INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (11163,1,1,NULL,12340),
	 (10304,1,0,'',12340),
	 (10324,1,1,'The buck hides are rugged and strong, making for very tough flesh - almost inedible, but we can use them for other purposes.',12340),
	 (10428,1,0,NULL,12340),
	 (10303,1,0,'There are too many of them... We must whittle them down or else the survivors will have no chance against them.',12340),
	 (10072,1,0,NULL,12340),
	 (10073,0,0,'Have you mastered Corruption?',20886),
	 (10166,1,0,'You''ve returned, haven''t you done enough?',12340),
	 (10302,1,1,'I am working on a solution I think may be effective with the strange creatures. I just need more time.',12340),
	 (10067,1,0,'Have you begun to clear the fouled water spirits?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (10068,1,0,NULL,12340),
	 (10069,1,0,NULL,12340),
	 (10070,1,0,NULL,12340),
	 (10071,1,0,NULL,12340),
	 (10064,1,0,NULL,12340),
	 (10065,1,0,'Have you managed to clear some of the ravagers in the area?',12340),
	 (10066,1,0,'Have you managed to clear any of the mutated tanglers?',12340),
	 (9877,1,0,NULL,12340),
	 (10063,1,0,NULL,12340),
	 (9799,6,6,'Hello, $c.  Do you have those flowers yet?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9811,1,0,'You seek audience with me?  I do not recall hearing of an appointment. ',12340),
	 (9798,6,6,'What have you got there?',12340),
	 (9758,1,0,NULL,12340),
	 (9759,1,0,NULL,12340),
	 (9760,1,0,NULL,12340),
	 (9761,1,0,'Do you see any unusually brave and powerful draenei around here?',12340),
	 (9762,1,0,NULL,12340),
	 (9779,6,6,'Back so soon? Have you found the missive?',12340),
	 (9756,1,0,'Do not return until you have succeeded!',12340),
	 (9749,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9751,1,0,NULL,12340),
	 (9753,1,0,NULL,12340),
	 (9748,5,5,'Don''t drink the water, $N!',12340),
	 (9741,1,0,'Void critters grow into void anomalies. Truth be told, we really don''t know what these creatures are... the name is more of a classification.',12340),
	 (9746,1,0,'Their leader can''t hide from us forever. We will systematically eliminate every possible hiding place until Sironas is found.',12340),
	 (9711,1,1,'A soldier of Matis'' stature won''t be traveling alone. Be careful out there.',12340),
	 (9740,1,0,'You must take out their portal controllers before you can destroy the gate itself!',12340),
	 (9703,6,6,'Was the information accurate?',12340),
	 (9704,1,0,NULL,12340),
	 (9705,1,0,'What did you find, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9706,6,0,'What have you got there, $N? Is that a journal?',12340),
	 (9699,1,6,'Well?',12340),
	 (9700,1,0,'I''ve been hearing reports of strange creatures appearing in the area. Whether they are mutated indigenous animals or true void anomalies is something that you need to find out.',12340),
	 (9698,1,0,'<Velen smiles.>$B$BGreetings, $N. I have been expecting you.',12340),
	 (9696,1,0,'I''m a bit busy here, agent $N. This better be important. ',12340),
	 (9694,1,1,'There are so many of them that I cannot help but think that they are somehow multiplying.',12340),
	 (9687,1,1,'The dragon wars have long since passed. All that remains are bones and the agitated remnants of Ysera''s brood.',12340),
	 (9688,1,0,'It pains me to watch. Please, let us not speak of this any further.',12340),
	 (9689,1,0,'I recommend that you bring allies, $N.',12340),
	 (9693,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9683,1,0,'Atoph must be lured out!',12340),
	 (9682,1,1,'Do not mourn their demise, $N.',12340),
	 (9672,1,0,NULL,12340),
	 (9674,1,1,'They''re nasty creatures...',12340),
	 (9668,1,0,NULL,12340),
	 (9669,1,1,'It was a terrible mess... ',12340),
	 (9670,6,6,'Any luck?',12340),
	 (9671,1,0,NULL,12340),
	 (9667,1,0,'I don''t have much longer, $N. They will kill me soon...',12340),
	 (9643,1,1,'Did you manage to get the constrictor vines?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9646,1,1,'How can I help you, $c?',12340),
	 (9647,1,0,'Have you culled the moths?',12340),
	 (9648,1,1,'Remember, the mushrooms I requested are each unique to the different environments of Bloodmyst.',12340),
	 (9649,1,1,'Back so soon?',12340),
	 (9663,5,5,'This is no time to relax!',12340),
	 (9666,1,6,'Is it done?',12340),
	 (9642,1,0,'If you have more of the irradiated crystal shards, I''d be happy to exchange them for another of my crystals.',12340),
	 (9641,1,1,'Have you gathered crystal shards from the creatures of Bloodmyst?',12340),
	 (9634,1,1,'We must act before the ravager displaces Bloodmyst Isle''s native predators. Have you begun culling the ravager population?',12340),
	 (9633,1,0,'Welcome to Auberdine, friend. What brings you to Darkshore?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9632,1,0,'Greetings, $c. What have you there? ',12340),
	 (9629,1,0,'Did the device work? Have you marked the murlocs for my research?',12340),
	 (9625,1,0,NULL,12340),
	 (9628,1,0,'Were you able to find out what was keeping the survey team from returning?',12340),
	 (9612,1,0,NULL,12340),
	 (9616,6,6,'Yes? I''m very busy, $N.',12340),
	 (9620,1,0,NULL,12340),
	 (9622,1,0,NULL,12340),
	 (9623,1,0,'<Torallius adjusts his eyepatch to look at you.>$B$BThis is the best we can offer the Hand of Argus?',12340),
	 (9624,1,1,'The sand pears are getting harder to find and, of course, that means less pie and fewer treats for the elekk here. Were you able to gather all the fruit I''ll need?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9606,1,0,'Welcome back, $N. Was Nurguni able to gather everything on the list? ',12340),
	 (9602,5,5,'You have returned!',12340),
	 (9603,1,0,'Good day, $N. Are you interested in renting a hippogryph?',12340),
	 (9604,1,0,'Greetings, friend. You look like you''ve come a long way. How can I help you?',12340),
	 (9605,1,0,'Where are you headed, $C?',12340),
	 (9580,1,1,'How goes the hunt, $N?',12340),
	 (9581,1,1,'Were you able to gather the first crystal sample?',12340),
	 (9584,1,1,'Do you have the second crystal sample?',12340),
	 (9585,1,1,'Have you returned with the last sample for my set?',12340),
	 (9594,1,0,'Yes, $C? What is it you have there?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9579,1,0,'<Morae looks at you hopefully.>$B$BDid your search turn up any trace of Galaen?',12340),
	 (9574,1,1,'Were you able to get the samples I need?',12340),
	 (9576,1,0,'What is it you have there?',12340),
	 (9578,1,0,NULL,12340),
	 (9569,1,1,'<Vindicator Aalesia seems to look through you rather than at you, her mind fixed on dealing with the satyr.>$B$BHave you moved against the satyr leader as I have asked?',12340),
	 (9570,1,0,'<Kurz grunts at you.>',12340),
	 (9571,1,0,'Hello, hero!',12340),
	 (9573,1,0,'Is the task complete?',12340),
	 (9566,1,0,NULL,12340),
	 (9567,1,1,'Were you successful in obtaining knowledge of the Nazzivus satyr?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9560,0,0,'They are ugly little creatures. Even the Blind Watcher could see them... and he''s blind.',12340),
	 (9561,1,0,NULL,12340),
	 (9562,0,0,'A murloc kicked me in the behind and spit on me... in broad daylight!',12340),
	 (9564,6,0,'Is that what I think it is?',12340),
	 (9565,1,0,NULL,12340),
	 (9549,1,1,'Do you have those samples for me to send back to Ironforge?',12340),
	 (9550,1,0,'Perhaps this old journal is what the map is referencing.',12340),
	 (9557,1,0,'The Light shine upon you in all your endeavors, $c. What is it you have there?',12340),
	 (9559,1,0,NULL,12340),
	 (9548,1,1,'Did you manage to find my equipment?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9540,1,0,NULL,12340),
	 (9541,1,0,NULL,12340),
	 (9542,1,0,NULL,12340),
	 (9544,1,0,'[Furbolg] So the prophecy of Akida is true... A hero has been delivered to us.',12340),
	 (9538,1,0,'You can hear a low-pitched hum emanating from the totem.',12340),
	 (9539,1,0,NULL,12340),
	 (9528,1,0,'Hail, $N.',12340),
	 (9530,1,1,'I love it when a plan comes together...',12340),
	 (9531,1,1,'That traitor is going to wish he never messed with Alliance Naval Command!',12340),
	 (9537,6,6,'Did you find the lying dog?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9523,25,25,'Don''t come back without some ancient relics.',12340),
	 (9527,1,1,'My wife was named Thalrisa and my daughter, Magwin.',12340),
	 (9513,1,0,'You do a good thing for my people, $N.',12340),
	 (9514,6,6,'You''ve found something?',12340),
	 (9515,1,0,'Remain vigilant!',12340),
	 (9512,1,1,'Arrr... Yarr... Shiver me timbers... Er, sorry $g lad:lass;, I gotta practice me pirate lest I forget it...',12340),
	 (9463,1,1,'I fear that her health is in steady decline.',12340),
	 (9473,1,1,'Do not waste time, $g boy:girl;.',12340),
	 (9505,1,0,NULL,12340),
	 (9506,6,6,'Any luck, stranger?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9454,1,1,'The stag hides are frail which tend to make for tender, succulent flesh.',12340),
	 (9455,6,6,'You found what? Where?',12340),
	 (9456,1,0,'We can''t risk this contamination spreading. The reports I''ve heard come from Blood Watch are bad enough. This has to be stopped now!',12340),
	 (9453,6,6,'What do you think of my armor? Crafted it myself! It''s a little different than what we''d traditionally wear but extremely comfortable.',12340),
	 (9452,1,1,'Watch out for murlocs: Strange and extremely annoying little creatures.',12340),
	 (9395,1,0,NULL,12340),
	 (9409,6,6,'Hello, $c.  What have you there? Is it for me?',12340),
	 (9371,1,0,'',12340),
	 (9394,1,0,NULL,12340),
	 (9369,0,0,'Have you harvested the necessary moth blood for the healing crystals yet? With survivors scattered all over the vale, time is of the essence!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9363,1,0,NULL,12340),
	 (9360,1,0,'What do you want to show me?',12340),
	 (9359,1,0,'',12340),
	 (9358,1,0,NULL,12340),
	 (9352,1,0,'Have you uncovered anything? Are the night elves behind this?',12340),
	 (9329,1,0,'I know it seems strange, but the Forsaken are here to help. You should speak with their leader, High Executor Mavren. He''s in the tower on the west side of town.$B$BAnd, $C, when you''re done talking with him return to me; I have something dire that needs to be dealt with immediately!',12340),
	 (9327,1,0,NULL,12340),
	 (9328,1,0,'You seek audience with me, $c?  I do not recall hearing of an appointment.',12340),
	 (9315,1,5,'A nerubian leader? None of the scouting missions reported anything about this Anok''suten!',12340),
	 (9312,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9313,1,0,'',12340),
	 (9314,1,0,NULL,12340),
	 (9311,1,0,'Then it is true... a scouting party of blood elves here in Ammen Vale! How did they follow us?$B$BI''ll get someone out there immediately to bring Tolaan back.',12340),
	 (9309,1,0,'',12340),
	 (9305,1,1,'When we have those spare parts, I know that we''ll get this emitter repaired. With any luck there will be someone else out there left to talk to.',12340),
	 (9303,1,1,'The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.',12340),
	 (9283,1,0,'We''ll survive this yet with your help.',12340),
	 (9293,1,1,'I''ll need all of the samples in good condition if we''re to have a chance of cleansing the lake.$B$BWe don''t have much time, $c!',12340),
	 (9294,1,0,'The sooner you disperse the agent at the lake, the fewer native creatures that will be mutated by drinking the water, including ourselves!$B$BI''m sorry that we can''t do anything to help the poor creatures that have already been infected. If only my lab equipment were intact.',12340),
	 (9279,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9280,6,6,'$N, have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!',12340),
	 (9281,1,0,'Did you take care of the business we discussed, $N?',12340),
	 (9282,1,0,NULL,12340),
	 (9275,1,6,'Isn''t this exciting? I really do take great pride in my work; I hope you appreciate it, $c.$B$BSo, I trust that you have ''seasoned'' the food at the troll camps in Zeb''Nowa?',12340),
	 (9276,1,6,'How are you doing with the attack on Zeb''Tela?',12340),
	 (9277,1,6,'Is your assault on Zeb''Nowa complete already?',12340),
	 (9278,1,0,'Greetings! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (9274,1,0,'You''ve done what I asked of you, $N?',12340),
	 (9219,1,0,'You''ve procured more spinal dust? I can use as much of it as you bring me.',12340),
	 (9220,1,0,'Have you returned from Deatholme victorious, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9252,1,0,'We will prevail, $N.',12340),
	 (9253,1,0,NULL,12340),
	 (9254,1,0,NULL,12340),
	 (9255,1,0,'You''ve something for me?',12340),
	 (9256,1,0,NULL,12340),
	 (9258,1,0,NULL,12340),
	 (9214,6,6,'Have those weapons yet? With the Shadowpine numbers decimated we''ll finally be able to turn our attention to the fight against the Scourge.',12340),
	 (9215,6,6,'What is that awful smell?',12340),
	 (9216,1,0,'Do you have the zombie hearts I requested, $N?',12340),
	 (9217,1,0,'You''ve brought more ghoul hearts? I can use as many as you can collect, $n.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9218,1,0,'Do you have the samples I requested, $N?',12340),
	 (9193,1,0,'This is a most grim and undignified business, I trust that you will complete this task to milady''s complete satisfaction? ',12340),
	 (9199,1,0,'I don''t have to remind you that we can ill afford this trouble with the troll dead rising in our very backyard! We have enough trouble with Deatholme to the south!',12340),
	 (9207,6,0,'How may I help you? ',12340),
	 (9212,1,6,'You''re the one that rescued my ranger?',12340),
	 (9173,1,6,'I trust that you return to me with news that Windrunner Spire has been cleansed of its Scourge infection?',12340),
	 (9174,1,0,'Has Aquantion been destroyed yet? ',12340),
	 (9175,6,0,'What''s that you have there? ',12340),
	 (9176,1,0,'Have you recovered the crystals yet?',12340),
	 (9192,1,6,'Is it good news, or bad, darling?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9172,1,0,'You wish to speak to me?',12340),
	 (9171,1,0,'I believe I can hear the dame''s belly rumbling even from here!  I take it that you are here talking to me because you have what I asked you to obtain?',12340),
	 (9170,1,0,'Have you succeeded in severing the Scourge''s chain of command, $N? Are Dar''Khan''s lieutenants dead?',12340),
	 (9169,1,6,'Is it over then, $c? Did you deactivate the night elf moon crystal at An''owyn?',12340),
	 (9166,1,0,'Oh, thank goodness for you! ',12340),
	 (9167,1,0,'Is it done, then?  Has Dar''Khan been destroyed?',12340),
	 (9164,1,0,'What became of the prisoners in Deatholme? Have you ventured there yet?',12340),
	 (9163,6,6,'How fare our efforts to uncover the night elf plot on Shalandis Isle, $c?',12340),
	 (9162,1,0,'Tell me, $N, what did you find out?',12340),
	 (9160,1,6,'$C. what word do you bring concerning An''daroth and what the night elves were up to there?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9161,1,0,NULL,12340),
	 (9157,1,0,'Have you obtained the medallions? The drowned still haunt this lake! ',12340),
	 (9158,1,0,'Have you completed the task I asked of you, $N?',12340),
	 (9159,1,0,'Have you completed the task I asked of you, $N?',12340),
	 (9155,0,0,'Are you done with your task yet?',12340),
	 (9156,1,0,'You have something to show me?',12340),
	 (9149,1,0,'Have you obtained the specimens I asked of you, $N?',12340),
	 (9150,1,0,'Did you obtain the essences, $N?',12340),
	 (9151,1,0,NULL,12340),
	 (9152,1,0,'Just as soon as I get the rest of my supplies. I''ll be open for business. The forces here aren''t going to get very far if they can''t purchase what they need to ply their trades.$B$BWar zones can be such profitable places, wouldn''t you agree, $c? Now, did you manage to fight your way to my cart through all of those ghouls?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9144,1,0,NULL,12340),
	 (9145,1,0,'',12340),
	 (9146,1,0,NULL,12340),
	 (9147,1,0,'Well? Did you bring me what I need? Hurry, or the pretty Blood Elf boy is a goner!',12340),
	 (9148,1,0,'You have the letter?',12340),
	 (9140,6,6,'$C, has Windrunner Village been liberated? Those damned magisters at the Sanctum of the Sun have been berating me to get their hands on those Scourge remnants I asked you to gather.$B$BDon''t worry about that, though. You take your time and get the job done right. I''ll deal with the magisters.',12340),
	 (9143,6,6,'You get those troll ears yet?$B$BYou know, if we could get some help from Tranquillien every once in a while this wouldn''t be such a problem. I''m just glad that you''re here.',12340),
	 (9139,1,0,'I''ve learned much about fighting the Scourge in the time that I''ve been here. They can be beaten back, but it must be done in small steps. The obscene manner in which they can take your fallen and add them to their own ranks as the newly risen makes it imperative that you make no mistakes along the way.$B$BNow, how goes the fight against Goldenmist Village?',12340),
	 (9130,6,0,'Yes. what''s this?',12340),
	 (9133,1,0,'That''s quite a list you have there, friend. Let me take a look at it.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9134,6,0,'Wow, that box of goods you have there looks heavy! You want to load that up on one of my flying beauties?',12340),
	 (9135,6,0,'$C, back so soon?  Are those the goods that I sent you for?  Doesn''t look like it could possibly be everything that I asked for!',12340),
	 (9138,1,0,'With your aid we''ll get the Scourge problem contained, $c. Dar''Khan will be dealt with!$B$BHave you handled the nerubian problem at Suncrown Village yet?',12340),
	 (9119,1,0,NULL,12340),
	 (9076,1,0,'Well, do you have his head or not?  I''ve no time to waste, $N.',12340),
	 (9064,1,0,'What calls for this interruption to my lecture, $C?',12340),
	 (9066,1,0,'Did you do what I asked of you, $N?',12340),
	 (9067,6,6,'Didn''t I just send you out to gather up more party supplies?  Was that you?  Oh, I can''t be expected to remember everyone''s face, now can I?  I meet so many... interesting people.$B$BWhat is it that you want?',12340),
	 (8895,1,0,'Yes, $C?',12340),
	 (8896,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (9035,1,0,NULL,12340),
	 (9062,1,0,'No luck? Well, keep looking. The book is of utmost importance, $C.',12340),
	 (8894,1,6,'Have you taken care of it then? Did you deal with a good number of those magical anomalies? What would I do if Magister Duskwither were to reappear with all of these things lurking about?',12340),
	 (8892,1,0,'Did you teach those Wretched a lesson?',12340),
	 (8888,1,0,'',12340),
	 (8889,6,6,'I can''t be certain from this distance... have you already shut down the power to Duskwither Spire?',12340),
	 (8890,1,0,NULL,12340),
	 (8891,1,0,'What''s this? It looks familiar. Oh no, this journal... my investigations... this is what caused all of this in the first place.',12340),
	 (8887,6,0,'Hello, $c, you''re a sight for sore eyes. I know, it''s crazy for me to be here, what with the anchorage overrun by the Wretched. Velendris and his rangers have sworn to protect me on the condition that I get out of here as soon as I''ve recovered my cargo.$B$BWhat''s that you have there... it looks vaguely familiar?',12340),
	 (8885,6,6,'You are the instrument of my success and revenge!$B$BHave you the ring? ',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (8886,6,6,'I am grateful for the assistance of someone like you, $N. It almost puts a smile on my face. But then I realize what these monsters have done to my ship and what''s happening to Quel''Thalas.$B$BHave you managed to retrieve any of my cargo?',12340),
	 (8884,6,6,'We rangers of the Farstrider Retreat are dedicated to setting right the damage that has been wreaked upon our fair lands. We will go to any length to do so.$B$BI trust that you have returned with the murloc heads I tasked you to gather? ',12340),
	 (8488,1,0,NULL,12340),
	 (8490,1,0,'Have you succeeded in powering the runestone yet, $N?',12340),
	 (8491,1,0,'You''re back. Did you bring the pelts?',12340),
	 (8547,1,0,'Greetings!  It is a pleasure to meet you!$B$BI see you have a special voucher.  Give it to me and I will offer you something in exchange.',12340),
	 (8480,1,0,'Did you gather the lost weapons yet?',12340),
	 (8482,1,0,'You''ve got something for me? Let me take a look.',12340),
	 (8483,1,0,'Did you take care of the intruder?',12340),
	 (8486,1,0,'Did you take care of the arcane wraiths?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (8487,1,0,'Are you done collecting the samples I asked for, $N?',12340),
	 (8477,1,0,'You''ve brought me Otembe''s hammer? ',12340),
	 (8479,1,0,'You bring me Zul''Marosh''s head?',12340),
	 (8476,1,0,'You''ll find Tor''Watha and Zeb''Watha southeast of here. Come back when you''ve killed the trolls.',12340),
	 (8350,2,0,'Welcome to my inn, $C.  Am I to understand that you have something for me?',20886),
	 (8463,1,0,'Did you retrieve the stolen goods yet?',12340),
	 (8468,1,0,'You have something to show me?',12340),
	 (8472,1,0,'Have you succeeded in gathering the arcane cores yet, $N?',12340),
	 (8473,1,0,'I dread to ask, $N... is the task done?',12340),
	 (8474,1,0,'You have something to show me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (8475,1,0,'You''re back, $N. Did you fight off the undead along the Dead Scar yet?',12340),
	 (8347,1,0,NULL,12340),
	 (8346,1,25,'Ah $N. Have you completed your task?',12340),
	 (8345,1,6,'Have you read the plaque on the shrine then, $c?',12340),
	 (8338,6,0,'From your demeanor, you seem to be on a matter of some urgency.  Is there something specific I can assist you with?',12340),
	 (8336,1,0,'Many of the creatures here on the isle were at one point bound into non-aggression and complacency by our magical skills.  When the Scourge destroyed the Sunwell, our hold over these creatures shattered.  Arcane slivers are the remnants of the control we once had, and as such might be usable in fashioning a new device to aid us in regaining their control.$B$BBetter still, perhaps the slivers could be used to see what malaise the isle truly suffers under...',12340),
	 (8334,1,25,'It is better you learn about survival - and the costs of survival - now rather than later. Making hard choices is something you''re going to have to get used to as a blood elf.$B$BNo one was there for us when the Scourge ripped our home in two. It was us and us alone who pulled ourselves up by the bootstraps.',12340),
	 (8335,1,0,'Heed well this warning - Felendren the Banished is only a symptom of a much larger problem.  His demise will solve our immediate concerns, but all blood elves share the potential same fate as him if we let our addictions get the best of us.',12340),
	 (8327,1,0,NULL,12340),
	 (8330,6,1,'Have you had a chance to find my belongings?  Once we reassert our dominance over Sunstrider Isle, I will need them in my work.  For now though, I must maintain my watch over the Sunwell... or what remains of it.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (8326,1,0,'It gives me no pleasure to ask you to destroy these beasts.  While in times past we have lived in relative harmony with woodland creatures, these are different times.  The first order of business for all sin''dorei is survival; make sure you remember that.',12340),
	 (7922,1,0,NULL,12340),
	 (7923,1,0,NULL,12340),
	 (7924,1,0,NULL,12340),
	 (7925,1,0,NULL,12340),
	 (8291,1,0,NULL,12340),
	 (8292,1,0,NULL,12340),
	 (8293,1,0,NULL,12340),
	 (8294,1,0,'The blood of our enemies is a mark of honor. Do you have such a mark?',12340),
	 (8325,1,0,'Our work in rebuilding our society begins here, $N. Once we are able to secure our home, we can look outward and upward.',12340);
