INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7871,1,0,NULL,12340),
	 (7868,1,0,NULL,12340),
	 (7867,1,0,NULL,12340),
	 (7866,1,0,NULL,12340),
	 (7865,1,0,NULL,12340),
	 (7864,1,0,NULL,12340),
	 (7863,1,0,NULL,12340),
	 (7862,1,6,'Are you here about the job opening?',12340),
	 (7861,1,6,'Do you bring news from Jintha''alor?',12340),
	 (7850,1,1,'Be cautious in battling the Vilebranch, $N. Their minds are clouded - they fight to the death.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7848,1,0,'You must attune your soul with the Molten Core before access is granted.',12340),
	 (7849,1,1,'When I have his remains, I shall take them to Yayo''jin and have them prepared for a proper burial.',12340),
	 (7845,1,0,'',12340),
	 (7846,1,0,'You must hurry!',12340),
	 (7847,1,0,'',12340),
	 (7840,0,0,'<Lard rubs his enormous belly.>$B$BLard so hungry.',12340),
	 (7841,1,0,'You be too clean, mon. You gotta mix it up - get down and dirty with the enemy.',12340),
	 (7842,0,0,'The last message gonna scare them off for sure. Either that or make them very, very angry.',12340),
	 (7843,1,6,'What''s the hold up, mon?',12340),
	 (7844,1,0,'The Vilebranch Soothsayers and Scalpers inhabit the north by northeast region of the Hinterlands.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7837,1,1,'Whenever you are ready to hand in the stack of runecloth, I''ll accept it.',12340),
	 (7838,1,0,'Avast Lubber! Bring me 12 trinkets of the Arena Master.',12340),
	 (7839,1,1,'Watch out for the Vilebranch trolls of the region, $N. They are ruthless, murderous filth.',12340),
	 (7836,1,1,'$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.',12340),
	 (7835,1,1,'Mageweave is running low, and we could use your help to replenish our stocks!  By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal.  Such generosity would not go unnoticed by the Darkspear Trolls, I assure you!$B$BIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7832,1,1,'Whenever you are ready to hand in the stack of runecloth, I''ll accept it.',12340),
	 (7833,1,1,'If you have the sixty pieces of wool cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7834,1,1,'As with most other fabrics, our stocks of silk are at an all-time low.  Our stores are such that we''d only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.$B$BA benevolent gift such as silk, might I add, would certainly increase your local standing in the community!  If you have the sixty pieces of silk cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7830,1,1,'The Razorbeak Skylord is a much rarer breed of gryphon: One responsible for mating and creating murderous offspring.',12340),
	 (7831,1,1,'Mageweave is running low, and we could use your help to replenish our stocks!  By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal.  Such generosity would not go unnoticed by Orgrimmar, I assure you!$B$BIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I''m able to take them from you now.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7828,1,5,'Show them the might of Revantusk!',12340),
	 (7829,1,0,'Clear your head of impure thoughts, $r. Become one with the wilds!',12340),
	 (7827,1,1,'As with most other fabrics, our stocks of silk are at an all-time low.  Our stores are such that we''d only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.$B$BA benevolent gift such as silk, might I add, would certainly increase your local standing in the community!  If you have the sixty pieces of silk cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7825,1,1,'Whenever you are ready to hand in the stack of runecloth, I''ll accept it.',12340),
	 (7826,1,1,'If you have the sixty pieces of wool cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7824,1,1,'$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.',12340),
	 (7823,1,1,'$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.',12340),
	 (7822,1,1,'Mageweave is running low, and we could use your help to replenish our stocks!  By counting on the community as a whole, we would only need a donation of 60 pieces of mageweave cloth from you to enable us to reach our goal.  Such generosity would not go unnoticed by Thunder Bluff, I assure you!$B$BIf you have the sixty pieces of mageweave cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7821,1,1,'As with most other fabrics, our stocks of silk are at an all-time low.  Our stores are such that we''d only need sixty pieces of silk from you total; we should be able to reach our goal with the support of others.$B$BA benevolent gift such as silk, might I add, would certainly increase your local standing in the community!  If you have the sixty pieces of silk cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7820,1,1,'We are currently accepting donations for wool cloth.  A donation of sixty pieces of wool cloth will net you full recognition by Thunder Bluff for your generous actions.  Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.$B$BIf you have the sixty pieces of wool cloth on you and are ready to donate them, I''m able to take them from you now.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7819,1,1,'Greetings once again, $N!  Our need for runecloth is constant, and we can always use additional resources if you are willing to part with them.  For an additional stack of twenty runecloth, I will make sure that you are recognized for your continuing efforts on behalf of the Undercity.$B$BWhenever you are ready to hand in the stack of runecloth, I''ll accept it.',12340),
	 (7815,1,6,'How goes the hunt?',12340),
	 (7816,6,6,'Did you get it yet?',12340),
	 (7817,1,1,'If you have the sixty pieces of mageweave cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7818,1,1,'$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.',12340),
