INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7800,1,1,'$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.',12340),
	 (7798,1,1,'A benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7796,1,1,'Whenever you are ready to hand in the stack of runecloth, I''ll accept it.',12340),
	 (7795,1,1,'$n, you''ve been a tremendous contributor to our cloth drive. As we work hard to replenish our reserves, one form of cloth remains critically low - runecloth. We are in absolutely dire need of it, and we hope that you will be able to help us as you have in the past!$b$bIf you are willing, please bring me what runecloth you can spare. We''ll initially accept a single donation of sixty, and then we''ll go from there.',12340),
	 (7794,1,1,'If you have the sixty pieces of mageweave cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7793,1,1,'A benevolent gift such as silk, might I add, would certainly increase your local standing in the community! If you have the sixty pieces of silk cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7792,1,1,'If you have the sixty pieces of wool cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7791,1,1,'If you have the sixty pieces of wool cloth on you and are ready to donate them, I''m able to take them from you now.',12340),
	 (7789,1,0,'The blood of our enemies is a mark of honor. Do you have such a mark?',12340),
	 (7738,6,0,'What''s this, $N - you''ve got something special for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7788,1,0,NULL,12340),
	 (7737,1,0,'You''ve worked your way up through the Brotherhood''s corporate hierarchy, $r. We have begun to look favorably upon you. Quite an accomplishment!$B$BIf you''re interested in more work and earning more respect amongst us, listen up.$B$BWe can refine the fiery flux by adding a simple Dark Iron residue to the mix. The Dark Iron residue can be found in Blackrock Depths.$B$BBring me all the Dark Iron residue you find!',12340),
	 (7736,1,1,'Let''s not waste more of my precious time with jibber jabber, $r. It''s time to focus on replenishing our dwindling fiery flux supply.$B$BWhat I''m gonna need from you is the following:$B$B*Incendosaur scales.$B$B*Kingsblood.$B$B*Coal.$B$BI''ll take all that you can offer!$B$BAnd you''ll do it fast if you wanna get in good with the Brotherhood.',12340),
	 (7735,6,0,'What''s this, $N - you''ve got something special for me?',12340),
	 (7734,5,5,'If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!$B$BImagine that!',12340),
	 (7733,5,5,'If these Rage Scar yeti hides are anything like the quality displayed by their Feral Scar counterparts, they could very well be as resilient as thorium!$B$BImagine that!',12340),
	 (7732,0,0,'Greetings friend... you look as though you are on urgent business.  Is there something I can help you with?',12340),
	 (7731,6,6,'Have you managed to bring down Stinglasher yet?',12340),
	 (7729,1,1,'We''re gonna need to weigh you with and without clothes to be sure.',12340),
	 (7730,6,6,'How goes the hunt, $N?  Are you here to report your success?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7728,1,1,'If you''re here for the reward, you''re gonna have to give me the stolen goods.',12340),
	 (7727,1,0,'<Hansel is busily rubbing his bunions.>$B$BDon''t just stand there, grab some oil and a luffa and get to scrubbin'' these bunions.$B$BYe don''t have a luffa? Well then! Perhaps it''s time I sent you out to find a luffa?$B$BHey, where are ye goin''?',12340),
	 (7726,6,6,'Have you managed to find the elemental cores I need?',12340),
	 (7722,6,6,'Did you find the plans?',12340),
	 (7723,1,6,'Did ye pound ''em?',12340),
	 (7724,1,6,'Was he right? Does it come out their rumps?',12340),
	 (7725,6,6,'Ah, the fruits of research and utilization in the form of sweet, sweet residue.  Well, that is to say, I don''t taste it or anything when I study it.$B$BMuch.',12340),
	 (7678,1,0,NULL,12340),
	 (7701,34,34,'Can''t ya shee I''m bushy? What *hic* ish it ya be wantin? *hic*',12340),
	 (7703,1,0,'Hah, you no find it, do you boss? Maybe old timey story a bad story... hard to believe that creepy elf can steal from Gordok king!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7721,6,6,'While I could bore you with the technical details of the utility behind elemental cores, I will instead tempt you to completion of this important task by offering valuable coin and prizes for doing so.  Yon verily, are you finished?',12340),
	 (7676,1,0,NULL,12340),
	 (7677,1,0,NULL,12340),
	 (7671,1,0,NULL,12340),
	 (7672,1,0,NULL,12340),
	 (7673,1,0,NULL,12340),
	 (7674,1,0,NULL,12340),
	 (7675,1,0,NULL,12340),
	 (7666,1,0,'',12340),
	 (7667,1,0,'I feel awkward asking for material assistance, but my divination scryer - the device I hope to finish - requires one of each. If you cannot help me, I''d certainly understand.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7665,1,0,'You bring me your old raptor, I give you new one with freshly sharpened claws!  The new raptor will be just as fast as your old one, but with a new look to him.   You can look at the swift raptors here to see what you will have to choose from.',12340),
	 (7664,1,0,'You bring me your old raptor, I give you new one with freshly sharpened claws!  The new raptor will be just as fast as your old one, but with a new look to him.   You can look at the swift raptors here to see what you will have to choose from.',12340),
	 (7663,1,0,'If you bring me your aging kodo, I will trade it in for one from the new herd.   The new kodo will be just as fast as your old one, but have a different look to it.   You can look at the great kodos we already have around the yard here to see what you will have to choose from.',12340),
	 (7662,1,0,'If you bring me your aging kodo, I will trade it in for one from the new herd.   The new kodo will be just as fast as your old one, but have a different look to it.   You can look at the great kodos we already have around the yard here to see what you will have to choose from.',12340),
	 (7661,1,0,'If you bring me your old fast wolf, I will trade it in for one from the new pack.   The new wolf will be just as fast as your old one, but have a different look to it.   You can look at the swift wolves we already have around the yard here to see what it will look like.',12340),
	 (7659,1,1,'For the shoulder plans, I''ll be needin'' 10 thorium bars.',12340),
	 (7660,1,0,'If you bring me your old fast wolf, I will trade it in for one from the new pack.   The new wolf will be just as fast as your old one, but have a different look to it.   You can look at the swift wolves we already have around the yard here to see what it will look like.',12340),
	 (7657,1,1,'Just hand over 25 thorium bars and the helm plans are yers.',12340),
	 (7658,1,1,'Just hand over 30 thorium bars and the leg plans are yers.$B$BI know, I''m driving you into bankruptcy! I''ve heard it all before so you can save your sob story, weakling.',12340),
	 (7656,1,1,'For the chest piece plans, I''ll be needin'' 30 thorium bars.$B$BOh boy, there you go again. Are you gonna be runnin'' to yer blue Gods, askin'' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life''s fair.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7655,0,0,'For the bracer plans, I''ll be needin'' 10 thorium bars.$B$BAre you alright, sonny? Yer getting'' all red.',12340),
	 (7654,11,11,'For the boot plans, I''ll be needin'' 20 thorium bars. Yep, 20. Are you gonna cry? Would you like a hanky?$B$B<Derotain laughs.>',12340),
	 (7652,1,0,'',12340),
	 (7653,1,1,'For the belt plans, I''ll be needin'' 10 thorium bars.',12340),
	 (7649,1,0,'You have recovered a tome!',12340),
	 (7650,1,0,'You have recovered a tome!',12340),
	 (7651,1,0,'You have recovered a tome!',12340),
	 (7648,1,0,'You''re progressing along nicely, $N. Once you have made your barding, you''ll be well on your way to the next task.',12340),
	 (7647,1,0,'The spirit of the fallen charger looks upon you with a mournful gaze. Sad, almost hollow eyes look at you as though all hope was lost to it.',12340),
	 (7646,1,1,'You have come so very far, $N. Your final act of worldly-item sacrifice will be the genesis for one of your greatest accomplishments. I can feel it in the very fiber of my being!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7645,5,5,'Yes, I''ve proved you wrong now, haven''t I? I''ve proved them all wrong! I WAS RIGHT ALL ALONG!!!',12340),
	 (7644,6,6,'$N, you''re back! Were you able to successfully deal with Merideth Carlson and Tendris Warpwood?  Honestly, I''m not sure which one is a greater threat at times...',12340),
	 (7638,1,0,'',12340),
	 (7639,2,0,'Welcome back, $N. Have you acquired the exorcism censer?',12340),
	 (7640,6,6,'It is good to see you again $N. Is your work done in Terrordale?',12340),
	 (7641,1,0,'',12340),
	 (7642,6,6,'Ah, $C. I won''t be able to finish your barding without the things I mentioned. Have you gotten everything together?',12340),
	 (7643,1,0,'The Ancient Equine Spirit looks at you expectantly, as though it wants something from you.',12340),
	 (7637,1,0,'Greetings, noble $C! I have prepared my trusted censer with the freshest of incense and blessed it thrice for your use. Your donation will help us in Ironforge not only create a new censer, but also to bolster sagging reserves of food for our needy.',12340),
	 (7631,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7632,1,0,'<Vartrus groans.>',12340),
	 (7633,1,0,'',12340),
	 (7634,1,0,'Welcome back, young $C.',12340),
	 (7635,1,0,'I am certain that you will have little difficulty in finding and slaying a black dragon, $N. Do not waste my time with idle chatter.',12340),
	 (7636,1,0,'Do not be fooled by their disguises!',12340),
	 (7628,6,6,'Did you bring the dragonscales, $N? I don''t want to start on the candle until I have them... or I might blow up the whole camp!',12340),
	 (7629,6,6,'Have you been to the Scholomance, $N? Has the imp yet infused the parchment with the stardust?',12340),
	 (7630,6,6,'Do you have the arcanite, $N? Once I have it I can make you the black lodestone.',12340),
	 (7626,6,6,'You have those elixirs, $N? Mor''zul told me you need a Bell of Dethmoora, and making one of those takes a lot of shadow power!',12340),
	 (7627,6,6,'The Wheel of the Black March isn''t easy to make, and takes a lot of materials. Have you gathered them yet?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7623,1,0,'',12340),
	 (7624,15,15,'I can already taste the heart of Ulathek on my lips. So sweet is the flesh of a traitor...',12340),
	 (7625,6,6,'Have you been to Jaedenar, $N? Did you get the stardust from Lord Banehollow?',12340),
	 (7622,1,0,'',12340),
	 (7603,6,6,'Did you get lost?',12340),
	 (7604,1,0,'Do we have a deal?',12340),
	 (7621,1,0,'',12340),
	 (7583,6,6,'Hrm? Well?',12340),
	 (7601,1,0,'',12340),
	 (7602,1,0,'Don''t tell anyone this but Niby is daft.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7582,1,1,'The Hederine will not give up their precious gems without a fight, $N.',12340),
	 (7581,1,1,'Only the blood of Wildspawn satyr will suffice.',12340),
	 (7564,6,0,'You have something for me?  It''s not a big, juicy spider, is it?  Or maybe a roach?  I hope it''s still alive... I so love chewing on them when they''re still alive...',12340),
	 (7506,1,0,'You have recovered a tome!',12340),
	 (7507,1,0,'Ah, one of our greatest compilations. This one has been missing for ages.',12340),
	 (7508,1,0,'Excellent, let us begin...',12340),
	 (7509,1,0,'Perhaps one day, another will wield the prismatic blade.',12340),
	 (7541,1,0,'',12340),
	 (7562,1,0,'',12340),
	 (7563,6,6,'Have you seen the raging owl beasts, $N? The magic of those creatures is strong, and it concentrates in the blood that flows through their torturted forms.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7505,1,0,'You have recovered a tome!',12340),
	 (7503,1,0,'You have recovered a tome!',12340),
	 (7504,1,0,'You have recovered a tome!',12340),
	 (7502,1,0,'You have recovered a tome!',12340),
	 (7501,1,0,'You have recovered a tome!',12340),
	 (7500,1,0,'You have recovered a tome!',12340),
	 (7497,1,0,'',12340),
	 (7498,1,0,'You have recovered a tome!',12340),
	 (7499,1,0,'You have recovered a tome!',12340),
	 (7496,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7495,1,0,'By Uther''s beard!',12340),
	 (7494,1,0,'',12340),
	 (7493,1,0,'',12340),
	 (7492,1,0,'',12340),
	 (7491,1,0,'',12340),
	 (7490,1,0,'<Thrall''s stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>',12340),
	 (7489,6,0,'$N, do you have Lethtendris''s Web?',12340),
	 (7485,1,0,'My patience prevents your suffering.',12340),
	 (7486,1,0,'',12340),
	 (7488,6,6,'Do you have the web, $N?  Its concentrated magical energy must be dissipated!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7483,1,0,'What is it? I have much cataloguing to do!',12340),
	 (7484,1,0,'You again? What could you possibly want now?',12340),
	 (7463,1,0,'Yes? Do I know you?',12340),
	 (7481,1,0,'My associate, the night elf scholar, Runethorn, is recruiting her allies for this task.',12340),
	 (7482,1,0,'My associate, the night elf scholar, Runethorn, is recruiting her allies for this task.',12340),
	 (7462,1,0,'',12340),
	 (7441,1,0,'I regret nothing, stranger. The Queen has long since passed. The works of the Shen''Dralar have been marred by the madness of Prince Tortheldrin. I seek only freedom... Escape...',12340),
	 (7461,1,0,'Be wary, adventurer. The Prince is... persuasive.',12340),
	 (7425,1,0,'',12340),
	 (7426,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7427,1,0,'',12340),
	 (7428,1,0,'',12340),
	 (7429,1,0,'It''s called the Gordok Shackle Key - well, that''s what these "tons o'' fun" keep calling it. I think any of the ogres might have it, but I''m not sure if any specific ones do. Maybe the guards have a better chance of having one...$b$bWhat am I talking about - you have it already, don''t you?! Is that it there??!',12340),
	 (7401,1,0,'I deal in wholesale irony, soldier.',12340),
	 (7402,1,0,'',12340),
	 (7421,1,0,'',12340),
	 (7422,1,0,'',12340),
	 (7423,1,0,'',12340),
	 (7424,1,0,'',12340),
	 (7386,1,0,'There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf''s storm crystals.$B$BThe Circle accepts such offerings, $n.',0);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7367,1,0,NULL,12340),
	 (7368,1,0,NULL,12340),
	 (7381,1,0,NULL,12340),
	 (7382,1,0,NULL,12340),
	 (7383,1,1,'Along with the druids, the Oracle Tree and the Arch Druid have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.',12340),
	 (7385,1,0,'You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, $n.',0),
	 (7366,1,0,'Benedictus! I am but a speck in the shadow of his grandeur. Praise him!',12340),
	 (7364,1,0,'',12340),
	 (7365,1,0,'',12340),
	 (7361,1,0,'They seek to exterminate us? It is they who shall be exterminated.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7362,1,0,'I don''t care where the hair comes from, $R.',12340),
	 (7363,1,0,'Yes, it is true. My brother is a human. Shameful... A stain upon my nearly immaculate record.',12340),
	 (7342,5,5,'Can you believe this rubbish?! The last shipment of ammunition from Kharanos was botched! All we have for ammo now are these flimsy, good for nothing arrows! What in the world am I going to do with 500,000 thorium headed arrows?$b$bI''ll tell you what, kid. If you can bring me thorium shells, I''ll trade you thorium headed arrows - straight up! Deal?',12340),
	 (7301,1,0,'Anything I would care to hear?',12340),
	 (7302,1,0,'Status of the hunt, soldier?',12340),
	 (7321,6,6,'Any luck finding the ingredients?  I''ll tell you, the alliance maggots are far too numerous in this area now... In my opinion, they have come far too close already...',12340),
	 (7341,6,0,'Greetings, $r. I am Kolark, Bounty Hunter from Thunderbluff. Much of the world I have traveled and much I have seen.$B$BMy journeys across the South Seas led to the discovery of these wonderous thorium headed arrows. Alas, I have an endless supply of the arrows but have exhausted my supply of shells. Bah, no self respecting Tauren would ever be caught dead using a flimsy bow. The arrows are useless!$B$BI will offer a trade: An even exchange of thorium shells for my thorium headed arrows. Deal?',12340),
	 (7224,1,0,'How goes the hunting, $N. Do you have any armor scraps for me?',12340),
	 (7241,1,0,NULL,12340),
	 (7261,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7281,1,0,'How it must pain him to remain as one of the living while his beloved brother has ascended to perfection.',12340),
	 (7282,1,0,'It is with heavy heart that I give such an order, soldier.',12340),
	 (7172,5,5,'Let them hear your voice, Commander $N! Let them know fear. Show them what power the Stormpike holds in their rank!',12340),
	 (7181,1,0,NULL,12340),
	 (7201,5,5,'Show them to me!',12340),
	 (7202,1,0,NULL,12340),
	 (7223,1,0,'Did you bring any armor scraps, $N?',12340),
	 (7171,66,66,'Before me stands an exalted hero of the Alliance.$B$B<Lieutenant Haggerdin salutes.>$B$BFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!$B$BPresent your insignia.',12340),
	 (7170,6,6,'I must know, $n. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!$B$BYou have earned reverence among the Guard. Present your insignia!',12340),
	 (7169,5,5,'The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.$B$BPresent your insignia.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7168,1,1,'Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, $c. The time has come.$B$BPresent your insignia.',12340),
	 (7166,1,0,'Your radiate command and power, $C. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.$B$BRise, Hero of Frostwolf. Rise and be honored!$B$BPresent your insignia.',12340),
	 (7167,1,0,'Drek''Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.$B$BYou have earned the Eye of Command.$B$BPresent your insignia, Commander $N.',12340),
	 (7165,1,0,'So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.$B$BPresent your insignia.',12340),
	 (7164,1,0,'It is good to see you again, $C. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.$B$BYour time has come again, $N. You have earned a new ranking and as such, a new insignia denoting this rise in stature.$B$BPresent your insignia.',12340),
	 (7163,1,0,'<Warmaster Laggrond salutes you.>$B$BIt is your time, $N. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.$B$BWell done! Present your initiate''s insignia.',12340),
	 (7162,5,5,'Beware the harpies of the region, $C. They''ll not think twice to rip out your throat!',12340),
	 (7142,1,0,'',12340),
	 (7161,1,0,'Wake up! Wake up, $N! This is not a dream. You really are entrenched in the midst of a raging battle!',12340),
	 (7121,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7122,1,5,'You haven''t captured the mine yet, $N!$B$BAfter we control a mine, it will be much easier to gather minerals and supplies from it.',12340),
	 (7123,1,0,NULL,12340),
	 (7124,1,0,'You haven''t yet captured a mine, $N! Find one that we do not control and defeat it''s leader! ',12340),
	 (7141,1,6,'Go, $N.  Go to Alterac Valley and defeat the orc general!',12340),
	 (7082,1,0,'Attack a graveyard held by the Alliance!',12340),
	 (7101,1,0,'You haven''t yet assaulted a bunker, $N! Are you waiting for others to claim your glory?',12340),
	 (7102,1,5,'You haven''t yet assaulted a tower, $N! What are you waiting for?',12340),
	 (7081,1,5,'$N, you have not yet assaulted a graveyard. Return to me when this task is complete!',12340),
	 (7067,0,0,'What did you decide, $N? Can you help me? Will you set foot on holy ground to help me forge one great centaur tribe!?',12340),
	 (7068,0,0,'You find the crystals yet? Rituals of power, spells of great strength - those shadowshards maybe very helpful in all kind of arcane magics.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7070,6,6,'Have you made the trip yet? I realize it''d be quite dangerous, but if you were successful, it would very much be worth it.',12340),
	 (7066,1,0,'You have the scent of corruption on you, $N... much like many adventurers these days. But something about you is different. Is there something you''ve come to speak to me about? You have an aura about you that seems familiar, but I cannot place it.$B$BPlease, I implore you, tell me why you''ve sought an audience with me.',12340),
	 (7065,1,0,'I feel the weight of imposing my plea on the mortal races, but we are left with no other options. The races of Azeroth have proven without a doubt they can overcome such things when they work together, so it is to them I ask for help.$B$BI only hope it is enough.$B$BZaetar, brother to Remulos, brought many pains to this world, and ultimately it caused his own death. There is a lesson there to all of us if we are wise enough to see it.',12340),
	 (7064,1,0,'I would prefer to fight this battle on our own, but we are left with no other options--we need those more powerful, and the races of Azeroth have proven without a doubt they can overcome such things when they work together. So it is to you we turn for help.$B$BI only hope it is enough.$B$BZaetar, brother to Remulos, brought many pains to this world, and ultimately it caused his own death. I just hope I have not caused more death by asking you to aid us.',12340),
	 (7062,1,0,'',12340),
	 (7063,1,0,'I bid you welcome to the Kingdom of Ironforge, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?',12340),
	 (7044,1,0,'I have awoken from a nightmare that seemed it would never end...',12340),
	 (7045,1,0,'',12340),
	 (7046,1,0,'If you wish to restart the ritual, please abandon our first attempt and then speak to me again.',12340),
	 (7061,1,0,'I bid you welcome to Mulgore and our humble community of Thunder Bluff, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7041,1,1,'If you are able to heal the plant, it will again begin to grow. We must do what we can, $N...',12340),
	 (7042,1,0,'',12340),
	 (7043,1,0,'$N - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...',12340),
	 (7029,1,1,'If you are able to heal the plant, it will again begin to grow. We must do what we can, $N...',12340),
	 (7028,25,25,'Don''t ask questions!$B$BYou have my request.',12340),
	 (7027,1,0,'Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!',12340),
	 (7026,1,0,'The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.$B$BWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.$B$BYou must strike at our enemy''s base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!',0),
	 (7024,1,0,NULL,12340),
	 (7025,1,0,'All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...',12340),
	 (7022,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (7023,1,0,NULL,12340),
	 (7021,1,0,NULL,12340),
	 (7003,6,6,'Miniaturization residue, I assure you, is a valuable commodity when it comes to engineering!  Well, it is valuable in that it helps me make sure the zapper won''t do something as disappointing as explode on the user.$B$BOh, I mean for the zappers other than the one I gave you.  Absolutely!',12340),
	 (7002,1,0,'While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.$B$BYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!$B$BSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!',0),
	 (6984,1,0,'',12340),
	 (6985,1,0,'Did you enter the Irondeep mine, $N? Did you raid its supplies?',12340),
	 (7001,1,0,'Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!',12340),
	 (6983,5,0,'$N - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...',12340),
	 (6963,1,0,'',12340),
	 (6964,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6981,2,0,'Hello, $R. What can I do for you?',12340),
	 (6982,1,0,'Have you been to the Coldtooth mine, $N? Do you have the supplies I asked for?',12340),
	 (6961,1,0,'',12340),
	 (6962,1,0,'All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...',12340),
	 (6943,1,0,'Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.$B$BReturn to the battlefield and strike at the heart of the Frostwolf''s command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!',12340),
	 (6942,1,0,'My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.$b$bThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.$b$bOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!',12340),
	 (6922,1,0,'Ah, hello again $N.  I was just reading the waves the sea, much like I always do.  What brings you to the outpost?',12340),
	 (6941,1,0,'The elite Frostwolf units that guard the lines must be dealt with, soldier! I''m tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I''ll deploy the air strike.',12340),
	 (6901,1,0,NULL,12340),
	 (6921,6,6,'Have you been successful in locating the fathom core?  Without it we''ll have no idea what the Twilight''s Hammer is exactly up to down there.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6847,1,0,NULL,12340),
	 (6848,1,0,NULL,12340),
	 (6861,1,0,NULL,12340),
	 (6862,1,0,NULL,12340),
	 (6881,1,0,'The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.$b$bThe damage has grown too great for the Circle to control! Ivus must be called to our aid.$b$bThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, $n!',12340),
	 (6845,1,0,NULL,12340),
	 (6846,1,0,'My troops are supplied and ready to assault.  We just need orders from Noreg Stormpike and I''ll send them into the fray!',12340),
	 (6844,1,0,'Why, hello there! Hrmm...$b$bLet me be a little honest with you, friend... you smell a bit ripe. Whiffy, one might say. Now I''m not making a personal assailment of your being. I''m just saying... in the future, you may want to freshen up a little after coming in from the field. It will make those first impressions a little more positively impressionable!$b$bAnyhoo... what can I do for you?',12340),
	 (6827,1,0,'I was locked up in a dwarven hellhole for days. You better believe I want revenge!$b$bWe must plan carefully.$b$bFirst, my war riders need targets to gun for - high priority targets. I''m going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You''ve definitely got your work cut out for you.',12340),
	 (6826,1,0,'You''ve worked hard, $n, but we have only just begun!$b$bMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!$b$bMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.$b$bMake haste, soldier!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6825,1,0,'We must prepare the new fleet of War Riders, $r! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.$b$bI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!',12340),
	 (6823,1,0,'',12340),
	 (6824,1,0,'Have you defeated Lucifron and the others, $N?  Do you have the hands of the enemy?',12340),
	 (6822,1,0,'Your success in the Molten Core awaits, $N.',12340),
	 (6821,1,0,'Do you have the Eye, $C?  Do you have the strength to enter Blackrock Spire?',12340),
	 (6804,0,0,'Do you have the bracers?',12340),
	 (6805,1,0,'Cowardice is not a thing we hold in regard, $c.  Go to Silithus and prove your bravery.',12340),
	 (6801,1,0,'I come from Thunder Bluff, $r. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.$b$bBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.$b$bVictory will be assured when the elemental lord is loosed upon the Stormpike army.',12340),
	 (6781,1,0,'$N, we need more armor scraps to supply our troops!',12340),
	 (6762,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6761,1,0,NULL,12340),
	 (6722,1,0,'',12340),
	 (6741,1,0,'I need more armor scraps, $N! Do you have any?',12340),
	 (6721,1,0,'',12340),
	 (6701,1,0,'We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It''s impossible to kill them off fast enough to have any noticeable impact on their population!$B$BWe''ve found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is ''dealt'' with internally.$B$BPick their pockets clean and turn the emblems in to me or one of the other guards.$B$BStart at Durnholde, south of here.',12340),
	 (6681,1,0,'Did you meet Milton?<Fahrad laughs.>',12340),
	 (6662,0,0,'<Nipsy puts his index finger through one of the air holes in the carton.>$b$bAlive and kicking... and just in time!',12340),
	 (6661,5,5,'Yarrr... Swabby, what be takin'' ye so long?',12340),
	 (6646,1,0,'The tears of the Fire Lord are a rare find indeed.$B$BOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood. 
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6644,1,0,'The Thorium Brotherhood sympathizes with your plight, $r. This is why Lokthos has been empowered to bargain.$B$BOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.',12340),
	 (6643,1,0,'Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.$B$BMany of the Brotherhood have been lost in their search for Fiery Cores.$B$BOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.',12340),
	 (6642,1,0,'Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.$B$BFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.',12340),
	 (6641,1,0,'',12340),
	 (6629,1,6,'Have you killed Grundig Darkcloud and his personal band of Brutes?',12340),
	 (6628,1,1,'There is only one rule I feel you must know if you wish to survive in this world: the more you know, the more you''ll see.$b$bIf you study, if you observe, then you will begin to see things in the world that no other $r will see.',12340),
	 (6627,1,1,'Life is full of questions, $C. You will never be able to answer all of them, but with some time and study, perhaps you will become a little more knowledgeable.',12340),
	 (6625,1,0,'',12340),
	 (6626,1,0,'How goes the hunt, $N? Seeing just this small sample of this diplomat''s power here removes any doubt I had that the Scourge are one of the greatest threats this world has ever seen.',12340),
	 (6622,1,0,'Miraculous work, doctor. Simply miraculous.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6623,1,0,'',12340),
	 (6624,1,0,'Miraculous work, doctor. Simply miraculous.',12340),
	 (6612,1,0,'',12340),
	 (6621,6,6,'Did you defeat Chief Murgut, $N? Did you retrieve his Foulweald Totem?',12340),
	 (6611,1,0,'',12340),
	 (6609,1,0,'',12340),
	 (6610,5,5,'My cravings are going to be the end of me! Hurry, $N - before I dip into my own supply.',12340),
	 (6606,1,0,'',12340),
	 (6607,6,6,'Anything bitin'' today?',12340),
	 (6608,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6603,1,0,'',12340),
	 (6604,1,0,'',12340),
	 (6605,1,0,'',12340),
	 (6601,1,0,'Do not panic, $N!',12340),
	 (6602,1,1,'I don''t think I need to tell you that Drakkisath is not to be taken lightly.$B$BI let the thousands dead by his hand do the talking.',12340),
	 (6584,1,1,'Ironically, whelp, time is of the essencccce.',12340),
	 (6585,0,0,'Changesss... I sense them taking place in you, whelp. Pass this test and only ceremony remains.',12340),
	 (6583,15,15,'Do not return here until you have bathed in the blood of our enemies and drank in their suffering.',12340),
	 (6582,0,0,'<Emberstrife hisses.>',12340),
	 (6581,1,0,'Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.$B$B..But what sort of payment do you have for me? You can''t just take them, you know! My time isn''t cheap!$B$BWhat I really need is a good gun to carry with me on my travels. A girl''s gotta protect herself, you know? There''s a gun I really like that I''m sure an engineer would have no problem making.$B$BSo, if you bring me a deadly blunderbuss, I''ll give you the saw blade shipment. Do we have a deal?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6570,1,0,'',12340),
	 (6571,1,1,'I hope you can come through with the supplies!',12340),
	 (6566,1,0,'Patience, $N. Pay attention!',12340),
	 (6567,1,0,'',12340),
	 (6568,1,0,'It is not often I see one of the Horde in these parts of Lordaeron. What is it that you have for Myranda?',12340),
	 (6569,11,11,'The eyes of that which we wish to mimic are the most important ingredient of any illusion, $N.$B$B<Myranda points to a bag almost overflowing with eyeballs labeled ''Scarlet Crusade.''>$B$B<Myranda laughs.>',12340),
	 (6564,6,0,'Yes, $N? What is it you need? There is still much I must learn about the crystals the naga are gathering.',12340),
	 (6565,1,5,'Have you found him yet, $N? Lorgus must be stopped!',12340),
	 (6562,1,0,'',12340),
	 (6563,6,6,'How goes your search for the crystals, $N? Have you witnessed the naga harvesting them? I pray to my ancestors we find the reason they are collecting such things.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6561,1,0,'May the Earthmother be with you, $N.$B$BPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.',12340),
	 (6548,1,6,'Have you killed them yet?',12340),
	 (6547,0,0,'Keep an eye out, $R. The elves are often hiding in the shadows...$B$BWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.$B$BI assume you have my next orders from Kadrak?',12340),
	 (6546,0,0,'Much danger lies along this path, $N. You''d do best to remember this while traveling in these lands. The threat of the alliance is quite near.$B$BWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale. I have also discovered that the naga have taken over a large area of the land of Azshara.$B$BIt''s good to see that we are still bolstering our numbers -- be ready for what lies ahead, $N.',12340),
	 (6545,0,0,'So you''re here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.$B$BYou''d best learn fast if you expect to keep up here. The threat of the naga grows, $N. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.$B$BBut if you''d like to pitch in with that effort, speak with one of the others here at the outpost.',12340),
	 (6544,1,0,'Torek was sent on a mission against Silverwing Outpost. Was the attack successful?',12340),
	 (6542,1,0,'',12340),
	 (6543,0,0,'Hurry, $N. They must receive their reports; it is urgent.',12340),
	 (6523,1,0,NULL,12340),
	 (6541,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6522,1,0,'What business is it you wish to speak of, $N? You must feel it is important if you continue to pester me.',12340),
	 (6503,1,0,'I await reports of your outrunner kills, $N.',12340),
	 (6504,0,0,'I hope you find the pages soon, $N! I really need to get back to work!',12340),
	 (6521,1,0,'Have you found the Ambassador, $N? Is he dead?$B$BWe cannot afford to allow the Scourge to take a foothold on Kalimdor. They are enough of a threat to our own borders to have to deal with them on two fronts.$B$BThe only optimistic sign from the events you''ve told me about is that the crone seemed uncorrupted. She must know deep in her spirit that the Scourge may bring great power, but that the Barrens would not truly be hers if she were to agree to their deal.',12340),
	 (6482,1,6,'Have you seen my brother Ruul? He walked into the forest days ago and has not returned...',12340),
	 (6501,1,0,'I sense an aura of evil radiating from you, $R. What could you hold that emits such an aura?',12340),
	 (6502,1,0,'The flow of time does not stop or slow, $R. While my life is eternal, yours is not. Waste not the time that you have...',12340),
	 (6481,1,1,'I fear if we do not dispose of this threat immediately, all of Stonetalon will be lost. The might of an Earthen can not be matched by any means. When awakened, Goggeroc will be weak from his long slumber, this will be the opportunity that you must take advantage of... go now $N!',12340),
	 (6462,14,14,'Did you find the charms, $N?  Every moment the furbolgs possess those sacred items, my blood boils with rage!',12340),
	 (6442,0,0,'The naga increase in numbers, $n. Please complete this task for me.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6461,1,6,'Hey mon, have you slain the hairy blood feeders? I fear none here in Stonetalon but I don''t go walking around here at night... if you know what I mean mon!$b$bAs long as I stay off their dinner plate then all is well.$b$bGood luck to you, $c!',12340),
	 (6441,0,0,'I hope you can be quick about getting those horns, $N. I''m heading back to Ratchet soon!',12340),
	 (6394,0,0,'Have you entered the Burning Blade Coven, $N? Did you find my pick?',12340),
	 (6395,1,1,'We must respect our dead, $N. It is one of the ways in which we differ from the Scourge...',12340),
	 (6401,1,0,'',12340),
	 (6402,1,0,'',12340),
	 (6403,1,0,'I... I... I was powerless.',12340),
	 (6421,1,1,'What news have you discovered from Boulderslide Ravine? I recall some legend that deals with Resonite... I just cannot place my hoof on it. Perhaps knowing what lies at the bottom of the cave will illuminate their devious intentions.',12340),
	 (6392,6,0,'Ah, $N. Have you returned from Ironforge?',12340),
	 (6393,1,0,'The Tribunal of the Tides grows impatient. They seek to end this war that has raged across all dimensions for eons. My brethren are anxious to hear news of the glorious victory over the hated fire elementals. Have you the Incendrites that I require?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6391,6,0,'What can I do for you, sir?',12340),
	 (6390,6,6,'Have you done it, $N? Have you released the termites in the lumber mill?$B$BIt was bad enough that my family lost their jobs and lives, but then to see the place where my childhood was spent taken over by those disgusting so-called holy men... pfah!!',12340),
	 (6385,6,0,'Do you need one of my wind riders?',12340),
	 (6386,6,0,'Have you returned from Orgrimmar? Did Gryshka like the meat I sent her?',12340),
	 (6387,6,0,'Have you had your fill of Thelsamar so soon? Are you ready to leave for another city?',12340),
	 (6388,6,0,'You look like you have somewhere to go. Need one of my gryphons?',12340),
	 (6389,6,0,'Have you done it, $N? Have you released the termites? The Light help us if the Scarlet Crusade were able to hold onto both the mill and Hearthglen. They should have neither. They''re just capitalizing on the victims of the last war and should be put down like rabid animals!',12340),
	 (6381,1,1,'These seeds you plant are strong, resisting corruption, and making a foothold for other life. They will grow and grow, first preventing corruption and healing the scarred land, and then one day, restoring Stonetalon to a lush forest, once again.$b$bHave you planted all of the Gaea seeds?',12340),
	 (6382,1,0,'',12340),
	 (6383,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6384,6,0,'Something smells good! You don''t have raw meat on you, do you?',12340),
	 (6362,6,6,'There is dust on your shoulders that must be from the Barrens. You have spoken with my friend Jahan?',12340),
	 (6363,3,3,'Greetings, $C. What can I do for you?',12340),
	 (6364,6,6,'$N, you are back from Thunder Bluff? Did you deliver the hides to Ahanu?',12340),
	 (6365,6,0,'You need to get somewhere fast? Then you''re talking to the right orc!',12340),
	 (6341,1,0,'How may I help you? Are you in need of transport?',12340),
	 (6342,1,0,'Have you come from Teldrassil? Tell me, how is the fishing there?',12340),
	 (6343,1,0,'$N, you''re back from Auberdine? Did you speak with Laird?',12340),
	 (6344,1,0,'',12340),
	 (6361,6,6,'Are you here for a wind rider? You have something to transport?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6324,6,0,'$N, you return. Do you have our supplies from the Undercity?',12340),
	 (6301,1,1,'The continuous destruction caused by war and those that seek a profit from lumber pains me deeply. To aid the cycle of rebirth and replenish the lands, I need Gaea seeds. Do you have them, $C?',12340),
	 (6321,6,0,'You appear to be on official business...',12340),
	 (6322,1,0,'If you must travel a long distance, then a bat is your best option.',12340),
	 (6323,6,0,'I keep my weapons in top condition. They are cleaned and ready for use.',12340),
	 (6284,1,1,'Besseleth is a ruthless predator... I fear for those that travel Webwinder Path at night. It''s then that she and her children prey upon innocent travelers. I myself fell prey to her two-foot fang of death, but luckily I was able to fend her off and get to safety. I would give anything to see that monster destroyed.',12340),
	 (6285,6,0,'You''re back from Stormwind? Did Osric send the armor?',12340),
	 (6282,1,1,'Do not be weary of Charred Vale; many evil creatures reside in those hills. Stay strong $N, and you shall prevail over this threat to our people. Go now and strike hard - our children shall never know of the evil of what was.',12340),
	 (6283,1,1,'Bloodfury Ripper is a nasty creature! You will have success finding her along the western hill line in the Charred Vale.$b$bThe bloodfuries will be helpless with out... surely we can vanquish them forever!',12340),
	 (6281,6,0,'You''ve been traveling, eh? Have you been anywhere interesting?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6221,1,0,'',12340),
	 (6241,1,0,'',12340),
	 (6261,1,0,'Is that sweat on your brow, lad? You''ve been running too much. Next time, take a gryphon!',12340),
	 (6183,1,0,'',12340),
	 (6184,1,0,'',12340),
	 (6185,6,0,'An... Any luck??',12340),
	 (6186,1,0,'',12340),
	 (6187,1,0,'<King Varian Wrynn is lost in thought.>',12340),
	 (6182,1,0,'',12340),
	 (6181,6,0,'You look like you''re in a hurry. Well, then you came to the right place!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6163,1,1,'After Sylvanas freed me, I hunted the beast across these wastes for months. It fled to the safety of Stratholme. The bastard...',12340),
	 (6164,0,0,'Do you have my receipt book?  I can''t wait to get back to business!',12340),
	 (6144,1,0,'',12340),
	 (6145,1,0,'Succeed now and you will have almost earned my respect, $C.',12340),
	 (6146,5,0,'This is unacceptable, soldier!',12340),
	 (6147,1,0,'',12340),
	 (6148,1,0,'What is your status, $N?',12340),
	 (6161,1,0,'This chest is securely locked.',12340),
	 (6162,6,6,'Do you have the beast''s claw yet, $N? It will pay for its crimes. I don''t care if it''s corrupt or just angry for living in such a dismal forest. No furbolg will live for long committing such crimes against my family!',12340),
	 (6141,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6142,1,0,'I can''t wait to go fishing with some fresh soft-shelled clam meat; did you bring me the 10 pieces of it I need?',12340),
	 (6143,1,0,'I still hear their voices crying for help when the naga unleashed their chaos over us. If I didn''t have this bad knee, I''d go and help you kill those blasted naga!$B$BYou can usually guarantee to find them deep in the coral reefs below the surface... lurking... scheming...',12340),
	 (6131,1,0,'',12340),
	 (6132,1,0,'Have you seen my sister Melizza? She''s always on the go, which gets her into trouble all the time.',12340),
	 (6133,0,0,'Do not leave me waiting, $C.',12340),
	 (6134,0,0,'Where''s my ghost-o-plasm, $N?',12340),
	 (6135,1,1,'I would not recommend that you take on this challenge alone, $c.',12340),
	 (6136,6,6,'Have I told you lately that I hate you?',12340),
	 (6128,1,0,'Have you got the reagents I need to make the salve? The gazelle aren''t getting any better on their own, so we better not tarry in our effort to save them!',12340),
	 (6129,1,0,'Have you completed what was asked of you by Tonga Runetotem at the Crossroads? Your work is not complete unless it is.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6130,1,0,'',12340),
	 (6125,1,0,'',12340),
	 (6126,1,0,'',12340),
	 (6127,1,0,'You are the one that the Cenarion Circle in Moonglade sent, yes? This is most fortuitous for us! We are stymied in our effort to bring balance to the sickly gazelles that wander the northern Barrens; we''re happy for all the help we can get.$B$BDo you have the sample of water that Dendrite Starblaze said you''d have? He notified me that you''d draw one so we could work on a cure together...',12340),
	 (6123,1,0,'Have you got the reagents I need to make the salve? The deer aren''t getting any better on their own, so we better hurry to help them out!',12340),
	 (6124,1,0,'Have you completed what was asked of you by Alanndarian Nightsong of Auberdine? Your work is not complete unless it is.',12340),
	 (6088,1,1,'You will soon be ready, $N.',12340),
	 (6089,1,0,'',12340),
	 (6101,1,0,'Understanding the balance between nature and oneself is a way of life for every $R.',12340),
	 (6102,1,0,'I am proud of your accomplishments, $N. Have you finished the last task I gave you?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6103,1,0,'',12340),
	 (6121,1,0,'',12340),
	 (6122,1,0,'You''re the one that the Cenarion Circle in Moonglade sent? That''s wonderful! We''ve quite the crisis our hands here regarding the poor deer, and we''re happy for all the help we can get.$B$BDo you have the sample of water that Dendrite Starblaze said you''d have? He notified me that you''d draw one so we could work on a cure together...',12340),
	 (6086,1,0,'',12340),
	 (6087,6,6,'Have you found a prairie stalker?',12340),
	 (6085,1,6,'Have you tamed the ice claw bear yet?',12340),
	 (6073,1,0,'',12340),
	 (6074,1,0,'',12340),
	 (6075,1,0,'',12340),
	 (6076,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6081,1,0,'',12340),
	 (6082,1,1,'Were you able to tame the scorpid?',12340),
	 (6083,1,1,'You need to practice in order to gain the skills you need to effectively control your pet. Have you tamed a surf crawler?',12340),
	 (6084,1,6,'What do you think of the snow leopard, $N?',12340),
	 (6070,1,0,'',12340),
	 (6071,1,0,'',12340),
	 (6072,1,0,NULL,12340),
	 (6066,1,0,'',12340),
	 (6067,1,0,'',12340),
	 (6068,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6069,1,0,'',12340),
	 (6061,1,1,'Practice your skills, $N. Tame the adult plainstrider.',12340),
	 (6062,1,1,'Good luck, young $C.',12340),
	 (6063,1,0,'You will learn, $N, and one day you will be a great $C.',12340),
	 (6064,1,1,'Don''t worry, lass! You''ll get ta try a few before you''ll need to decide on just one.',12340),
	 (6065,1,0,'',12340),
	 (6032,0,0,'Have you brought the mooncloth, $N?',12340),
	 (6041,1,1,'I got supplies left over to make a few more sticks of the special compound. Just let ol'' Smokey know if you need more.',12340),
	 (6042,1,1,'It could have been worse. I could have had you collecting bat guano.$B$B<Nathanos stares at you in contemplation.>$B$BHrm... Hey! Wait a minute. Where are you going?',12340),
	 (6029,66,0,'Greetings, $C.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Bulwark.  I might also offer you the chance to fight for a cause that''s worth fighting for!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6030,2,0,'May the Light guide you in these troubling times, $C. What brings you here to this beacon of hope in the middle of darkness and despair?',12340),
	 (6031,0,0,'Do you have the runecloth?  My people are eager for more items of runecloth!',12340),
	 (6028,66,0,'Greetings, $N. On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp. I might also have some work for you...',12340),
	 (6027,1,1,'Ah, $N! It''s good to see you again. Do you have the Book of the Ancients?',12340),
	 (6026,1,1,'Trust ol'' Smokey, $r. The reward will be worth it. These Argent Dawn folk don''t mess around when it comes to payment.
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (6004,1,6,'How is it going, $N? Are they stronger than you thought? I hope not. If I''m going to follow through here, then it''s going to require a heck of a lot more strength than what I''ve already asked you to do.',12340),
	 (5944,1,0,'<Tirion regains his composure.>',12340),
	 (5961,1,0,'',12340),
	 (5981,1,1,'You must continue to prove yourself, $N.',12340),
	 (6001,1,0,'',12340),
	 (6002,1,0,'When you have faced the challenge that lies before you, your understanding of strength of body and strength of heart will be fully realized. Until that time, I cannot help you further.',0),
	 (5942,0,0,'This chest is old and covered in grime.',12340),
	 (5943,1,0,'You know, if that caravan were to ever disappear I would be ruined! You''re not the bearer of bad news about the caravan, are you?$b$b<Smeed wipes his brow.>$b$bThank the goddess of greed!',12340),
	 (5926,1,0,'',12340),
	 (5927,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5928,1,0,'',12340),
	 (5929,1,0,'',12340),
	 (5930,1,0,'',12340),
	 (5931,1,0,'',12340),
	 (5932,1,0,'',12340),
	 (5941,6,0,'I have been in contact with your friend Carlin.  He feels great pain for the doom of his village, but he speaks very highly of you and knows that you can set things right.$B$BOh, but I''m drifting from the subject at hand... $N, do you have the relics I asked for?',12340),
	 (5902,1,0,NULL,12340),
	 (5903,6,6,'Did you find the termite mounds, $N? I''ve heard they are all over Plaguewood.',12340),
	 (5904,1,0,'',12340),
	 (5921,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5922,1,0,'',12340),
	 (5923,1,0,'',12340),
	 (5924,1,0,'',12340),
	 (5925,1,0,'',12340),
	 (5892,1,0,'Do you have the supplies, $N? We can never have enough!',12340),
	 (5893,1,0,'Have you been to the Coldtooth mine, $N? Do you have the supplies I asked for?',12340),
	 (5901,6,6,'Do you have the termites yet, $N? I am sure it is obvious to a smart $C like yourself.$B$BOnce we have enough of them, we''ll make sure no one can use the lumber mill ever again!',12340),
	 (5891,1,0,'The power of a disenchanted magical item is felt by the essence it creates.  I''ve devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don''t need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.$B$BI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!',12340),
	 (5890,1,0,'A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!$b$bWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.',12340),
	 (5889,1,0,'A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood''s corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.$b$bWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5888,1,0,'If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.$B$BIf you have collected any tainted vitriol, I''ll give you some Cenarion plant salve I have already prepared.',12340),
	 (5887,1,1,'Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.$B$BIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.',12340),
	 (5886,1,0,'The power of a disenchanted magical item is felt by the essence it creates. I''ve devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don''t need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.$b$bI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way! ',12340),
	 (5885,1,0,'A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!$b$bWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.',12340),
	 (5884,1,0,'A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood''s corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.$b$bWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.',12340),
	 (5883,1,0,'If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.$b$bIf you have collected any tainted vitriol, I''ll give you some Cenarion plant salve I have already prepared.',12340),
	 (5882,1,1,'Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.$b$bIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.',12340),
	 (5846,1,0,'',12340),
	 (5847,1,0,'Greetings! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (5848,6,6,'The painting, $N. Do you have the painting?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5861,2,0,'I knew this day would come.',12340),
	 (5862,25,0,'Are you the reinforcements from Tyr''s Hand?',12340),
	 (5863,1,1,'I''m so worried! Please be careful!',12340),
	 (5881,1,0,'You have news from Maggran Earthbinder?',12340),
	 (5843,1,0,'Hello! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (5844,1,0,'Greetings! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (5845,1,1,'My faith will guide you, $N. The Light knows no bounds.',12340),
	 (5842,1,0,'Greetings! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (5841,1,0,'Hello! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (5821,1,0,'Why do I find myself waiting for that blasted caravan?$b$b<Smeed looks enlightened.>$b$bOh yeah, they pay the bills. Have you seen them?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5805,1,0,'Greetings! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.',12340),
	 (5804,1,1,'You''ve come this far $N - only the destruction of the physical form of Araj the Summoner will provide us with the means to finish the key. Get Araj''s scarab, by hook or by crook, and bring it to me - I will fuse it on as the head of the key.',12340),
	 (5803,1,1,'You''ve come this far $N - only the destruction of the physical form of Araj the Summoner will provide us with the means to finish the key. Get Araj''s scarab, by hook or by crook, and bring it to me - I will fuse it on as the head of the key.',12340),
	 (5802,6,0,'Do you have the stem of the skeletal key finished? I''m truly sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge. Once you hand me the unfinished key, you''ll be ready for the final item needed to complete its construction.$b$bIt won''t be easy at all, but the work you''ve done to date in preparing for an assault on Andorhal will now start to pay for itself. You''ll see.',12340),
	 (5801,6,0,'Do you have the stem of the skeletal key finished? I''m truly sorry you had to bear the brunt of the fee to purchase the mold, but we must all do our part to counter the Scourge. Once you hand me the unfinished key, you''ll be ready for the final item needed to complete its construction.$b$bIt won''t be easy at all, but the work you''ve done to date in preparing for an assault on Andorhal will now start to pay for itself. You''ll see.',12340),
	 (5781,5,5,'He must be redeemed.',12340),
	 (5763,6,0,'Sit, $C. Soon enough you''ll strike back into the jungle.',12340),
	 (5762,6,0,'Is that desert dust on your collar?$b$bHm... if my nose tells true, I''d say it''s not desert dust, it''s desert salt!  Been to the Shimmering Flats, have you?',12340),
	 (5741,6,6,'Do you have the Sceptre of Light?',12340),
	 (5742,1,0,'Please, friend; sit and hear my tale.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5761,6,6,'Have you killed the beast? He surely must be the leader of the Searing Blade in Ragefire Chasm.',12340),
	 (5729,1,0,'',12340),
	 (5730,1,0,'',12340),
	 (5727,6,6,'Well, $c? Does he believe our ploy, or are things worse than I had first estimated?$b$bProving valuable to Neeru will make our infiltration of the Shadow Council much easier. He will have plenty of information that we can use to route out those who would destroy all we have built in Durotar.',12340),
	 (5728,1,6,'Have you found them yet, $N? The leaders of the Searing Blade.$b$bI knew the Shadow Council sought to take Orgrimmar and all of the Horde from me, but I hadn''t realized how quickly they were able to infiltrate the city. So many arms this beast has... we can cut them off until exhaustion sets in, but we will be no further than when we started. I will have to have my spies double their efforts.',12340),
	 (5726,6,6,'Do you have the insignia yet, $N?$b$bIt will be a vital tool in you infiltrating what I believe is the greatest threat to the Horde and us finally finding peace in our new home.$b$bYou will learn how intricate a web men and orcs alike can weave when they are motivated by greed and power. The hidden agendas, the corruption, all of it will become clear. You will find yourself in the midst of a war you never knew existed.',12340),
	 (5725,1,0,'There are a hundred other tasks awaiting my attention, $C. Do you have the books?',12340),
	 (5721,1,0,'I think I heard ghosts outside. They whisper scary things to me...',12340),
	 (5722,1,0,'',12340),
	 (5723,1,6,'How goes your search for the Chasm? And the troggs?$B$BThe threat cannot be allowed to persist--it will only injure our orc brethren if it continues.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5724,6,6,'Were you able to find anything, $N? Any clues as to why one of her clansman had to die needlessly would be helpful.',12340),
	 (5678,1,0,NULL,12340),
	 (5679,1,0,'',12340),
	 (5680,1,0,'',12340),
	 (5713,1,0,'Have you seen of Sentinel Aynasha on the road? She left on an important mission but she has not yet returned.',12340),
	 (5661,1,0,NULL,12340),
	 (5662,1,0,NULL,12340),
	 (5663,1,0,NULL,12340),
	 (5672,1,0,'',12340),
	 (5673,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5674,1,0,'',12340),
	 (5675,1,0,'',12340),
	 (5676,1,0,'',12340),
	 (5677,1,0,'',12340),
	 (5660,1,0,NULL,12340),
	 (5654,1,0,'',12340),
