INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5659,1,0,NULL,12340),
	 (5651,1,0,'',12340),
	 (5652,1,0,'',12340),
	 (5649,1,0,'',12340),
	 (5650,1,0,'Our powers make us ideal for so many situations, $N. You''ll find that no matter what though, our ability to mend wounds and increase the amount of damage our companions can take will always be the most desired talents we have access to. Do not let that dissuade you from pursuing other paths as a $C--you can be effective in many ways. But... if you truly wish to destroy your enemies with magical energy, perhaps the arcane is more to your liking.',12340),
	 (5643,1,0,'',12340),
	 (5644,1,0,'',12340),
	 (5645,1,0,'',12340),
	 (5646,1,0,'',12340),
	 (5647,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5648,1,0,'Most think it logical that healin'' magics be powerful, but not many understand how powerful. You can keep many alive when instead they should be meetin'' their own ancestors. This healin'' magic mixed with the ability of Fortitude are a very powerful combination of spells. You remember this. It helpful to all manner of people: warriors, mages and everything in between.',12340),
	 (5640,1,0,NULL,12340),
	 (5641,1,0,'',12340),
	 (5642,1,0,'',12340),
	 (5637,1,0,NULL,12340),
	 (5638,1,0,NULL,12340),
	 (5639,1,0,NULL,12340),
	 (5634,1,0,NULL,12340),
	 (5635,1,0,NULL,12340),
	 (5636,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5630,1,0,'',12340),
	 (5631,1,0,'',12340),
	 (5632,1,0,'',12340),
	 (5633,1,0,'',12340),
	 (5627,1,0,'',12340),
	 (5628,1,0,'',12340),
	 (5629,1,0,'',12340),
	 (5626,6,0,'',12340),
	 (5625,1,0,'Have you found Dolf yet, $N?$B$BYou''ve probably already learned this, but our ability to heal is very useful. Not only are we able to take care of the wounded, but we''re vital to the survival of all those would-be heroes out there trying to make a name for themselves. With Fortitude to increase the amount of blows we can take, and our healing magic to keep them alive, there''s nothing we can''t overcome!',12340),
	 (5622,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5623,1,0,'',12340),
	 (5624,1,1,'As you may have already learned, our healing magics are vital to the survival of our people in these harsh times--especially to adventurers and heroes who take up arms and magic to fight back so many different threats.$B$BYou would do well to always remember how important that skill is. That, coupled with Fortitude, make your companions far more capable in battle since they will be able to stand up to a greater number of blows.$B$BDo not let anyone dismiss how powerful your magics are.',12340),
	 (5601,1,0,'',12340),
	 (5621,1,0,'Our spells of Fortify are very powerful, $N. They allow our companions to take further injury from all types of attacks and survive in situations where they would normally fall. But this is nothing when compared to our abilities to heal. There are no greater healers than a priest--do well to remember that. Your power alone can turn the tides of battle easily.',12340),
	 (5581,6,6,'Have you banished the demon portals at Mannoroc Coven?',12340),
	 (5582,1,0,'$N, do you have something to show me?',12340),
	 (5545,0,0,'That deadline isn''t getting any further away, $C. Please hurry and collect those bundles of wood.',12340),
	 (5561,0,0,'The caravan will be here shortly; do you have the five new tamed kodos I was asking for?',12340),
	 (5543,1,1,'Do not underestimate the winged vermin, $r. The Plague has given them supernatural abilities.',12340),
	 (5544,1,1,'You will grow to tolerate the taste, $r.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5541,6,6,'I hope you''re not here for ammo, because I''m almost out!',12340),
	 (5542,1,5,'Do not pity the demon dogs, $r. They are abominations!',12340),
	 (5538,1,0,'Yeah, I know who you are, and I know why you''re here. Arbington sent word to me before you arrived. Let''s cut to deal at hand, now shall we?$B$BI''ve got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation. I''ll pack the skeletal fragments into the mold for you, and I''ll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.$B$BWho says mercenaries don''t offer competitive deals!',0),
	 (5536,1,1,'How goes your battle against the satyr, $c?$B$BAre they as strong as you thought? Stronger? Or perhaps they were nothing to your own might.',12340),
	 (5537,1,1,'As morbid as it sounds, we''ll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don''t call it a Skeleton Key for nothing, you know.',12340),
	 (5535,1,6,'How goes your search for the Highborne spirits, $c?$B$BMany events have caused all the races of Azeroth great suffering, but for some reason, these spirits seem to be a plague for all people. Perhaps it is there continued desire for any arcane magic--such desire is a harbinger of the Burning Legion, and we know what that can lead to.',12340),
	 (5534,1,0,'Well, $N? Where is the rune? You are a good employee, right? You''re here to help?$b$bDon''t make me think twice about paying you what we agreed upon. What? Oh, we didn''t agree on anything? Oh, great... then take your time--just know that it''ll be a lot less if you take a long time.',12340),
	 (5531,3,0,'Hello, $N! I heard you were here with some dragon eggs? Well, let''s see them!',12340),
	 (5533,1,0,'',12340),
	 (5528,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5529,1,5,'Get to the Scholomance, $N.  Take out those plagued hatchlings before they grow!',12340),
	 (5527,1,0,'A Reliquary of Purity is an artifact unto itself.  Few were ever made, and almost all of them were thought to have been lost over time.$B$BI admit I have known about the one in Southwind for a little while now.  Honestly, with the rising turmoil in Silithus, I thought to keep our secrets just that - a secret.  To poke and prod would only cause suspicions of our enemies to rise.$B$BAlas, the time for complacency is at an end, especially with the situation in Eldre''Thalas. ',12340),
	 (5526,1,0,'With the Sealed Reliquary of Purity in our possession, it will be possible not only to remove a corrupting threat from the world but also to study it under our judicious watch. Perhaps we can even devise new means to combat the taint of corruption that ever threatens Azeroth.$b$bI know Milli would have had it no other way...',12340),
	 (5525,1,0,'It''s called the Gordok Shackle Key - well, that''s what these "tons o'' fun" keep calling it. I think any of the ogres might have it, but I''m not sure if any specific ones do. Maybe the guards have a better chance of having one...$B$BWhat am I talking about - you have it already, don''t you?! Is that it there??!',12340),
	 (5522,6,0,'You are the one up to mischief in Blackrock Spire, yes? Do you have what I asked for?',12340),
	 (5524,1,0,'Salutations, mighty $C! Have you brought the valor tokens I asked of you? Once you hand them to me, I will issue you your own Chromatic Mantle of the Dawn.',12340),
	 (5521,1,0,'Salutations, mighty $C! Have you brought the valor tokens I asked of you? Once you hand them to me, I will issue you your own Chromatic Mantle of the Dawn.',12340),
	 (5519,1,0,'Need another suit, do ya? Well, I''m not going anywhere soon it seems - bring me the same things I asked for from before, and I''ll make you another ogre suit.',12340),
	 (5518,1,0,'The Ogre Tannin is probably the toughest thing to find for what I need to make the suit - I think they have some upstairs?  It''s hard to tell, since this ball and chain doesn''t make movement that easy to do...$B$BAnyway, bring me the things I need, and I''ll whip you up an ogre suit that will fool Captain Kromcrush into thinking you''re one of his men.',12340),
	 (5515,0,0,'<Eva fades in and out of focus.>',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5517,1,0,'Salutations, mighty $c! Have you brought the valor tokens I asked of you? Once you hand them to me, I will issue you your own Chromatic Mantle of the Dawn.',0),
	 (5513,1,0,'Ah, noble $C! Have you brought the valor tokens requested of you? Once you hand them to me, I will make our various mantles available to you for purchase.',12340),
	 (5514,1,0,'Yeah, I know who you are, and I know why you''re here. Dithers sent word to me before you arrived. Let''s cut to deal at hand, now shall we?$b$bI''ve got a mold you can use for the skeleton key, but it will cost you - fifteen gold, up front, no negotiation. I''ll pack the skeletal fragments into the mold for you, and I''ll also teach you on how to forge the stem of the key without any knowledge of blacksmithing... all free of charge no less.$b$bWho says mercenaries don''t offer competitive deals!',12340),
	 (5511,1,0,'Well, here you are, $n - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There''s only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.',12340),
	 (5510,1,1,'A Minion''s Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term "weaker" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.$B$BThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I''m happy to do, provided you have earned enough scourgestones!',12340),
	 (5509,1,1,'An Invader''s Scourgestone is the insignia of the Scourge''s elite troops.  These are sometimes found on the stronger of the troops positioned in the Plaguelands.  Slaying such a creature is indeed a challenge, but one that should be relished with a commission to vanquish evil.$B$BThe Argent Dawn currently offers a valor token in exchange for ten of these insignia.  Bring them to me here, and I will make sure you receive your just reward.',12340),
	 (5508,1,1,'A Corruptor''s Scourgestone is the insignia of the Scourge''s overlords.  A powerful being that holds a position of authority over the Scourge will always possess one.  To slay such a malevolent creature would surely advance the cause of the Argent Dawn, and all good causes!$B$BOn behalf of the Argent Dawn, I will give you a valor token in exchange for just a single one of these insignia.  Use caution in acquiring one, $N - such powerful beings are not to be trifled with.',12340),
	 (5507,1,0,'Ah, noble $C! Have you brought the valor tokens requested of you? Once you hand them to me, I will make our various mantles available to you for purchase.',12340),
	 (5505,1,0,'Well, here you are, $n - the completed Skeleton Key. I am certain as I can be that this key will allow you within the confines of the Scholomance. There''s only one way to be absolutely sure it works, though. Waste no time in trying it out, I say.',12340),
	 (5504,1,0,'Ah, noble $C! Have you brought the valor tokens requested of you? Once you hand them to me, I will make our various mantles available to you for purchase.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5503,1,0,'',12340),
	 (5502,1,0,'It is a pleasure to see you again, $N. Have you attended to the duties you''ve volunteered for during Children''s Week?',12340),
	 (5501,0,0,'Do you have the bones?  The caravan will be here any moment.  I need just ten more kodo bones to reach a career high.  A career high, I tell you!',12340),
	 (5482,6,0,'This had better be good. I trust you have all of the doom weed that I require?',12340),
	 (5481,0,0,'Where''s that useless abomination? Either you have what I need or you''d best get out there and find it.',12340),
	 (5466,1,1,'You carry the burden of ten thousand restless souls, $N.',12340),
	 (5464,0,0,'<Leonid shudders.>',12340),
	 (5465,6,0,'Have you done the impossible?',12340),
	 (5463,1,0,'The area around Menethil''s Gift is exceptionally cold.',12340),
	 (5462,274,0,'Do not ask questions of which you do not want answers.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5461,0,0,'A keepsake of remembrance is a rare find, $N.',12340),
	 (5441,5,1,'No good lazy...$b$b Eh? Do you have my blackjack? Did you catch any peons sleeping on the job?!',12340),
	 (5421,1,1,'I''ll reward anyone who makes my life a bit easier... I enjoy doing as little as possible, mon!$B$BBelow the docks here in Shadowprey Village, I''ve many shellfish traps.  If you''re kind enough to do my work and collect me my shellfish, then I''ll reward you with something you want... get my drift mon?  For every five shellfish you bring me I will give you a fine Bloodbelly fish!',12340),
	 (5408,1,1,'A Minion''s Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term "weaker" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.$B$BThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I''m happy to do, provided you have earned enough scourgestones!',12340),
	 (5407,1,1,'An Invader''s Scourgestone is the insignia of the Scourge''s elite troops.  These are sometimes found on the stronger of the troops positioned in the Plaguelands.  Slaying such a creature is indeed a challenge, but one that should be relished with a commission to vanquish evil.$B$BThe Argent Dawn currently offers a valor token in exchange for ten of these insignia.  Bring them to me here, and I will make sure you receive your just reward.',12340),
	 (5405,1,0,'',12340),
	 (5406,1,1,'A Corruptor''s Scourgestone is the insignia of the Scourge''s overlords.  A powerful being that holds a position of authority over the Scourge will always possess one.  To slay such a malevolent creature would surely advance the cause of the Argent Dawn, and all good causes!$B$BOn behalf of the Argent Dawn, I will give you a valor token in exchange for just a single one these insignia.  Use caution in acquiring one, $N - such powerful beings are not to be trifled with.',12340),
	 (5404,1,1,'A Corruptor''s Scourgestone is the insignia of the Scourge''s overlords.  A powerful being that holds a position of authority over the Scourge will always possess one.  To slay such a malevolent creature would surely advance the cause of the Argent Dawn, and all good causes!$B$BOn behalf of the Argent Dawn, I will give you a valor token in exchange for just a single one these insignia.  Use caution in acquiring one, $N - such powerful beings are not to be trifled with.',12340),
	 (5403,1,1,'An Invader''s Scourgestone is the insignia of the Scourge''s elite troops.  These are sometimes found on the stronger of the troops positioned in the Plaguelands.  Slaying such a creature is indeed a challenge, but one that should be relished with a commission to vanquish evil.$B$BThe Argent Dawn currently offers a valor token in exchange for ten of these insignia.  Bring them to me here, and I will make sure you receive your just reward.',12340),
	 (5401,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5402,1,1,'A Minion''s Scourgestone is the insignia of the Scourge rank and file.  These are sometimes found on the weaker of their troops positioned in the Plaguelands, though the term "weaker" is certainly to be considered in context.  The Scourge, no matter where they are, should never be underestimated.$B$BThe Argent Dawn currently offers a valor token in exchange for twenty of these insignia - an exchange I''m happy to do, provided you have earned enough scourgestones!',12340),
	 (5361,0,0,'What news have you, $C! Ah - a message from my brother you say? Well then, hand over the report!',12340),
	 (5381,0,0,'$n, do you have the Demon Box?',12340),
	 (5382,1,5,'The Butcher must be stopped!',12340),
	 (5384,1,1,'Be wary, Kirtonos is a seasoned fighter.',12340),
	 (5385,6,0,'How did things go in Jaedenar, $N?',12340),
	 (5386,1,1,'My hoof tingles and my mouth starts to water when I think of fried Bloodbelly fish... You have any on you?',12340),
	 (5344,6,6,'You do want payment, do you not?',12340),
	 (5321,0,0,'Has Kerlonian arrived?',12340),
	 (5341,25,25,'Bow your head in my presence, $r. I am a noble, after all, and you are a copperless peasant.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5342,0,0,'Secure my fortune and share in the spoils.',12340),
	 (5343,25,25,'Bow your head in my presence, $R. I am a noble, after all, and you are a copperless peasant.',12340),
	 (5302,4,4,'For the glory of the Horde!',12340),
	 (5305,5,5,'His apron! Where is it?',12340),
	 (5306,5,5,'Legend states that one use of Vosh''gajin''s snakestone will keep an axe razor sharp for a 1000 years!',12340),
	 (5307,6,6,'Have you forgotten what it is that you were tasked with, $N?',12340),
	 (5282,1,0,'Compassion is what separates us from the animals, $N. Remember that...',12340),
	 (5283,1,1,'Ah, ain''t nothing like a good forge tan. Ye can tell who''s got the really good tans by their apron lines.',12340),
	 (5284,0,0,'<Ironus is busy stacking gold coins into neat little piles.>',12340),
	 (5301,1,1,'I will pound the steel until the breath itself has been taken from me.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5252,6,0,'It has been some time since you left, $N. How have you fared?',12340),
	 (5253,0,0,'Yes, $R?',12340),
	 (5261,6,6,NULL,12340),
	 (5262,25,0,'What have you got there, $N?',12340),
	 (5263,1,1,'The Baron has slain more people than you have most likely seen in your lifetime.',12340),
	 (5264,1,0,NULL,12340),
	 (5265,1,0,NULL,12340),
	 (5281,1,0,'',12340),
	 (5247,0,0,'The relic must be placed in the hands of only the most trustworthy. It can not be stolen again...',12340),
	 (5248,1,0,'Currrrrsed... Forevvvverrrr...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5249,1,0,'',12340),
	 (5250,1,0,'',12340),
	 (5251,1,5,'Remember, $N - we must be tolerant yet rigid in our beliefs!',12340),
	 (5246,0,0,'It is only in the pages of the sacred writings that I will be able to discern whether or not I can help you...',12340),
	 (5244,1,0,'',12340),
	 (5245,0,0,'Why have you come here?',12340),
	 (5243,1,1,'Be wary, not all supply crates will have survived the destruction of the city. The Scourge dare not touch the water but surely the holy water will not prevent vermin infestations.',12340),
	 (5242,1,1,'Without Fel''dan, the Shadow Council will hopefully lose focus and start infighting. They will struggle with one another for control and hoard assets for future plans. That will be an opportune time to devastate them and their demon slaves.',12340),
	 (5238,1,0,'',12340),
	 (5241,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5237,1,0,'',12340),
	 (5236,1,0,'Gahrron''s Withering houses the last cauldron that we need to acquire access to here in the west. Once we have a sample of the plague from that cauldron, we will be able to introduce our reagents into the environment through four separate vessels! The Scourge will be hard pressed to keep us out of all four, even with the power of Kel''Thuzad behind them.',12340),
	 (5235,1,0,'An access panel to the cauldron remains securely fastened. In order to open it, you will need to find the key.',12340),
	 (5234,1,0,'Once we successfully analysis the sample drawn from the Writhing Haunt''s cauldron, it will provide us with a third avenue to deliver a devastating counter agent against the Scourge!',12340),
	 (5233,1,0,'An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key. ',12340),
	 (5232,1,0,'We know that each cauldron employs a different mix of reagents to generate its plague-inducing toxin; likewise, we know that we will need to develop a counter agent that is unique for each cauldron. Your sample from Dalson''s Tears will be the key to figure out that cauldron''s distinct reagent requirement.',12340),
	 (5231,1,0,'An access panel to the cauldron remains securely fastened. In order to open it, you will need to find the key.',12340),
	 (5230,6,0,'Welcome back to the relative safety of the Bulwark, $N. What progress on the cauldrons do you have to report?',12340),
	 (5228,1,0,'',12340),
	 (5229,1,0,'An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key. ',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5227,1,0,'The Scourge''s plague cauldron stands before you, spewing vast amounts of toxins into the air.  A small, non-descript access panel lies in the base of the cauldron''s vast platform.$B$BHaving already defeated the cauldron lord and acquired its key, you are free to add the appropriate reagents to the cauldron to make a counter agent to the plague.',12340),
	 (5226,1,0,'Gahrron''s Withering houses the last cauldron here in the east that we need access to.  Once we have a sample of the plague it spews forth, we will be able to introduce our reagents into the environment through four separate vessels!  The Scourge will be hard pressed to keep us out of all four, even with the power of Kel''Thuzad behind them.',12340),
	 (5225,0,0,'An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.',12340),
	 (5224,0,0,'The Scourge''s plague cauldron stands before you, spewing vast amounts of toxins into the air.  A small, non-descript access panel lies in the base of the cauldron''s vast platform.$B$BHaving already defeated the cauldron lord and acquired its key, you are free to add the appropriate reagents to the cauldron to make a counter agent to the plague.',12340),
	 (5223,1,0,'Once we successfully analyze the sample drawn from the Writhing Haunt''s cauldron, it will provide us with a third avenue to deliver a devastating counter agent onto the Scourge!',12340),
	 (5222,0,0,'An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.',12340),
	 (5221,1,0,'The Scourge''s plague cauldron stands before you, spewing vast amounts of toxins into the air.  A small, non-descript access panel lies in the base of the cauldron''s vast platform.$B$BHaving already defeated the cauldron lord and acquired its key, you are free to add the appropriate reagents to the cauldron to make a counter agent to the plague.',12340),
	 (5220,1,0,'We know that each cauldron employs a different mix of reagents to generate its plague-inducing toxin; likewise, we know that we will need to develop a counter agent that is unique for each cauldron.  Your sample from Dalson''s Tears will be the key to figure out that cauldron''s distinct reagent requirement. ',12340),
	 (5219,0,0,'An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.',12340),
	 (5217,3,0,'Welcome back to the relative safety of Chillwind Camp, $N.  What progress on the cauldrons do you have to report?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5218,0,0,'The Scourge''s plague cauldron stands before you, spewing vast amounts of toxins into the air.  A small, non-descript access panel lies in the base of the cauldron''s vast platform.$B$BHaving already defeated the cauldron lord and acquired its key, you are free to add the appropriate reagents to the cauldron to make a counter agent to the plague.',12340),
	 (5215,1,0,NULL,12340),
	 (5216,0,0,'An access panel to the cauldron remains securely fastened.  In order to open it, you will need to find the key.
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5203,1,0,'You look winded, $n. Are you all right, or is something wrong?',12340),
	 (5202,6,0,'I begin to wonder if I''ll ever escape this cage.$b$bIt''s only a matter of time before they sacrifice me to whatever demons they worship. The monsters!',12340),
	 (5168,0,0,'Do you have the relics, $N?',12340),
	 (5181,0,0,'Did you find the skull and the sword, $N?',12340),
	 (5201,1,1,'The furbolgs seem to suffer from such paranoia...',12340),
	 (5166,273,273,'You have chosen wisely, $R.',12340),
	 (5167,1,1,'Such an item has never been crafted!',12340),
	 (5164,1,0,'',12340),
	 (5165,1,1,'The braziers must be extinguished if we are to have any hope of being prepared for a much greater battle. Going in to the dragon''s lair without any knowledge is a fool''s errand. And this is much worse than a dragon. The Shadow Council are solely responsible for a great number of crimes and atrocities. We''ll have to work quickly if we''re to stop them.',12340),
	 (5162,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5163,5,5,'I can''t wait to hear how my friends react!$B$BThey''ll never expect it!',12340),
	 (5160,2,2,'It is good to see you, $N.',12340),
	 (5161,1,0,'',12340),
	 (5159,2,0,'Ah, I see you''ve returned, $N. Good. Did you find Islen in the Barrens? Or do we have to find another way to accomplish our goals?',12340),
	 (5158,2,0,'I sense you are not just a simple traveler looking for the path to Ratchet. Come, sit and rest at our camp. Speak to me when you''re ready.',12340),
	 (5157,6,6,'Once we have the waters from the Moon Well, we will purify it and use it to extinguish the braziers of protection within Shadow Hold. That should allow me ample time to see into the chambers even deeper and discern who actually leads this... cult.$b$bI pray the Earthmother is with us.',12340),
	 (5156,1,1,'I hope your search goes well, $N. I haven''t started heading that far north, but I will admit, the thought of crossing the path of an infernal at any point scares me just a little. The creatures are brainless, but still quite intimidating.',12340),
	 (5154,6,6,'Did you find the book, $N?',12340),
	 (5155,1,6,'How goes your fight, $N? I know the shedding of blood as proof of honor can be disgusting to some, but you must understand that it serves two goals: you make my task easier by hurting their numbers, and we gain a respect for each other that will only make us stronger in times to come.$B$BI hope you understand.',12340),
	 (5151,0,0,'Do you have my hypercapacitor?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5152,1,0,'',12340),
	 (5153,6,0,'There is something timely about your visit.  You''re not from the future, are you?',12340),
	 (5150,0,0,'Dadanga looks up at you as you approach her. She seems to be hoping for something...$B$BShe''s probably hungry!$B$BThere''s got to be something growing in the crater that would be just the perfect snack for a large herbivore. Dadanga''s a big girl; whatever you bring her, there would need to be a lot of it!',12340),
	 (5149,0,0,'Did you find my doll?',12340),
	 (5148,1,0,'Nature is a force that must be appeased before you hope to learn how to bend its will into your leather garments. Bring me your offering to this force, and I will make sure you are heard.',12340),
	 (5147,0,0,'Have you any news of that murderous Arnak Grimtotem?',12340),
	 (5146,1,1,'Making this kind of leather-based armor requires patience and dedication. Once you have cast your lot with the elements, there is no turning your back on them. Bring me proof of your worthiness, and we''ll get started.',12340),
	 (5145,1,1,'If you''re ready to commit to a permanent decision by becoming a dragonscale leatherworker, then I''m ready to take you on as a student. Just bring to me the things I asked for, and we''ll begin your education.',12340),
	 (5144,1,0,'Making this kind of leather-based armor requires patience and dedication. Once you have cast your lot with the elements, there is no turning your back on them. Bring me proof of your worthiness, and we''ll get started.',12340),
	 (5141,1,0,'If you''re ready to commit to a permanent decision by becoming a dragonscale leatherworker, then I''m ready to take you on as a student. Just bring to me the things I asked for, and we''ll begin your education.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5142,1,0,'',12340),
	 (5143,1,1,'Nature is a force that must be appeased before you hope to learn how to bend its will into your leather garments. Bring me your offering to this force, and I will make sure you are heard.',12340),
	 (5123,6,0,'Now, what''s this, $N?',12340),
	 (5124,1,0,'Time is money, $N and I don''t have much of either.',12340),
	 (5125,1,0,'',12340),
	 (5126,1,0,NULL,12340),
	 (5127,1,0,'Tempt not...',12340),
	 (5128,2,0,'The Emerald Circle is friendly to all, $R. What can I do for you?',12340),
	 (5102,1,6,'Is it done?',12340),
	 (5103,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5121,1,0,'Maybe you will find out more in Winterfall Village, $N.',12340),
	 (5122,1,0,'The power of this chapel gives me the strength to resist the corruption in my heart.  If I leave it, I will become a death knight.   But there is a medallion, the medallion of faith, that will give me the strength I need to leave.$B$BPlease, $N, retrieve the medallion.  It is guarded by Malor the Zealous, a crazed member of the Scarlet Crusade who resides deep in the Scarlet Bastion in western Stratholme.',12340),
	 (5098,1,0,'Once the towers are marked, they''ll become top priority targets for our attack on Andorhal. I suspect that once we neutralize the towers, the main threat of Andorhal will emerge. From that point on, we''ll have a straight-up fight for control of the city!$b$bYou''re back to report success, yes? Don''t forget the beacon torch as well; we must maintain control of our materiel.',12340),
	 (5093,1,0,'',12340),
	 (5094,1,0,'',12340),
	 (5095,1,0,NULL,12340),
	 (5096,1,0,NULL,12340),
	 (5097,1,1,'Once the towers are marked, they''ll become top priority targets for our attack on Andorhal. I suspect that once we neutralize the towers, the main threat of Andorhal will emerge. From that point on, we''ll have a straight-up fight for control of the city!$B$Byou''re back to report success, yes? Don''t forget the beacon torch as well; we must maintain control of our materiel.',12340),
	 (5089,6,6,'What have you got there, $N?',12340),
	 (5090,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5091,1,0,'',12340),
	 (5092,1,25,'I want you to prepare for the worst, $N - dig deep.  The task in front of us will not be easy.  As we rally our forces here to eventually strike out against the Scourge, you will be part of our advance effort that takes the fight to them!  Your assigned mission in Sorrow Hill will begin our path to victory!',12340),
	 (5086,0,0,'I think we are beginning to uncover what is happening here, $N.',12340),
	 (5087,1,1,'We''ll see what happens when the Winterfall don''t get their firewater!',12340),
	 (5088,1,1,'Have you slain the vicious serpent Arikara, $N?',12340),
	 (5085,6,0,'I hope you found something, $N. The Winterfall are becoming increasingly aggressive!',12340),
	 (5084,1,0,NULL,12340),
	 (5083,0,0,'What is that you have found?',12340),
	 (5081,1,0,'Status?',12340),
	 (5082,1,0,'I appreciate your help!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5067,6,6,'Unless you''ve got everything I need, you''re wasting my time.',12340),
	 (5068,6,6,'Unless you''ve got everything I need, you''re wasting my time.',12340),
	 (5066,1,0,'',12340),
	 (5065,6,6,'Do you have the tablets?  I fear their texts will reveal a great threat to our world.',12340),
	 (5064,6,6,'Have you discovered what the Grimtotem are up to?',12340),
	 (5062,0,0,'So, Motega Firemane sends word of Arikara... well now that is grave news.$B$B<Magatha looks around.>$B$BArikara is a deadly creature born only to seek vengeance against those who have committed heinous acts.$B$B<Magatha smiles.>',12340),
	 (5063,6,6,'Unless you''ve got everything I need, you''re wasting my time.',12340),
	 (5061,1,0,'Your return to Darnassus is not without heralding, though I will need proof of your lessons learned in Moonglade before I will teach you your aquatic form.$B$BDo you have the Pendant of the Sea Lion?',12340),
	 (5060,0,0,'An extremely sturdy cabinet stands before you, securely fastened shut by a built-in lock.  The front of the cabinet is deeply scratched and marked.  This could be surmised as being from numerous and violent failed attempts to reveal whatever secrets the cabinet currently obfuscates from view.$B$BIf you are going to open this cabinet, you will need to find the key.',12340),
	 (5057,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5058,1,0,'',12340),
	 (5059,0,0,'The door to the outhouse has begun to splinter at the edges of the frame as though it has been repeatedly and incessantly tried to be forced open.  It is currently locked up tight from the outside of the outhouse.$B$BAs you rattle the door, you hear a guttural moaning come from inside!  Whatever is inside there, it certainly does not sound friendly.',12340),
	 (5054,1,0,'Go now, $c. Seek out Ursius.',12340),
	 (5055,1,25,'Brumeran calls out to you, $N.',12340),
	 (5056,1,1,'Shy-Rotam is bold and unforgiving; she will defend her kind with fervent enthusiasm.',12340),
	 (5052,1,0,'Our tribes flock to the thorny areas throughout the Barrens <snort> because they are holy places, but none as holy as Razorfen. Agamaggan''s body makes up the entirety of the Razorfen, <snort> but the Downs are especially protected because the entrance is made from his great maw! <snort> It will swallow whole those not loyal to him, and spit out their bodies after he''s chewed them up! <snort>$B$BAgamaggan has left his body behind to protect us, and he gives of his spirit so we may protect him. <snort>',12340),
	 (5051,0,0,'John, don''t let the ghouls get you... don''t let the ghouls get me... nasty ghouls... our charm will keep us safe.',12340),
	 (5050,0,0,'John, sweetheart... is that you?  I''m so cold all the sudden...',12340),
	 (5049,18,0,'Every time someone steps on a cockroach, I cry. Please don''t make me cry.',12340),
	 (5047,0,0,'Yea?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5048,25,0,'I would tell you to get off my lawn, but as you can see I don''t have one.',12340),
	 (5046,0,0,'All those who <snort> enter battle have need of protection. Their bones must be strong. Their skin tough. <snort> My tribe knows this as well, and to add to the natural protection our quills and hide give us, <snort> we often call upon Agamaggan to protect us from harm before we go to war.$B$BBring me 4 blood shards <snort> and I will grant you the same protection.',12340),
	 (5045,0,0,'Warriors of all types <snort> have need of a strong spirit. It drives you to greater feats when all hope has been lost. This is not unknown to the <snort> Razormane. We are a spiritual tribe--we are more proud of our connection to Agamaggan than our prowess <snort> in battle.$B$BBring me 4 blood shards and I will bless your spirit for battle. <snort>',12340),
	 (5043,0,0,'My tribes greatest scouts are said to be unrivaled in their accuracy, and no rogue <snort> could measure up to their quickness in battle.$B$BBring me 4 blood shards and I will make you even more agile than any quilboar born.',12340),
	 (5044,0,0,'The shaman and geomancers of the quilboar tribes <snort> call upon the strength of Agamaggan to help them in battle and in their rituals, $r.$B$BIf you too wish the added power of Agamaggan''s blessing with your spells, then bring me 4 blood shards and Mangletooth will aid you. <snort>',12340),
	 (5042,0,0,'I will need 4 blood shards if you wish Agamaggan''s strength, $r.$B$BYour foes will cower before your strength were you to be given this blessing. <snort>$B$BThe Razormane''s greatest warriors are infused with such power!',12340),
	 (5041,6,6,'How goes your search for the supplies, $N? I trust the quilboar fall under your strength easily.',12340),
	 (5023,6,0,'Are you here to seek the assistance of the Undercity census, or just to ask me if someone you knew is dead? I get asked that a lot.',12340),
	 (5002,1,0,'Ah, $N. It has been a long time.',12340),
	 (5021,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (5022,2,0,'Welcome to the office of the Stormwind census.  If you are in need of information on our populace, then I can assist you.',12340),
	 (5001,6,6,'Any luck?',12340),
	 (4987,2,0,'On behalf of the Cenarion Circle, I bid you welcome to this enclave, $C. What business do you have with us?',12340),
	 (4986,2,0,'On behalf of the Cenarion Circle, I bid you welcome to this enclave, $c.  What business do you have with us?',12340),
	 (4985,1,0,'I hear your footsteps, $N.  My vision has faded from me, but I still am able to sense things around me.  Have you ended the misery of the disease-ridden grizzlies?',12340),
	 (4983,5,5,'Where''s the goblin???',12340),
	 (4984,1,0,'The wolves that are infected with the plague must be put down, $N.  The disease they carry cannot be cured.  I tried... I tried until I succumbed to the plague myself.',12340),
	 (4976,6,6,'How goes your search for Tabetha and the orb, $N?$B$BTabetha has been more than useful when it comes to matters of the arcane. I''m sure she would have no problem aiding you if you''re able to find her.',12340),
	 (4981,1,0,'',12340),
	 (4982,6,6,'Any luck?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4974,0,0,'<Thrall grunts.>',12340),
	 (4975,1,0,'',12340),
	 (4973,1,1,'The watches of Andorhal, much like the large clock on the ruins of the town hall, all are frozen in time at three o''clock.  This was when the full effects of the plague first spread out over the city, choking the life out of it.$B$BAs much as we all may regret what happened that day, it has shaped the flow of time as you mortals perceive it.  The bronze dragonflight must persevere in protecting the timeline!',12340),
	 (4971,1,1,'Temporal parasites are a common malady present wherever the flow of time has been tampered with.  I sense that many are present, and this is disturbing.$B$BRooting out whatever ones you can find will help me be able to take a better hold on the deteriorating temporal situation here.  I will be able to sense when this has been achieved.',12340),
	 (4972,1,1,'The time trinkets I seek are simple devices.  They are watches mainly, and their hands are trapped forever when the plague first ravaged Andorhal.$B$BTime is never ending, and the watches you bring to me will invariably find themselves counted out back to their homes... that is, so long as the disturbances continue here.',12340),
	 (4965,1,0,'',12340),
	 (4966,1,0,'',12340),
	 (4967,1,0,'',12340),
	 (4968,1,0,'',12340),
	 (4969,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4970,1,1,'Discipline and determination are your goals. I may ask you to do a simple task many times; you must perform to the best of your ability each time.',12340),
	 (4964,1,0,'',12340),
	 (4963,6,6,'Yes, $N? Have you chosen? Infernal or felhound?$B$BEach choice is personal and should reflect your strengths and weaknesses. It is not unheard of for a $C to enhance themselves further instead of making up in areas they lack. Sometimes overpowering an enemy is just as strong a tactic than becoming a more balanced spell caster.',12340),
	 (4962,6,6,'Yes, $N? Have you chosen? Infernal or felhound?$B$BEach choice is personal and should reflect your strengths and weaknesses. It is not unheard of for a $C to enhance themselves further instead of making up in areas they lack. Sometimes overpowering an enemy is just as strong a tactic than becoming a more balanced spell caster.',12340),
	 (4961,1,1,'You''ll have to kill that demon to remove its presence permanently from the orb, $N.',12340),
	 (4941,1,0,'Can you not see that I must not be interrupted?',12340),
	 (4907,1,0,'',12340),
	 (4921,1,6,'Have you found any sign of her at all? The pain in my chest tells me that the worst has happened, but I have hope you will find her safe and sound.',12340),
	 (4904,1,0,'Thalia Amberhide:',12340),
	 (4906,1,20,'Please, put and end to the suffering of Felwood''s creatures.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4881,1,0,'',12340),
	 (4882,1,0,'Reporting for another assignment?',12340),
	 (4883,6,6,'How may I help you, $N?',12340),
	 (4901,1,0,'',12340),
	 (4902,1,0,'',12340),
	 (4903,66,66,'<Warlord Goretooth salutes.>',12340),
	 (4867,1,0,'Ah! Do you have my mojo?',12340),
	 (4866,1,35,'<Ragged John pinches you.>',12340),
	 (4865,1,0,'',12340),
	 (4864,1,1,'Aye... Tell me the news.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4863,1,0,'',12340),
	 (4862,6,6,'Are those spider eggs in your pack or are you just happy to see me?',12340),
	 (4861,1,0,'',12340),
	 (4822,6,0,'I wish they''d make more flavors of ice cream other than strawberry, but I guess I''m lucky that strawberry is my favorite!',12340),
	 (4841,1,25,'Come now $N, I know you haven''t killed your share yet. Hunt them down, and I shall give you a reward for my gratitude.',12340),
	 (4842,1,0,'The water in the springs seems to have some very odd properties... I am still unsure of what it means...',12340),
	 (4813,1,0,'',12340),
	 (4821,1,1,'I must know more about this mysterious egg, who knows what will hatch from it.',12340),
	 (4808,1,0,'It''s cold up here! I hope you brought me a blanket!',12340),
	 (4809,6,6,'Do you have the chillwind horns, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4810,6,6,'$N! Did you talk to Felnok? Did you bring the components I need?',12340),
	 (4811,1,6,'What do you have to report on that red crystal? Does it even really exist?',12340),
	 (4812,1,0,'The crystal looks very alien against the wooded scenery of Darkshore. You think you hear a very slight humming coming from deep within it.',12340),
	 (4807,1,1,'In Winterspring, you will fight creatures of might dat seem to possess an innate magic ability. These wildkin can use strong magics. If you wish ta gain an increase in your intellect bring me da E''ko you find from any a'' da owlbeasts you find der.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.$B$B',12340),
	 (4806,1,1,'In Winterspring, you have fought da large ice giants called frostmaul. Sheer power and force is at their disposal. If you wish ta gain da force of da frostmaul, bring me da E''ko you find from dem.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.',12340),
	 (4805,1,1,'In Winterspring, you will fight great creatures called da ice thistle yeti. These beasts move slowly, but dey are able to evade many blows from da protection their thick fur provides dem. If you wish ta gain da ability to dodge attacks, bring me da E''ko you find from dem.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.$B$B',12340),
	 (4803,1,1,'In Winterspring, you will find large bears wit extremely thick hides. These Shardtooth bears gain much protection from what dey can withstand. If you wish ta gain the resistance against fire, bring me da E''ko you find from da Shardtooth.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.$B$B',12340),
	 (4804,1,1,'In Winterspring, you will fight great flying creatures called da Chillwind. These beasts possess da power ta wield frost magics. If you wish ta gain resistance ta frost, bring me da E''ko you find from da Chillwind.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.$B$B',12340),
	 (4802,1,1,'In Winterspring, you will fight misguided creatures known as da Winterfall furbolg. Through the wishes of their leader, dey have gained incredible strength. If you wish ta gain the power a'' da Winterfall, bring me da E''ko you find from dem.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.',12340),
	 (4801,1,1,'In Winterspring, you will fight great cats called frostsabers. These beasts possess incredible speed an'' cunning. If you wish ta gain the speed a'' da frostsaber, bring me da E''ko you find from dem.$B$BRememba, you must have the Cache of Mau''ari in your inventory if you want ta hunt for E''ko.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4785,1,0,'',12340),
	 (4786,1,0,'A moment, $n...',12340),
	 (4787,0,0,'Do you have the ancient egg? I sense great forces stirring, and I fear that time grows short.',12340),
	 (4788,6,6,'Have you been to the spire, $N? Do you have the fifth and sixth tables?',12340),
	 (4784,1,1,'Soon, $N. I promise you. The robe will be more than adequate for your needs and certainly give you an edge over your opponents.',12340),
	 (4783,1,1,'Desolace is not a kind area: naga, giants, satyr, the Burning Legion... all of those and warring centaur clans all make the land dangerous if you''re not careful.$B$BLike I said before, it will not only test your strength and cunning, but also your patience. Be wary in those lands, $N.',12340),
	 (4782,1,0,'',12340),
	 (4781,2,2,'Gold bars, yes... yes. Bring me one and we''ll see what we can do about spinning some thread for you. Until then, I would suggest you focus your efforts on becoming more powerful. Your toughest trials are still ahead. And trust me... you''ll wish you were more prepared, regardless of how powerful you think you might be.',12340),
	 (4769,1,0,'',12340),
	 (4770,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4771,1,25,'Remember, $N - we must be tolerant yet rigid in our beliefs!',12340),
	 (4768,6,6,'Have you found the Tablet, $N?  I yearn to delve into its secrets.',12340),
	 (4767,6,6,'$N, have you retrieved the wyvern eggs that I seek? I''m really anxious to start my wind rider training!',12340),
	 (4766,1,0,'',12340),
	 (4765,0,0,'I was told a messenger would come. One with a gift from Blackrock Spire.$B$BAre you he?',12340),
	 (4764,0,0,'Do you have the clasp, $N? My patron will pay very handsomely for it.',12340),
	 (4763,0,0,'The Talisman of Corruption is a sinister device that only serves to pervert the balance of nature. When you obtain this item from whatever satyr is tormenting the furbolgs and bring it to me for disposal, we will have won a great victory this day!',12340),
	 (4761,1,0,'',12340),
	 (4762,1,1,'The pollution of the Cliffspring River is but the start of an alarming trend here in Darkshore.  The sample you provide will help us formalize a plan... a plan of attack, I am starting to suspect.',12340),
	 (4743,1,0,'Waste no time, $N. Nefarian works feverishly to unleash his evil upon our world.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4740,1,0,'Greetings $c - what may the Sentinels assist you with today? Perhaps you are here to inquire about the bounty on Murkdeep?',12340),
	 (4741,1,0,'Don''t tell me that you''re too scared! Get going!',12340),
	 (4742,1,0,'Courage and patience above all else, $N!',12340),
	 (4739,1,0,'',12340),
	 (4738,1,0,'',12340),
	 (4736,1,0,'',12340),
	 (4737,1,0,'',12340),
	 (4735,6,6,'Do you have the eggs, $N?  My patron heard you were collecting them for me, and is very eager to get his hands on them!',12340),
	 (4734,6,6,'$N, did you test the eggscilloscope?',12340),
	 (4733,1,0,'Thanks be to Elune - I am glad to see you again, dear $N.  The Temple of the Moon''s work on the strange beaching phenomena continues here in Darkshore.  Might you have anything additional to offer us?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4732,1,0,'Greetings once again $N - do you have any more discoveries to report to the Temple of the Moon?',12340),
	 (4731,3,0,'Hello again, $N.  The work you have done on behalf of the Temple of the Moon has been outstanding.  Are we to be blessed with more of your effort on our behalf?',12340),
	 (4730,3,0,'Hello again, $N!  Are you here to report on another discovery?',12340),
	 (4729,0,0,'<Kibler is busy arguing with Toucan Stan.>',12340),
	 (4728,3,0,'Greetings once again, $N!  What brings you back to Auberdine?  Are you here to report on another discovery, perhaps?',12340),
	 (4727,3,0,'Hello again, $N! Are you here to report on another discovery?',12340),
	 (4726,6,6,'Do you have the broodling essence, $N?  I can''t wait to study it.$B$BAnd besides that... my patron is not the type of person you want to disappoint.',12340),
	 (4725,1,0,'It is a pleasure to see you again, $N. We are making great strives in uncovering the mystery of why majestic sea creatures beach themselves on the Darkshore coastline, but with every question answered, two more are raised it seems.$b$bAre you here to offer us more aid in our research?',12340),
	 (4724,1,1,'With the pack mistress slain, we can begin to thin out the worg sentries of the Spire and eventually make some headway into the city.',12340),
	 (4723,3,0,'Hello again, $N! Are you here to report on another discovery?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4722,3,0,'Hello $N - do you have any discoveries of creatures that have washed ashore to report on?',12340),
	 (4721,1,25,'You know your orders, $N.',12340),
	 (4701,1,6,'Have you discovered and dealt with the source of the worg menace?',12340),
	 (4681,1,1,'Once you have investigated the creature''s remains in the water to the west of here, I should be able to file a proper report with the Temple of the Moon in Darnassus. Perhaps then we will be closer to discovering the reason why these unfortunate creatures choose to end their lives beached on the coast of Darkshore.',12340),
	 (4661,1,0,'You take a sample of slime from Felwood and place some of it into the various tubes and beakers on the table. As things begin to boil and spurt, the slime changes colors. When the process slows down and the liquids calm, you see a small petri dish with your altered Felwood slime samples in it along with some other remnants.',12340),
	 (4642,1,0,'How goes the experiment, $N? I will continue to study the samples you''ve recovered for me--I am starting to see why Lady Sylvanas is so interested in these creatures. If they are truly part of the Old Gods, then who knows how it can be used to our benefit.',12340),
	 (4641,6,0,'The carapace of a scorpid isn''t so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.',12340),
	 (4621,1,0,'Yer back already, ya blasted tar! Haves ye done as I''ve ordered? Fail us, and ye will be walkin'' the plank.$B$BArrrrr...',12340),
	 (4605,1,0,'',12340),
	 (4606,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4604,1,0,'The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!',12340),
	 (4603,1,0,'The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!',12340),
	 (4602,1,0,'Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.',12340),
	 (4601,1,0,'It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working. So long as both are present, the Sparklematic 5200 should work...',12340),
	 (4581,6,0,'Do you have something for me?',12340),
	 (4561,1,0,'You take a sample of slime from Un''Goro Crater and place some of it into the various tubes and beakers on the table. As things begin to boil and spurt, the slime changes colors. When the process slows down and the liquids calm, you see a small petri dish with your purified Un''Goro slime samples in it along with some other remnants.',12340),
	 (4542,6,0,'What do you want, $C? An urgent message - for me?$b',12340),
	 (4521,1,25,'Report back to me after you have completed the task I gave you.',12340),
	 (4513,1,1,'So many things to consider. But what does it mean? And how does it affect the lives of the people of Azeroth?',12340),
	 (4510,2,2,'Elune''adore, $C.  What may I do for you today?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4511,2,2,'Zug zug!  What may I help you with today, $C?',12340),
	 (4512,1,1,'Some of the experiments I''ve done are fascinating. I think with a little more work, I''ll be able to figure out the nature of these creatures and how they play into how life developed on Azeroth... if they even have anything to do with it to begin with.$B$BOne of my biggest theories that isn''t well liked is the idea that oozes and slimes are tied to the creation of this planet... almost like they''re a secretion of it.$B$BBut I can''t prove or disprove it until I get more samples.',12340),
	 (4509,5,5,'They are fools, $N!  They cannot even think to look around them for a greater threat; their irrational hatred of the Alliance will be our undoing.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!$B$BI''m sorry, you bring news for my attention?',12340),
	 (4508,5,5,'They are fools, $N!  They cannot even think to look around them for a greater threat; their irrational hatred of the Horde will be the end of us all.  I do not know how much more proof I can give them of the silithid threat short of dropping them in one of the hives so they can see for themselves!$B$BI''m sorry, you bring news for my attention?',12340),
	 (4506,1,5,'Don''t tell me that you can''t go back there! Get going!',12340),
	 (4507,1,1,'Acquiring the queen''s brain for our research is absolutely imperative.  From what we have learned, we believe that these silithid are quite possibly being controlled by a malign intelligence.  I shudder to think what could control something as insidious as the silithid, $N.',12340),
	 (4504,4,4,'Tran''rek''s done it again -- this super sticky glue will be all the rage!',12340),
	 (4505,5,5,'This is of utmost importance. Be on your way, now.',12340),
	 (4502,6,6,'Is it true that the volcano in Un''Goro is active? I''m sure I could learn a lot with some ash from the volcano, $N.',12340),
	 (4503,0,0,'Every great vehicle needs a name... I was thinking I''d call it... Pwned!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4501,1,0,'To tell you the truth, I really wasn''t that worried about the strange creatures... Until the day that I saw it written on the side of a large stone.$B$BBEWARE OF PTERRORDAX$B$BWho could have written it? I don''t know, but it''s too creepy to just ignore!',12340),
	 (4492,1,0,'Wha... What?',12340),
	 (4493,1,0,'',12340),
	 (4494,1,0,'',12340),
	 (4496,1,1,'Finding a suitable scent gland might take a bit - the gland can''t be damaged, but the process of getting one certainly doesn''t lend itself to it. As for the soil, I''d assume it should be easy enough to find.$b$bAnyway, do you have the items I need to make the lure?',12340),
	 (4485,1,0,'',12340),
	 (4486,1,0,'',12340),
	 (4487,1,0,'',12340),
	 (4488,1,0,'',12340),
	 (4489,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4490,1,0,'',12340),
	 (4491,1,0,'I''ve been so worried about Ringo...',12340),
	 (4483,6,6,'If it is resilience you desire, thirty gold I require.',12340),
	 (4484,274,274,'Do not waste my time, $R. Give me what I require. Thirty gold and the components.',12340),
	 (4482,1,1,'Thirty gold, $R. Thirty gold and the required components.',12340),
	 (4481,1,1,'There is a price to pay for all things in this world. The price for the specific item that you seek is thirty gold pieces.$B$BNaturally, I shall retain the majority of the components which you collected. But worry not, you shall have your trinket.',12340),
	 (4467,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4466,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4465,0,0,'You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4464,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4463,25,25,'Present the components, mortal.$B$BI will also require payment in the form of thirty gold pieces for this creation.',12340),
	 (4462,1,0,'You have found a sickly, corrupted version of what appears to be a Night Dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4461,1,0,'You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4450,6,6,'Yes, yes? What can I do for you, $R? I''m awfully busy and have many patrons requesting my services. Perhaps you can speed things up. I don''t mean to be rude, but I just don''t have the time if I''m to catch up on all my work.',12340),
	 (4451,1,0,'*cough*$b$bWho is it? Can''t ya see I''m busy?',12340),
	 (4449,0,0,'I ain''t got all day! Get me those pieces of silk cloth! I mean geologists. Get those geologists! They deserve to feel my, well... your wrath.',12340),
	 (4448,1,0,'You have found a sickly, corrupted version of what appears to be a Night Dragon plant. The fruits that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4447,0,0,'You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4445,1,0,'You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4446,1,0,'You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4443,1,0,'You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4444,0,0,'You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4421,1,0,'The corruption here drives the creatures into madness...',12340),
	 (4441,1,1,'The water will hopefully release the spirit of the ancient, and allow it to be at peace.',12340),
	 (4442,1,0,'',12340),
	 (4401,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4402,6,6,'Have you finished collecting cactus apples?',12340),
	 (4403,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4385,1,0,'The Pylon table allows you to combine red power crystals with yellow power crystals.$B$BAccording to J.D.''s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.',12340),
	 (4386,1,0,'The Pylon table allows you to combine blue power crystals with yellow power crystals.$B$BAccording to J.D.''s manual, this combination can be used to create a shield that does damage to enemies.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4383,1,0,'The Pylon table allows you to combine green power crystals with red power crystals.$B$BAccording to J.D.''s manual, this combination can be used to strengthen the protection you have against physical damage.',12340),
	 (4384,1,0,'The Pylon table allows you to combine red power crystals with blue power crystals.$B$BAccording to J.D.''s manual, this combination can be used to weaken an enemy''s defenses.',12340),
	 (4361,1,0,'',12340),
	 (4362,1,0,'',12340),
	 (4363,1,0,'',12340),
	 (4381,1,0,'The Pylon table allows you to combine green power crystals with yellow power crystals.$B$BAccording to J.D.''s manual, this combination can be used to heal yourself or your allies.',12340),
	 (4382,1,0,'The Pylon table allows you to combine green power crystals with blue power crystals.$B$BAccording to J.D.''s manual, this combination can be used to increase your spirit.',12340),
	 (4321,1,0,'',12340),
	 (4322,1,0,'You look exhausted, $n. Perhaps you should have a seat by the fire and relax.',12340),
	 (4324,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4341,1,0,'',12340),
	 (4342,1,0,'Allow me to finish telling my story.',12340),
	 (4343,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4298,1,0,'',12340),
	 (4300,6,6,'Me clients are not so patient, $N. Have you gotten any of the claws yet?',12340),
	 (4301,1,1,'U''cha... the beast was magnificent. Huge and red, with teeth the size of daggers. His arms as thick as tree trunks, and as fast as any mountain lion I have ever laid eyes upon. You should consider yourself lucky to find such a test of bravery--my people would go generations without seeing such a creature.',12340),
	 (4296,0,0,'Do you have the writings of the Seven, $N?  Have you learned the secrets from their tablet?',12340),
	 (4297,6,6,'Find that meat yet, $N? Your little egg here''s just about ready to hatch. If he don''t have a good enough first meal, then he might not make it past his first week, and I''d hate for that to happen.$B$BCan''t much lie to ya, $N. I''m jealous of you gettin'' this egg to begin with. Don''t make me regret helpin'' ya out like this.',12340),
	 (4293,1,0,'I will need at least five corrupted samples for our control group, $N. Continue to gather Felwood slime samples until you''re able to give me that which we''ll need. The Lady Sylvanas decrees it...',12340),
	 (4294,6,0,'Yes, $N? How goes your search?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4295,5,5,'Oh, ale!  I would kill for some Dark Iron ale!!  Quick, I''m getting sober!  I know this because sobriety blurs my vision... and it''s making you look like the $r I slew last week!',12340),
	 (4292,2,2,'Do not let fear overpower you, $N. Fear is the great betrayer... you must remain strong!$B$BTake the meat, place it in the small valley, and then use the gland on it. Only then will death come for you.',12340),
	 (4290,1,1,'Do not take my words lightly, $N. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar''korwi and defeat him.',12340),
	 (4291,1,1,'Be careful, $N. Getting close to any of nest of eggs surely will provoke the mothers... even if you''ve already secured a gland from one. The mothers can be just as deadly as Lar''korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar''korwi out from hiding.',12340),
	 (4284,5,5,'I just know I''m onto something here, $N!',12340),
	 (4285,1,0,'Have you visited the pylon, $N?',12340),
	 (4286,1,1,'I can''t be bothered right now, $N. Me and Winky got a meeting to attend.',12340),
	 (4287,1,0,'Have you visited the pylon, $N?',12340),
	 (4288,1,0,'Have you visited the pylon, $N?',12340),
	 (4289,2,2,'Have the creatures here bested you already, $N?$B$BDo not be dissuaded so easily. Tracking and defeating the apes of Un''Goro is no simple task, even for a great hunter.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4281,2,0,'Welcome to Thalanaar, $C. Do you need assistance of some sort?',12340),
	 (4282,1,0,'Soon this grand subterfuge will be over.',12340),
	 (4283,0,0,'<Oralius is talking into a rather large, severed ogre ear.>$B$BBurning Steppes to control, come in control.',12340),
	 (4267,2,2,'Welcome to this blessed temple, friend.  Your arrival here from Feathermoon Stronghold has been foretold to me.  Do you have the report Shandris Feathermoon asked you to bring?',12340),
	 (4266,1,0,'',12340),
	 (4261,1,0,'',12340),
	 (4262,1,0,'<Jalinda appears to be staring at your head.>',12340),
	 (4263,1,6,'Is the fiend dead??',12340),
	 (4264,1,0,'<Marshal Windsor eyes the note in your hand.>$B$BWhat do you have there, $N?',12340),
	 (4265,1,0,'You have something to report, $n?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4223,1,0,'',12340),
	 (4224,1,0,'Have you spoken with John yet?',12340),
	 (4241,1,0,'',12340),
	 (4242,1,0,'',12340),
	 (4243,1,0,'',12340),
	 (4244,0,0,'The panel in which the mithril casing goes is still closed shut. The rest of A-Me 01 remains inert.',12340),
	 (4245,1,0,'Have you been able to help A-Me? That mithril casing you mentioned being destroyed was a good guess at what was wrong. I''m sure if you replace that, she''ll reactivate and be able to come home.',12340),
	 (4221,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4222,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4182,1,0,'How goes the dragon hunt?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4183,1,0,'Greetings, $N. Have we met before? You look vaguely familiar.',12340),
	 (4184,1,0,'What brings you to Stormwind Keep?',12340),
	 (4185,1,0,'<Bolvar watches you intently.>',12340),
	 (4186,1,0,'Any news from Bolvar?',12340),
	 (4201,1,0,'Do you have the ingredients?  The hole in my heart threatens to consume me!',12340),
	 (4161,0,0,'Remember the balance, $N. I wish you to develop an understanding and a strong empathy for the living forests.',12340),
	 (4181,1,0,'I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?',12340),
	 (4145,1,5,'Muigin needs to apologize first before I''ll talk to him again!',12340),
	 (4146,5,5,'This is exhausting, $N. Those things just won''t leave me alone!',12340),
	 (4147,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4148,1,1,'For the zapper to work, it needs a sample of the target creature. Head out into the crater and collect a Bloodpetal sprout. Then I can calibrate it to work on Muigin''s little friends...$b$bIf he weren''t so stubborn, we could be on our way home, already... But until then, I''ll just have to show him that his little prank doesn''t bother me at all!',12340),
	 (4143,0,1,'Larion''s still not speaking to me! He sure knows how to hold a grudge.',12340),
	 (4144,5,1,'Here''s the plan, $n: Go out and collect some bloodpetal sprouts -- you know, the plants that haven''t fully sprouted yet, and bring them here. Then I''ll see what the Atal''ai haze can do.$B$BYou may think I''m vengeful... Actually, you''d be right about that! $B$BTruth is, I know the way out of here, but until Larion will admit that I''m right, I''m staying right here!$B$BSo off with you, find those bloodpetal sprouts and let''s have some fun!',12340),
	 (4134,6,6,'Do you have the recipe for the Thunderbrew Lager, $N?',12340),
	 (4135,1,0,'',12340),
	 (4136,0,0,'Do you have Ribbly?  Or, at least a part of him?',12340),
	 (4141,11,11,'Larion''s got something coming, that''s for sure!',12340),
	 (4142,0,0,'I live out here in the forest... Peaceful.$B$BWell, at least I thought it would be. I get more visitors out here than I ever did when I lived in Ironforge!',12340),
	 (4130,1,0,'',12340),
	 (4131,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4132,1,0,'Has the Butcher of Blackrock been disposed of?',12340),
	 (4133,1,0,'',12340),
	 (4125,1,0,'',12340),
	 (4126,5,5,'Do you have the recipe, $N? I can''t stand the idea of those Dark Iron dwarves drinking my family''s drink!',12340),
	 (4127,2,2,'Ah, welcome back $N.  I hope that you were able to uncover some clue as to Raschal''s ultimate fate, as tragic as that may be.',12340),
	 (4128,1,0,'',12340),
	 (4129,6,0,'Ginro sent you, eh?$B$BMy psychometric readings are fairly draining on the psyche... but so are my losses at Kalimdor Hold ''Em.  They call me "King of the Bad Beats" here in the Stronghold.  Unlucky at cards... lucky at mastering the secrets of nature, I guess.$B$BAnyway, of course I''ll do it.  This may be just the breakthrough we need to uncover Raschal''s fate.  If you would hand me the knife, we can get started.',12340),
	 (4120,1,0,'Everything touched by the fel emanates a strange green glow... I sense it is evil, but at the same time, very powerful.',12340),
	 (4121,0,0,'I will take this traitorous filth, $N.',12340),
	 (4122,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4123,0,0,'Do you have the Heart of the Mountain?  To me, its value is without limit.',12340),
	 (4124,1,0,'',12340),
	 (4118,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4119,0,0,'You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4117,1,0,'You have found a sickly, corrupted version of what appears to be a whipper root plant. The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4115,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4116,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4113,0,0,'You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4114,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (4112,1,0,'The power of a disenchanted magical item is felt by the essence it creates. I''ve devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don''t need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.$b$bI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4111,1,0,'A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!$b$bWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.',12340),
	 (4110,1,0,'A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood''s corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.$b$bWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.',12340),
	 (4109,1,0,'If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.$b$bIf you have collected any tainted vitriol, I''ll give you some Cenarion plant salve I have already prepared.',12340),
	 (4108,1,1,'Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.$b$bIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.',12340),
	 (4107,1,0,'The power of a disenchanted magical item is felt by the essence it creates. I''ve devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve. You don''t need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.$b$bI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves. The essence is extremely potent - a little definitely goes a long way!',12340),
	 (4106,1,0,'A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood. I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve. When you skin your kills here in Felwood, be sure to have a beacon on you!$b$bWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.',12340),
	 (4105,1,0,'A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood''s corruption. My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.$b$bWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon. In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.',12340),
	 (4104,1,0,'If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal. I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve. You will then use that salve on plants you find in the wild that need saving.$b$bIf you have collected any tainted vitriol, I''ll give you some Cenarion plant salve I have already prepared.',12340),
	 (4103,1,1,'Possessing a Cenarion Beacon allows one to sea a corrupted soul shard on those tainted beasts that are put down for the greater good. I grind shards into a usable reagent that goes into making Cenarion plant salve. We will use that salve to turn corrupted plants into healthy ones again.$b$bIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.',12340),
	 (4102,5,5,'I know Felwood suffers, $N - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.$B$BBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4101,5,5,'I know Felwood suffers, $N - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.$B$BBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.',12340),
	 (4084,1,1,'I can tell you more of the power required to defeat Blazerunner, but first, you need to gather the things I require.',12340),
	 (4083,1,0,'The gems make no sound as they fall into depths of the chalice... ',12340),
	 (4081,1,6,'What is it, $r? Can''t you see I have a platoon to command?$B$B',12340),
	 (4082,1,6,'You again? I have to hand it to you, $N, you are tenacious.',12340),
	 (4063,6,6,'Was it him? Was he really alive?',12340),
	 (4062,6,0,'What have you got there, $R?',12340),
	 (4061,5,5,'Do not take this task lightly, $N!',12340),
	 (4041,0,1,'Bring me an Evoroot, and sure, I can make ya that Videre Elixir.$B$BI know all kinds of things about herbs and alchemy... Why, let me tell you the story about the time I transmuted gold from the cheese I was going to eat for lunch... hey... Where are you going?',12340),
	 (4024,6,0,'Has the giant been felled?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (4023,1,0,'<Cyrus''s eyes form two blazing spheres.>',12340),
	 (4022,1,0,'<Cyrus''s eyes form two blazing spheres.>',12340),
	 (4021,0,0,'Do you have the banner?',12340),
	 (4005,6,6,'So you''re back, eh? Hmm... Let me take a look at that, $N.',12340),
	 (4004,1,0,'',12340),
	 (4003,1,0,'<Princess Moira cowers in fear.>',12340),
	 (4002,1,0,'',12340),
	 (4001,1,0,'What brings you to these hallowed grounds?',12340),
	 (3982,1,5,'Defend yourself, fool!',12340),
	 (3981,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3962,1,1,'Blazerunner is almost invincible behind the aura he has created by using the Golden Flame. Only you have the power to remove it with the Silver Totem of Aquementas.',12340),
	 (3941,1,0,'',12340),
	 (3942,1,0,'',12340),
	 (3961,3,0,'Hi, again, $N!',12340),
	 (3924,0,0,'Do you have the manual?',12340),
	 (3923,0,0,'Mind your head! I don''t want it to get in the way of my work!',12340),
	 (3922,0,0,'Do you have the nugget slugs, $N? I''ve been eyeing this Samophlange and I can''t wait to tinker with it.',12340),
	 (3921,0,0,'I''m very busy with my work, $C. Unless you have something for me, it''d be best if you moved along...',12340),
	 (3913,1,0,'This must be the gravestone that Gaeriyan mentioned...',12340),
	 (3914,25,0,'Oh! I remember you! You are... No, don''t tell me!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3909,0,6,'Back already?',12340),
	 (3911,1,0,'Show them to me!',12340),
	 (3912,1,0,NULL,12340),
	 (3908,0,0,'My, my... So Linken did finally get around to sending me his sword.',12340),
	 (3907,5,5,'The flames will soon overtake these lands. Make haste, $N!',12340),
	 (3902,0,0,'Have you managed to scavenge up some useful items for us? There is no shame in reusing that which has been tossed aside. No one is going to give us any handouts - we Forsaken will fend for ourselves!',12340),
	 (3903,1,0,'',12340),
	 (3904,0,0,'Do you have my harvest, $N?',12340),
	 (3905,0,0,'You look to be in fine spirits! Come! Have a seat, and have a drink!',12340),
	 (3906,1,0,'The elements are still in disarray, $N.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3901,1,0,'Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village. Let''s hope you will fare better than them, yes? $b$b',12340),
	 (3884,3,0,'Hello there!  I and my companions are happy to see some living beings here other than overgrown savage beasts!  What brings you into the Un''Goro Crater?',12340),
	 (3883,6,6,'Do you have the sample of the Gorishi hive for me to study, $N?',12340),
	 (3882,0,0,'Think whatever you want of me, but they''re not going to care if the bones they get to research are from ones from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I''ll just be happy if we get out of here alive...',12340),
	 (3881,1,1,'If we''re going to have any chance of getting out of here alive, we''ll need our big crate of foodstuffs.  Also, getting at least some of our research equipment back would be a blessing in a sea of misery.',12340),
	 (3861,1,0,'The chicken stares at you with dark, cold eyes. It waits for you hungrily.$B$B"BACAAAW!$B$BCluck...cluck...cluck."',12340),
	 (3845,0,0,'Hi there. I''ve seen you before... Haven''t I?',12340),
	 (3844,1,0,'',12340),
	 (3843,6,0,'Greetin''s, $N. How can I be of service to ya?',12340),
	 (3842,1,1,'The longer I stay here, the more tempted I am to partake in these races, $N. Truly boggling...$B$BHave you found the elixirs yet? Once I can tell if the egg is going to be healthy or not, I''ll return it to you to hold onto until it''s prepared to hatch.$B$BLet me know.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3825,1,6,'So? Did you paint any pictures of the event?',12340),
	 (3841,3,0,'Why hello, $C.$B$BDon''t let my location fool you, I''m really not here for the races... as entertaining as they may be.$B$BI''m actually here in Thousand Needles investigating all I can to find out how salvageable the land is. It has become my crusade of sorts to revitalize and replenish the area with new, fertile soil. Perhaps I''ll find there''s a water source nearby.$B$BTell me you haven''t noticed how odd the transition between Feralas and Thousand Needles is. Strange magic was afoot when that happened.',12340),
	 (3824,6,6,'Oh glorious day! Have you returned with the head?',12340),
	 (3821,1,0,'',12340),
	 (3822,6,6,'Did you find Sha''ni? Is she ok?',12340),
	 (3823,1,25,'There is not nearly enough blood on your uniform, soldier!',12340),
	 (3804,1,1,'The Arch Druid is always looking for more morrowgrain for the Cenarion Circle''s research project on Un''Goro Crater. We take them in increments of ten, and award you with a cache of goods you should find useful. When you have ten, let me know and I will award you accordingly.',12340),
	 (3803,1,1,'The Arch Druid is always looking for additional morrowgrain for the Cenarion Circle''s continued research. We take them in increments of ten, and award you with a cache of goods you should find useful. When you have ten, let me know and I will reward you accordingly.',12340),
	 (3801,1,0,'',12340),
	 (3802,0,0,'The statue looms ominously above you.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3792,1,1,'Hello again, $N. My research is progressing fairly well, but if you have five more Morrowgrain I''d be happy to take them off your hands. Well... happy is a figurative term in this case; the more I am around them, the more uncomfortable I feel. Still, my research demands I buckle down and get through this.',12340),
	 (3791,1,1,'I''m looking for ten morrowgrain - that should be enough to at least get my research started.  I''ll no doubt burn through a lot of those going down wrong paths, but such is the nature of research.',12340),
	 (3787,1,0,'',12340),
	 (3788,1,0,'',12340),
	 (3789,1,0,'',12340),
	 (3790,1,0,'',12340),
	 (3786,6,6,'Yes $N, have you grown some morrowgrain for the Arch Druid''s important research?  The mysterious properties of Un''Goro Crater become clearer with each passing day, thanks to the help you are giving us.',12340),
	 (3784,1,0,'',12340),
	 (3785,6,6,'Yes $N, have you grown some morrowgrain for the Arch Druid''s important research? The mysterious properties of Un''Goro Crater become clearer with each passing day, thanks to the help you are giving us.',12340),
	 (3783,0,0,'I''ve got lots to get started on here. Please get me those furs as soon as you can!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3782,2,0,'Peace and serenity be yours, friend. You are here on business from the Arch Druid himself, yes?',12340),
	 (3781,2,0,'Peace and serenity be yours, friend. You are here on business from the Arch Druid himself, yes?',12340),
	 (3765,1,0,'',12340),
	 (3762,1,0,'',12340),
	 (3763,1,0,'',12340),
	 (3764,4,4,'Ah yes, the dirt. The Arch Druid wants twenty loads per adventurer, and twenty loads he shall get. Let those who conspire against us fall to the wayside!',12340),
	 (3761,25,25,'At ease, Private. If you''re here to unload soil from Un''Goro - outstanding then! Otherwise, disappear.',12340),
	 (3721,1,0,'',12340),
	 (3741,24,24,'Hi. I miss my necklace. My daddy got it for me. Daddy says that there are monsters in the lake. Did you beat up any monsters?',12340),
	 (3681,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3701,1,6,'Do you bring new information?',12340),
	 (3702,1,0,'Allow me to finish telling you the story of Thaurissan.',12340),
	 (3661,0,0,'Try to avoid them if you can, $N. The Wildkin may misread your interest as an intent to do them harm...',12340),
	 (3647,1,0,'In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.',12340),
	 (3646,1,0,'In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.',12340),
	 (3645,1,0,'In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.',12340),
	 (3644,1,0,'In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.',12340),
	 (3643,1,1,'Once I receive your crafted engineering items for my review, I will hand you a genuine Gnome Engineer Membership Card! So long as the card is valid, you will have unlimited access to any gnome engineer trainer anywhere in the world.',12340),
	 (3642,0,0,'If you''ve signed the document and are ready to hand it to me, then that is that.$B$BWhile I may vehemently disagree with Gnomeregan - especially that fool Tinkmaster Overspark - politically, the Pledge of Secrecy transcends everything else! You must agree to commit a single path and stay true to that path throughout your life.',12340),
	 (3641,1,1,'Once I receive your crafted engineering items for my review, I will hand you a genuine Gnome Engineer Membership Card! So long as the card is valid, you will have unlimited access to any gnome engineer trainer anywhere in the world.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3640,0,0,'If you''ve signed the document and are ready to hand it to me, then that is that.$B$BThe secrets I will share with you are of such a magnitude that the signing of the Pledge of Secrecy is absolutely critical. I signed one, as did my brother and sister gnome engineers. You will be joining quite the auspicious fold, Engineer $N!',12340),
	 (3639,1,1,'Once I receive your crafted engineering items for my review, I will hand you a genuine Goblin Engineer Membership Card! So long as the card is valid, you will have unlimited access to any goblin engineer trainer anywhere in the world.',12340),
	 (3638,0,0,'If you''ve signed the document and are ready to hand it to me, then that is that. You''ve been told that this is a one way trip. If you''re ready, then hop on board!',12340),
	 (3636,1,0,'Amnennar must be eradicated. Go, swiftly.',12340),
	 (3637,3,0,'Hello there! If you''ve come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance. Otherwise, what can I do for you today?',12340),
	 (3635,3,0,'Hello there! If you''ve come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance. Otherwise, what can I do for you today?',12340),
	 (3634,6,0,'Yes, yes, what needs of yours might I address today? Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.',12340),
	 (3633,1,0,'I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?',12340),
	 (3631,1,0,'',12340),
	 (3632,6,0,'Yes, yes, what needs of yours might I address today? Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3630,6,0,'Yes, yes, what needs of yours might I address today? Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.',12340),
	 (3629,1,0,'I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?',12340),
	 (3628,0,0,'There is nothing left to fear.',12340),
	 (3626,1,0,'',12340),
	 (3627,0,0,'The three shall form the one, the one shall light the way.',12340),
	 (3625,1,0,'To interrupt the forging process could result in an imperfect weapon. Be patient, $n.',12340),
	 (3621,6,0,'Loramus, eh? It has been many years since I have heard that name.',12340),
	 (3602,25,25,'Evil does not sleep, fool. You will have time for rest when you are finally dead. Now, bring me those crystals.',12340),
	 (3601,14,0,'Those stinkin'' Blood elves. I tell ya, if I was as strong as you are, I''d go down there and teach them a thing or two myself! But I''ll have to settle with payin'' you to take care of ''em for me.',12340),
	 (3569,1,0,'I''ve come to Undercity because I heard their alchemists have been studying long and hard on how to find a cure for their own illness. It was suggested that perhaps they could help me too.$B$BAlthough this place makes me feel far from welcome, I had no choice--the sickness that found me is tearing me up inside and I needed their help immediately.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3567,1,0,'',12340),
	 (3568,6,0,'You know where this is leading, don''t you, $N? There''s no way she can survive... look at her. The best thing for her now is to aid us in finding a cure for the plague. This water she drank might have a clue that helps us figure out how. She''s going to die anyway--she might as well die doing something noble for our people before she does. Don''t you agree?',12340),
	 (3566,274,274,'I don''t believe you! Show me proof!',12340),
	 (3565,1,0,'Well, what did Xylem have to say? He didn''t do anything to you, did he? Cast a spell on you? Con you into doing work for him?',12340),
	 (3564,1,0,'Have you met with Andron yet? He rarely leaves Undercity, so I don''t think it''d be too hard to find him.',12340),
	 (3563,1,0,'Have you spoken to Jes''rimon yet?$B$BHe''s a boar among trolls, but his information is usually accurate and his jobs well paying.$B$BIf you can stand his attitude then you stand to make some good coin from his business endeavors.',12340),
	 (3562,1,0,'Well, what did Magatha say? The old crone... I bet she was less than polite.',12340),
	 (3561,1,0,'What can help you with, $N?',12340),
	 (3542,1,0,'Well... ... isn''t this a surprise? An adventurererere... !$b$bWhat c''n I do for you... ?',12340),
	 (3541,1,0,'Yes, what you be needin'', mon? I got many tings to be takin'' care of today, and you not be on me agenda as one of them. Pester me, and I make sure that changes.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3528,6,6,'Have you defeated the avatar of Hakkar, $N? Has his essence yet empowered the egg I gave you?',12340),
	 (3527,6,6,'Do you have the tablets of the Prophecy of Mosh''aru, $N?$b$bWhen I gain the tablets, I will study them, and learn how to contain the essence of Hakkar!',12340),
	 (3525,1,0,'',12340),
	 (3526,1,0,'I can smell fresh recruits much like I can an excellent blasting powder - from a mile away. Have you come seeking to learn about the mastery of the explosion?',12340),
	 (3524,1,0,'It is only recently that these creatures started landing on the coast of Darkshore in such alarming numbers. I can''t help but think that this is an ill omen of some sort. Recovering a sample of that creature''s bones to the south would help us in Darnassus assess this situation!',12340),
	 (3521,0,2,'Please, collect the ingredients, $N. Iverron needs our help.',12340),
	 (3522,0,0,'Oh... $N, I''m so glad you have returned.',12340),
	 (3523,1,0,'I''m not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.$B$BIf you''re willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I''m... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.',12340),
	 (3520,0,0,'Have you collected the essence of the screecher spirits, $N?',12340),
	 (3518,1,0,'Yes, $N. What can I do for you? I have many matters I must attend to, so please, be quick.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3511,6,6,'You return! Astounding, $R. Did you discover the true name?',12340),
	 (3512,1,0,'',12340),
	 (3513,0,0,'Whaddya got?',12340),
	 (3514,1,5,'We cannot allow the Alliance on our land, $N. Make this known.',12340),
	 (3517,1,0,'The tablets I''m having you gather should bring in a pretty copper or two to the right parties. I''ll tell you who we need to deliver them to after you''ve found them. But I''m no fool... you''ll get your share after I have proof that they''ve been delivered.$b$bSo get to it--we don''t have all day. I might have to find someone else to help me.',12340),
	 (3510,1,0,'<Lord Arkkoroc bends down to inspect you.>$b$bWhere are they?',12340),
	 (3509,1,0,'',12340),
	 (3508,1,0,'',12340),
	 (3507,1,0,'I remember you, $C. I asked you to go to Azshara to destroy that wench that betrayed me! That seems like many moons ago. Don''t tell me that Ag''tor and the others are dead also!',12340),
	 (3506,1,0,'How goes your slaughter of the blood elf traitors, $N? Have you made any progress?$b$bI hope you are the one strong enough to bring that dog to her knees! She deserves nothing but a painful death for all that she has done!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3505,1,0,'The title of the book is emblazoned on the black leather cover in gold leaf--Kaldorei Tome of Summoning. As you open the pages you can see that the book is very old but in superb condition.$b$bYou assume the text is of some ancient language... perhaps Kaldorei?$b$bYour instincts tell you that you should return here once you''ve finished doling out retribution on the blood elves for their betrayal.',12340),
	 (3503,1,0,'',12340),
	 (3504,1,0,'Ah, Belgrom wizened up and finally sent someone not in his ranks to aid us, did he?$b$bThis camp used to be a dozen warriors strong, $N, but now they''re all dead. That mage, Rimtori, has slain them all. She played Belgrom like a lute... seduced him even. It''s none of my business, but between you and I, she is quite the temptress. That''s probably why I''m still out here helping Belgrom--I probably would have done the same thing.',12340),
	 (3502,1,0,'Well? Draenethyst? Remember?$B$B<Kum''isha clenches his fist and knocks on your head.>$B$BIs anybody home?',12340),
	 (3501,1,0,'Have you had any luck in your exploration?',12340),
	 (3481,1,0,'',12340),
	 (3482,1,0,'',12340),
	 (3483,1,0,NULL,12340),
	 (3462,1,0,'',12340),
	 (3463,1,0,'Are you lost, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3461,6,0,'You''re back! Excellent. Do you have my drawing kit also?',12340),
	 (3453,1,0,'Do not interrupt the channeling process.',12340),
	 (3454,1,0,'',12340),
	 (3452,0,0,'Without a suitable source of arcane energy, the torch of retribution cannot be completed.',12340),
	 (3451,1,0,'',12340),
	 (3450,1,0,'',12340),
	 (3449,4,4,'Well, well, well, glad to see you made it out here, $N. Did you get the rubbings for Tymor?$B$BAs dangerous as this place is, there hasn''t been too much action along the coast. That might be on account of the naga swimming underwater, but that''s not my problem... I patrol the skies.',12340),
	 (3448,1,0,'',12340),
	 (3447,1,0,'',12340),
	 (3446,1,0,'Upon examining the statue, you notice a depression in its side, just the size of the token that Marvon gave you...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3445,1,0,'',12340),
	 (3443,0,0,'Eight, $N. I need eight!	',12340),
	 (3444,0,0,'Ratchet is not far from here, $N. The journey shouldn''t take long.',12340),
	 (3442,0,6,'Have you collected the materials?',12340),
	 (3441,1,0,'Allow me to finish mo... $r.',12340),
	 (3421,1,0,'',12340),
	 (3402,1,0,'',12340),
	 (3385,0,6,'The Trade Master still lives?',12340),
	 (3382,1,0,'Have you met with Andron yet? He rarely leaves Undercity, so I don''t think it''d be too hard to find him.',12340),
	 (3381,1,0,'I remain here at my master''s bidding. I''ve been given leave to ask any price I wish for transportation up to his tower. For now, I ask for only the two feathers from each traveler so I can continue to make my signature arrows.$b$bIf you''re not careful, I''ll up the price. How does half a dozen gold sound?$b$bYeah, I thought as much. Just mind yourself and I''ll keep the price where it is.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3380,1,0,'',12340),
	 (3379,1,6,'What information do you have?',12340),
	 (3377,1,0,'Allow me to finish my story.',12340),
	 (3378,0,0,'What brings you to the Temple of the Moon, $N?',12340),
	 (3376,1,1,'Sharptusk will trouble us no more once you have brought me proof of his death.  It is his head that I seek, $N.$B$BWe tauren live for the hunt, and there is no greater hunt than against one that is cunning enough to perhaps hunt us back.  If you are successful in this task, young one, you will start to learn what I mean.',12340),
	 (3375,1,1,'To make another phial I need a mana potion, a piece of coal, and some sweet nectar.$B$BThat, and a whole lotta patience apparently.',12340),
	 (3374,6,6,'Here we are $N, at yet another crossroads. The time has come to make another choice. What choice do you make, mortal?',12340),
	 (3373,0,0,'As you near the essence font that Eranikus told you of, his voice once again touches your mind.$B$B"Yes mortal, this essence font will redeem what untainted element of my psyche remains imbued in this gem.  Place the gem inside the font, and let the magic of the Green Dragonflight cleanse the corruption and taint from my being.  Only then will I find true release, and only then will the Dragonflight be able to reassert their stewardship over the Atal''ai."',12340),
	 (3372,1,0,'The altar is empty.',12340),
	 (3371,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3370,6,0,'May I help you with something?',12340),
	 (3369,6,0,'May I help you with something?',12340),
	 (3368,0,18,'<Thorius sobs.>',12340),
	 (3367,1,0,'I''m not going to make it...',12340),
	 (3366,1,0,NULL,12340),
	 (3365,1,7,'I trust the scalding mornbrew got to Durnan on time! Did you remember to bring me back my mug?',12340),
	 (3364,6,4,'Aye, I''m Durnan Furcutter. You have something for me?',12340),
	 (3363,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (3361,0,0,'Oh goodness $N, this town is not well suited for the likes of me. There are as many nasty creatures here as there were in Gnomeregan before the accident!$b$bDo you have my belongings? If you don''t, then who knows what the trolls have done with them now...',12340),
	 (3362,1,0,'I''d like to take a closer look at that cactus in the valley... So leave some of it in one piece, will ya?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3341,1,0,'This matter is of utmost importance, $N. We must stop any attempt by the Scourge to bolster their ranks.',12340),
	 (3182,3,0,'Why hello there young $g man : lady;. Would you like a tour of the museum?',12340),
	 (3201,274,0,'I don''t believe it.',12340),
	 (3221,1,0,'',12340),
	 (3261,1,0,'',12340),
	 (3281,6,6,'Do you have the silver?',12340),
	 (3301,0,0,'I can smell the dust of the Barrens on you, $C. You have traveled far.',12340),
	 (3321,1,0,'Today we finalize our celebration of your commitment to the Order.',12340),
	 (3129,1,0,'',12340),
	 (3130,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3141,1,0,'Do not interrupt me, $r.',12340),
	 (3161,0,0,'Are you having any trouble?$B$BYou can find Gahz''ridian just about anywhere in Tanaris, $N, so keep looking!',12340),
	 (3181,274,0,'No, I will not open the gate.',12340),
	 (3126,6,6,'Were you able to capture the wandering forest walkers?',12340),
	 (3127,6,6,'Were you able to capture the mountain giants?',12340),
	 (3128,0,0,'Were you able to collect the materials I need?',12340),
	 (3125,6,6,'Were you able to capture the muisek of the faerie dragons?',12340),
	 (3124,6,6,'Were you able to capture the hippogryphs?',12340),
	 (3123,0,0,'Were you able to capture the wildkin?$b$bIf you succeed, we will be ready to shrink and capture the muisek of creatures of Feralas.',12340),
	 (3121,0,0,'Yes?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3122,0,0,'Have you spoken to Xerash?',12340),
	 (3120,2,0,'Ah, young $C. I see you''re eager to continue your studies. Good.$b$bI wonder, have you spent much time in the Emerald Dream already? Perhaps you''re not prepared for that yet... In time, I''m sure.$b$bBut until then, we should discuss other matters.',12340),
	 (3119,2,0,'It pleases me to see you''ve arrived so quickly, $N. Welcome.$b$bAs you''ve probably heard, all of Teldrassil is stirring with the comings and goings of travelers. Even members of the Alliance have even been allowed access onto Teldrassil''s boughs in order to meet with other Kaldorei who prepare for the adventures ahead.',12340),
	 (3118,2,1,'Hello, $n. I''m glad you found me. I was thinking that perhaps you got lost on the way here.$B$BNothing really new has happened in Shadowglen since I sent you my sigil, but I''ll leave all the information gathering to you. Speak to the rest of the people around Aldrassil if you''d like.',0),
	 (3117,2,0,'You''ve arrived, and none too soon, $N. Welcome to Shadowglen.$B$BI trust my sigil found you in good spirits and health?$B$BAs I said previously, I am here to train you as a $C; to tame beasts to aid you in battle; to use a bow with unerring accuracy; to respect the lands which we call home and also the lands beyond.',12340),
	 (3116,2,0,'You made it. I''m so glad.$b$bMuch has happened over the last few years, $N: the creation of Teldrassil, the corruption of many of the forest creatures here and abroad, discovery of lands we thought lost to us like Feralas... so much, in so little time. But those are just some of the reasons we are here, the most important being to protect our kind from further evil.',12340),
	 (3115,1,0,'Wonderful! You got my memorandum obviously.$b$bIgnore the fools around you, $N. The Holy Light?! The sword and shield?! These aren''t paths for ones as open minded as us. Look at what "normal" magic did to our home. Coupled with those damned tinkerers, our race almost became extinct. And now we have to rely on the dwarves-- they''d rather spend time allying with humans than help us rebuild our own home. We''re like second-class citizens. Have you seen the way they look at us?',12340),
	 (3114,11,0,'Yeah, what''s that, $R? Speak up, if you don''t mind. I don''t hear so good after a few ales.',12340),
	 (3113,1,0,'Glad to see you got my note and came over. Sorry about pretendin'' it was a memorandum from your higher-ups... no offense intended. I just knew the two of us, along with others of our kind, gotta stick together.$B$BNot many think it''s the best thing in the world to have your kind and my kind holed up in the same city, but I think we can work things out just fine. What do you think?',12340),
	 (3112,2,0,'Ah, well, another memorandum from a $R on a mission... isn''t this quaint.$B$BNo, no, I ain''t teasin'' ya, little one. Gotta respect your tenacity, that much is fer sure. I''d be just as peeved if Ironforge was taken by Dark Iron dwarves, so don''t be thinkin'' I don''t feel for your plight...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3110,6,0,'Ach! Ya made it, $N! Wonderful!$B$BI was gonna say, I was about to lose faith that ye''d arrive at all... get it, lose faith? It''s a joke, lass... aww, nevermind. Ya didn''t come here for me bad jokes anyway.',12340),
	 (3109,2,0,'You made it! Great!$B$BWe''ve got an influx of activity lately, so I''m glad to count another of the Ironforge clan among our numbers. Too many of us are lookin'' to the arcane, and divine for my own tastes. Nothin'' against them and their beliefs, but there''s nothing like a cold blade in your hand and a shadow to keep you from the light, know what I mean?',12340),
	 (3108,4,0,'Ya made it! Good to hear! Betcha didn''t have to track me to find the place either. Haha!$B$BOur profession is pretty steeped in tradition, $N. Learning the ways of the land. Learning to track a bear through the mountains. Even just surviving on wits alone takes a great deal of courage and cunning. Think you''re capable?',12340),
	 (3107,1,0,'So, you''ve made it! And not a second too soon. There''s much to be done in Coldridge Valley and beyond. I''m gonna need your help as much as you''re gonna need mine!$B$BYou''re a Knight of the Silver Hand now, be ready to play the part.',12340),
	 (3106,6,0,'Blast it''s cold today, aint it? It''s like the snow never goes away, $N.$b$bYou''ve probably noticed already, but there are gnomes now living in our city. That''s because they went and got themselves blown out of their own home. Don''t go spreadin'' this ''round, but I can hardly blame them--I think I woulda resorted to explosives too if Ironforge were infested with Dark Irons or the like.',12340),
	 (3105,1,0,'Ah, so you''ve arrived, and not a moment too soon, $N. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes.',12340),
	 (3104,6,0,'Hello, $N. I am Khelden. Is there something I can do for you?',12340),
	 (3103,2,0,'Ah, at last you''ve come. I knew you would find your way to me. The Holy Light shines upon you, and the path you''ve chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can.',12340),
	 (3102,2,0,'You made it here in one piece, and it doesn''t look like too many people saw you. Good enough for me. I don''t like to have much attention drawn to me back here... nice and quiet. I''m sure you can understand.$b$bHave any trouble yet? I''m glad to hear not. That''ll change soon enough.',12340),
	 (3101,4,0,'Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3100,2,0,'Ah, you got my letter, $N... good.$B$BThere''s been an influx of warriors in Elwynn recently - which is good for Stormwind, but bad for the kobolds and Defias in the area.',12340),
	 (3099,2,0,'I bid you welcome, $gbrother:sister;. I knew you would come. It was only a matter of time.$b$bWhat I said interested you, didn''t it? I hit a chord... something inside you knew what I claimed was truth. Good.$b$bKnow this though: I am no traitor to Sylvanas. If anything, she would appreciate my claims considering it was her own beliefs that has put the Forsaken in the position it is now.',12340),
	 (3098,1,0,'I knew you would come to me, $N. Not because you do not have the will to follow your own path, but because we are kindred spirits. We both have felt pain. We have both suffered. And now we want the power to take back what we know is ours: this land, our lives, our destinies. But there is much for you to learn still.',12340),
	 (3097,1,0,'Ah, so between fire, plague, rioting, and much worse, one more of the "faithful" comes to my door. Well, let me bid you welcome, $C. And allow me a moment to explain a thing or two before you decide it''s time for you to seek whatever drives you forward: the Holy Light no longer concerns you, the spirits of your forefathers are fairy tales, and creatures from the Nether don''t want you.$b$bDo you understand me so far?',12340),
	 (3096,1,0,'So you''ve made it? Good, we''ll have need of more rogues as time goes on. The Shadowstalkers will probably wind up finding you when they think the time''s right, so don''t go and slip up or do anything you might regret. They need talented agents... not pickpockets and fools.',12340),
	 (3095,1,0,'Ah, so you''ve arrived. Good. I overheard that a few others were able to escape "death" and were heading into town. Perhaps that resilence will pay off in the future also.$B$BYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.',12340),
	 (3094,2,2,'You have arrived. This is good. Our ancestors'' spirits have become restless throughout Mulgore and beyond, but I cannot tell why. It will forever be your duty to learn to listen to nature''s spirits, and act as their avatar. Be mindful of that.',12340),
	 (3093,2,2,'As quickly as water falls from the sky, here you are before me. I am pleased by your haste. It means you realize both the importance of our meeting and you being here. I am no leader, but I do understand the elements, and I can speak to the spirits of our people. I will teach you to do the same.',12340),
	 (3092,2,2,'Welcome to Camp Narache, $n. I hear good things about you. Your bloodline is strong, and many of the elders consider you skilled already. But that we will test.$b$bThe plains of Mulgore will be your home for sometime--you should do your best to learn it very well. One day you will travel to unfamilar lands to master greater skills. You must be ready.',12340),
	 (3091,2,2,'Ah, at last, you''ve arrived, $C. I did not lie in my note, $N. We are a special breed also, not unlike the druids or shamans of our tribe. You are just as important. We are the ones called upon to defend our borders, to hunt the centaur, and to go to war.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3090,1,0,'Finally, you''ve arrived... and discretely also. Good.$b$bOur world is full of fools, $N. Even the mighty Thrall has greater flaws than most can see. He turns his back on the power needed to make this land ours completely! We''re not the same people who were manipulated and used by creatures from the Nether. We are our own people. We are proud... and we are strong.',12340),
	 (3089,2,0,'So, you''ve arrived. I was beginning to wonder when you would show yourself. I sent the parchment some time ago--I wasn''t sure if it had arrived.$B$BBut enough chatter... you''re here because you have been chosen, chosen to lead the spiritual lives of our people.',12340),
	 (3088,2,5,'Shhh, not so loud. I don''t trust Nartok over there. Anyone that has to hide deeper in a cave than I do shouldn''t be trifled with.$b$bI trust you had no problem finding your way around?',12340),
	 (3087,2,0,'Ah, so you come at last. Good. Jen''shan be waitin'' for you.$B$BMany tink it be an easy path, but Jen''shan tell you dat not true. Mastering da beasts of Durotar and beyond take as much skill as masterin'' the arcane arts or speakin'' to our ancestors.$B$BFirin'' a bow or rifle may not be as dangerous to you as castin'' a spell, but it sure be as dangerous to your enemy.',12340),
	 (3086,2,0,'Ya look to please Mai''ah already, $N. Dat be good. You give Mai''ah respect, and Mai''ah maybe give you respect back. But enough o'' dat, you be here to learn ''bout magic, not hear Mai''ah talk.$B$BThere be only one ting Mai''ah can no teach you ''bout magic, $N, and dat''s how to stop da corruptin''.',12340),
	 (3085,2,0,'So ya made it... good good! Da spirits tol'' me you be comin'' to see Ken''jai soon enough. Let me be one o'' da first to welcome ya to da Valley of Trials. Dis place not be your home fer long, but while it is, why dontcha make da best o'' it.',12340),
	 (3084,2,0,'Ah, welcome, $N. I''m pleased you have arrived. My days have become long and even busy what with so many students to teach, but the coming of one of your ilk brings me a great sense of accomplishment--I remember the days when I was taught by one of your shamans.',12340),
	 (3083,2,5,'Welcome to the Valley of Trials, $n. You wouldn''t be here if you hadn''t gotten my tablet, so I will get to the point.$B$BI am Rwag and I am responsible for training the rogues, thieves, and cutpurses here in the Valley. I''m the one the Hand will turn to if you''re not ready for what''s to come. But don''t worry, the Hand won''t be controlling everything you do, but it would be wise to work with them if they have need of your talents.',0),
	 (3082,2,0,'Jen''shan see a mighty $C before her and da spirits approve.$b$bDa path of da $C is one of our oldest walks of life. Da Horde turned to us when they be just strugglin'' to survive on Azeroth, and they ask us to teach them, to show them the secrets of many tings. They were strong already: strong in shaman ways; strong in warrior ways. But the $C path not be their path... then.',12340),
	 (3065,2,0,'Another $R to bolster the ranks. Good enough for me.$b$bYou''ll probably have a hard time hefting a good weapon like an axe, but a spear''s just as good as anything else.$b$bWelcome to the Valley of Trials.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (3063,1,0,'The wings of the Northspring harpies are black as the night; do not take your eyes off of them, lest they disappear into darkness.',12340),
	 (3062,0,0,'The hate that Edana spreads across the land must be stopped.',12340),
	 (3042,0,0,'Did you bring me the temper, $N?',12340),
	 (3022,0,0,'Another shipment from Curgle, I assume?',12340),
	 (2999,1,0,'',12340),
	 (3000,1,0,'',12340),
	 (3001,1,0,'',12340),
	 (3002,6,0,'What have you brought me, $R?',12340),
	 (2998,1,0,'',12340),
	 (2997,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2996,1,0,'',12340),
	 (2992,1,0,'',12340),
	 (2993,1,0,'',12340),
	 (2994,1,0,'Save Sharpbeak!',12340),
	 (2995,1,6,'Keeping the Highvale elves isolated is the key. Have you found the lodge?',12340),
	 (2990,0,0,'$N, you come bearing a gift?',12340),
	 (2991,6,6,'Do you have Nekrum''s Medallion, $N?  There are powers hidden within it that I am eager to discover.',12340),
	 (2985,1,0,'',12340),
	 (2987,5,5,'Get on up there and start digging!$b$bI''ve got places to go and people to see -- time is money!',12340),
	 (2988,1,0,'Have you searched the cages, $N? We must find Sharpbeak!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2989,1,0,'Hurry, $N!  If the Vilebranch trolls have Sharpbeak, then who knows what they might be doing with him!',12340),
	 (2984,1,0,'',12340),
	 (2983,1,0,'',12340),
	 (2981,1,0,'',12340),
	 (2982,1,1,'Be watchful around the Gordunni, $N. Their magic seems to wreak havoc on the very land they stand on.',12340),
	 (2980,1,0,'Have you found the ruins, $N?',12340),
	 (2979,0,0,'We must discover more about why the Gordunni are here, $N.',12340),
	 (2978,0,0,'What is this?',12340),
	 (2976,1,0,'Be quick, $C, I have much to complete today.',12340),
	 (2977,6,0,'Welcome back $N.  Were you able to use the discs to your advantage, or did it end up being a wild goose chase?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2975,1,0,'Move swiftly, $N. Or is the task I requested too difficult?',12340),
	 (2974,1,1,'Take my words seriously, $C, the Grimtotem clan is evil. If you''ve found their whereabouts, then it''s up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.',12340),
	 (2973,1,1,'The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, $C. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.$b$bWhen you''ve gotten enough of the wings, let me know, I''ll be sure to reward you well!',12340),
	 (2972,1,0,'Hello, child. It pleases us to have more powerful adventurers here in the temple. If you have the time, will you share a tale or two with the younger adventurers? I know many of them would benefit from your wisdom.$B$BI''m sorry, look how rude of me. You''ve come to the Temple seeking our aid, and I impose on you. Please, forgive me. Tell me what the servants of the Light can do for you.',12340),
	 (2968,1,0,'',12340),
	 (2969,1,0,'',12340),
	 (2970,1,1,'Kindal needs time to prepare, but our kills already number in the dozens. The Grimtotem clan is more than aware of our presence in the area, and they seek us out like vipers.$B$BThey''ll do everything in their power to take our heads from our bodies. You should be alert... they''ll be coming for you too now that you''ve interfered.',12340),
	 (2967,6,6,'Welcome back $N.  Were you able to use the discs to your advantage, or was it for naught?',12340),
	 (2966,1,0,'This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...',12340),
	 (2965,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2963,1,0,'',12340),
	 (2964,1,0,'',12340),
	 (2962,1,1,'Hrm, you''re not glowing. That''s a good sign.',12340),
	 (2954,1,0,'The purpose of the stone watcher must be learned before continuing on...',12340),
	 (2952,1,0,'',12340),
	 (2953,1,0,'The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!',12340),
	 (2951,1,0,'It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working. So long as both are present, the Sparklematic 5200 should work...',12340),
	 (2950,1,0,'Do you have the materials I need?  I can''t improve on this design without everything I asked for.',12340),
	 (2949,1,0,'You''d think that we would find a way on our own to outdo those filthy little gnomes.  I would even wager that they stole that rig from us to begin with!  Bah, those greasy, grimy... erm, yes?  You need something?',12340),
	 (2948,1,0,'Do you have the materials I need?  I wouldn''t ask you for them if I wasn''t down on my luck...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2946,1,0,'This familiar looking pedestal sticks out of the hot sand. Perhaps there is something to its presence here...',12340),
	 (2947,1,0,'Hey, easy there partner - I''m a very important businessman!  I am sure that the courier is just simply late with the delivery of the rent... wait... you''re not my landlord.$B$BWell, of course you aren''t - silly me!  You''ve come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items!  Yes!$B$BUm... what do you need?',12340),
	 (2945,1,0,'The gnomish contraption before you bears a plaque calling it "The Sparklematic 5200".  The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have.  The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it.$B$BIt would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!',12340),
	 (2944,1,1,'So, you have finally returned, $N. And you''ve brought the contraption that Curgle built for me -- perfect.',12340),
	 (2943,6,0,'Hello, $N. Have you been to Darnassus?',12340),
	 (2941,6,0,'A letter -- for me?',12340),
	 (2942,1,1,'I am glad you have returned, $N. I am eager to hear of your findings.',12340),
	 (2940,1,0,'',12340),
	 (2939,1,0,'',12340),
	 (2938,0,0,'Word was sent of your coming, $N. You have a parcel for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2937,6,6,'Did you get the venom?',12340),
	 (2935,1,0,'',12340),
	 (2936,1,0,'Do you know the spider god''s name?',12340),
	 (2934,0,0,'Do you have the undamaged venom sac, $N?  I yearn to run experiments with its fresh venom, and have ordered a collection of small, terribly cute animals on which to test it!',12340),
	 (2930,6,6,'Do you have the prismatic punch card??',12340),
	 (2931,1,0,'',12340),
	 (2932,1,0,'You have not completed my task, $N.',12340),
	 (2933,0,0,'Hello, gentle $C. The day has been long and not a single experiment successful...I hope you bring good news to me.',12340),
	 (2927,1,0,'',12340),
	 (2928,0,0,'If this were a race, you would have lost by now.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2929,1,0,'Is the task complete? Did he beg for lenience? For mercy??',12340),
	 (2926,5,5,'Can''t you see we''re trying to cure an entire species of gnomes here??! We need more of the green glow!',12340),
	 (2925,1,0,'',12340),
	 (2923,1,0,'',12340),
	 (2924,6,6,'Do you have the essential artificials?',12340),
	 (2904,1,0,'Eh? Kernobee is alive??',12340),
	 (2922,6,6,'Did you find Techbot?  Did you retrieve its memory core??',12340),
	 (2903,6,0,'Welcome back $N - were you able to find some tangible evidence as to the plans of the gnolls?',12340),
	 (2902,1,0,'',12340),
	 (2882,1,0,'This chest is locked!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2881,1,0,'I want five of those tribal necklaces the trolls carry on them. If you need it spelled out further, then killing one of them stands you a good chance of getting one!$B$BProve your worth to the Wildhammers!',12340),
	 (2879,1,0,'The Equinex Monolith stands silently among the ruins. What could it be holding?',12340),
	 (2880,5,5,'I want five of those tribal necklaces the trolls carry on them.  If you need it spelled out further, then killing one of them stands you a good chance of getting one!$B$BProve your worth to the Wildhammers!',12340),
	 (2878,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (2877,1,5,'Make no effort to negotiate the mission at hand, $r!  If the gods had wanted those oozes killed, they would have miracled it done by now, wouldn''t they?!',12340),
	 (2876,0,0,'You look out of breath.  You have something to tell me?',12340),
	 (2875,0,0,'You look a little dazed.  Have you been reading our legal documents?',12340),
	 (2874,6,0,'Did Stoley cough up my booze?',12340),
	 (2873,6,6,'Did you find my shipment of rum, $N?',12340),
	 (2872,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2871,2,0,'Yes, may I assist you?$B$BHold on, you''re the $C that has been helping General Feathermoon and Latro out with the naga threat, yes?  I''m Vestia, Latro''s - erm, rather, Latronicus'' wife.  It is a pleasure to meet you!$B$BI''m sorry, you''re here on business, of course.  Do you have something for me - from him, perchance?',12340),
	 (2870,6,6,'Bringing down Lord Shalzaru would certainly set their plans back weeks, if not months.  On top of that, the relic he uncovered is of definite interest to us.$B$BHave you performed the mission given to you, $N?',12340),
	 (2869,1,1,'$N, if you''re here to verify the task given to you, then excellent - it is ten Hatecrest scales I seek.  If you are here for chit-chat, then I am currently unavailable for such trivialities.$B$BKnow this - we night elves are not warmongers.  Our race is dedicated to the preservation of peace and harmony.  This does not mean, however, that we will not proactively protect our own interests.  This is my duty to General Feathermoon, and to the stronghold.',12340),
	 (2867,1,0,'',12340),
	 (2866,1,0,'',12340),
	 (2865,0,0,'Do you have the shells?  My cousin in Booty Bay is waiting for a load of them, and he''s getting impatient!',12340),
	 (2864,1,0,'',12340),
	 (2863,1,0,'Time is running out, $N! If you''re not here to report that you''ve taken out the Alphas, then you''re wasting time!',12340),
	 (2862,5,5,'We drive them back, and yet they still attack! Someone or something must be driving them into a frenzy... oh, you have returned, eh $N? Do you have the manes I require for the bounty to be met?',12340),
	 (2861,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2860,1,0,'Greetings, $r... from your countenance I can tell you are a leatherworker as am I. Have you come to draw from my skills, or perhaps you have other business with me?',12340),
	 (2859,1,0,'Do you have the Turtle Scale bracers and helms ready? Don''t forget the two wildvines I require.$b$bBy now, you''re starting to realize the potential power that lies in Wild Leather armor. An armor that has no boundaries in application is nearly invaluable to a leatherworker. The limits are only in the quantities of resources to make the items - not the quality of the finished products!',12340),
	 (2858,1,0,'The pants, boots, and wildvines need to be delivered to me before you learn the pattern, $N. Have you done as I asked?$b$bFrom the earliest pair of boots we learn how to make, we start to understand that a quality boot needs to ride a razor''s edge between comfort and function. With both, we are able to create items that allow the wearer to ignore fatigue that would cripple those wearing lower quality goods.',12340),
	 (2857,1,0,'I need those tunics and headbands made, and I also need that piece of wildvine before I will share with you the knowledge of Wild Leather helmets.$b$bHead gear is highly coveted amongst adventurers, whether it be a disarmingly simple headband or a full-covering helmet. The fundamentals of creating valued head gear remain constant, no matter what the cosmetic appearance of the gear is.',12340),
	 (2856,1,0,'Do you have the two Turtle Scale breastplates and gloves? Also, don''t forget the wildvine!$b$bEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments. Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.$b$bAs you progress through your lessons, the skills I teach will become as art.',12340),
	 (2855,1,0,'Do you have the six thick armor kits and the wildvine I require?$b$bThink of making armor kits as a lesson in steady and reliable crafting; the consistent fashioning method you develop as you ply your trade on these kits helps develop your skills for the intricate work needed to make Wild Leather armors.$b$bEvery lesson has a purpose, $N. It is important to embrace each one accordingly.',12340),
	 (2854,1,0,'We must be clear; you shall be apprenticed to me while you learn the art of Wild Leather armor. Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making. This knowledge, however, was not easy for me to acquire.$b$bThe initial cost to begin this process is ten pieces of thick leather.$b$bOnce that is done, we''ll get to the work you need to do in order to obtain the patterns.',12340),
	 (2853,2,2,'Greetings, $R... from your countenance I can tell you are a leatherworker as am I. Have you come to draw from my skills, or perhaps you have other business with me?',12340),
	 (2852,6,6,'Do you have the Turtle Scale bracers and helms ready? Don''t forget the two wildvines I need!$B$BBy now, you''re starting to realize the potential power that lies in Wild Leather armor. An armor that has no boundaries in application is nearly invaluable to a leatherworker. The limits are only in the quantities of resources to make the items - not the quality of the finished products!',12340),
	 (2851,6,6,'The order on the pants, boots, and wildvines needs to be filled before you get the pattern, $N. Are you finished?$B$BFrom the earliest pair of boots we learn how to make, we start to understand that a quality boot needs to ride a razor''s edge between comfort and function. With both, we are able to create items that allow the wearer to ignore fatigue that would cripple those wearing lower quality goods.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2850,1,1,'I need those tunics and headbands made, and I also need that piece of wildvine before I will share with you the knowledge of Wild Leather helmets.$B$BHead gear is highly coveted amongst adventurers, whether it be a disarmingly simple headband or a full-covering helmet. The fundamentals of creating valued head gear remain constant, no matter what the cosmetic appearance of the gear is.',12340),
	 (2849,6,6,'Do you have the two Turtle Scale breastplates and gloves I ordered? Also, don''t forget the wildvine!$B$BEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments. Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.$B$BAnd the gloves... well, they''re just for my own benefit. Remember, you''re working for me!',12340),
	 (2848,6,6,'Do you have the six thick armor kits and the wildvine I require?$B$BDon''t think of making armor kits as monotonous work; the steady fashioning method you develop as you ply your trade on these kits helps develop your skills for the intricate work needed to make Wild Leather armor.$B$BSee - there''s a real reason behind what you''re making for me...',12340),
	 (2847,1,1,'Like I said, you''ll be working for me while you learn about Wild Leather armor. Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making. This knowledge, however, was not easy for me to come by.$B$BThe initial cost to begin this process is ten pieces of thick leather.$B$BOnce that is done, we''ll get to the work you need to do in order to obtain the patterns.',12340),
	 (2846,6,6,'Do you have the tiara, $N?  Has Velratha learned the price of crossing me?',12340),
	 (2845,1,0,'I was gettin'' worried ''bout ya! Thank you so much for bringin'' Shay home, $N.',12340),
	 (2844,1,0,'',12340),
	 (2842,1,0,'',12340),
	 (2843,1,0,'It''s ready!',12340),
	 (2841,1,0,'I don''t see any blueprints. Did you hide them somewhere on your body or are you just standing around here to irritate me?$b$b',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2822,6,6,'Were you able to get a stack of ten thick yeti hides? My leather goods are second to none, and I''ll share a sampling with you should you have the hides.$b$bIf you can''t seem to find yetis, I know where some might be. Try looking west of here, just inland of the Forgotten Coast around the Feral Scar Vale.',12340),
	 (2801,1,0,'Listen to what I have to say, $N.',12340),
	 (2821,1,1,'A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you''ll get a good item!$B$BIf you can''t seem to find yetis, I know where some might be.  Try looking just inland of the Forgotten Coast, around Feral Scar Vale.',12340),
	 (2784,1,0,'Listen to what I have to say.',12340),
	 (2783,1,0,'',12340),
	 (2782,6,0,'Well, now, what is this?',12340),
	 (2781,6,6,'Yes $c, I am an official of the Gadgetzan Water Company.  What can I assist you with?',12340),
	 (2773,1,0,'Have you completed the crafting of the items, $N?',12340),
	 (2772,1,0,'Have you completed the crafting of the items, $N?',12340),
	 (2771,1,0,'Have you completed the crafting of the items, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2769,1,0,'',12340),
	 (2770,6,6,'Do you have the scale?  I can''t wait to try different ways to harness its energy!',12340),
	 (2768,6,6,'Did you find Sergeant Bly?  Did you get my divino-matic rod?',12340),
	 (2767,1,0,'Yes, I''m Oglethorpe Obnoticus, master inventor at your service! Now, is there something I could assist you with?',12340),
	 (2764,1,0,'',12340),
	 (2765,1,0,'',12340),
	 (2766,1,0,'You appear to have uncovered the wreckage of... a robotic chicken? The voice from within the egg crackles to life again:$b$b"Yes, excellent work! This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs. Go ahead and place the beacon inside the rover - the beacon will take care of the rest!"',12340),
	 (2763,0,0,'After such mining, your muscles bulge and your body aches!',12340),
	 (2762,0,0,'After such mining, your muscles bulge and your body aches!',12340),
	 (2761,0,0,'After such mining, your muscles bulge and your body aches!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2759,25,0,'A rare breed your kind be, matey. Let me see that insignia.',12340),
	 (2760,2,2,'Hail! Come closer; show Galvan what you have.',12340),
	 (2755,1,0,'',12340),
	 (2756,5,5,'Aturk, like time, waits for no one! Hurry up fool!',12340),
	 (2757,25,0,'A rare breed your kind be, matey. Let me see that insignia.',12340),
	 (2758,6,6,'Could you be the next Galvan protege?',12340),
	 (2754,1,0,'Show the iron who is in charge, $N!',12340),
	 (2753,1,0,'Their skulls will crack under the pressure of your boots!',12340),
	 (2752,1,0,'Show me your dedication, $R.',12340),
	 (2751,1,0,'Bronze, $N! More bronze!!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2750,1,1,'These are the eggs that cannot be saved -- they will never hatch.',12340),
	 (2749,1,1,'Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.',12340),
	 (2748,1,1,'A fine egg is one that will, in ideal conditions, hatch free of the evil effects of the Gordunni ogres'' incantations.',12340),
	 (2747,1,1,'I have seen very few eggs retrieved from Feralas in extraordinary condition. These are eggs of the rarest sort...',12340),
	 (2745,1,0,'',12340),
	 (2746,0,0,'I''ve been watching Lescovar for a couple weeks now. Trias has never trusted him, but we didn''t suspect he was involved in anything to do with the Defias Brotherhood. We were following leads that tied him to the Twilight''s Hammer. Either way, he''s become more dangerous than this city can deal with, and that''s where we come in.$b$bGet me those items and we can put my plan into effect.',12340),
	 (2744,1,0,'What are you doing here?',12340),
	 (2743,1,0,'',12340),
	 (2742,1,0,'Rin''ji is scared!',12340),
	 (2741,1,0,'The Super Egg-O-Matic is the latest of Curgle Cranklehop''s inventions. It is quite an impressive piece of machinery.$B$BThe Super Egg-O-Matic sputters wildly as you approach the control panel.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2721,1,0,'',12340),
	 (2702,1,0,'',12340),
	 (2701,1,0,'',12340),
	 (2662,1,0,'',12340),
	 (2681,1,0,'It is no easy task, $N. Do not give up!',12340),
	 (2661,0,0,'Oh, $N, you''re finally back.  What have you brought?',12340),
	 (2623,0,0,'Awaiting orders.',12340),
	 (2641,0,0,'Under the waters of that lake -- it''s the only place where the Violet Tragan can be found.  Hope you''re good at holding your breath!',12340),
	 (2622,1,0,'',12340),
	 (2621,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2609,1,1,'If you want the ''itis'' cured, you''re going to have to try harder than that, $n. Where are the reagents for the cure?',12340),
	 (2608,1,0,'When you''re ready for the examination, /lay down on the ground and I''ll begin the phlebotomy.',12340),
	 (2607,1,0,'',12340),
	 (2606,0,0,'So old Marin''s up to it again, eh? What''s this concoction made from?',12340),
	 (2605,0,0,'Please, tell me you found the dew collectors?',12340),
	 (2604,5,5,'Do not waste my time, $N. We have nothing to discuss, unless you have recovered the items I have requested.',12340),
	 (2603,5,5,'Do not waste my time, $N. We have nothing to discuss, unless you have recovered the items I have requested.',12340),
	 (2602,6,6,'Have you returned with the requested organs?',12340),
	 (2601,6,6,'Have you returned with the requested organs?',12340),
	 (2586,5,5,'Where are the organs, $N!?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2585,5,5,'Where are the organs, $N!?',12340),
	 (2584,5,5,'Where are the organs, $N!?',12340),
	 (2583,5,5,'Where are the organs, $N!?',12340),
	 (2582,6,6,'Do you have the beast organs?',12340),
	 (2581,6,6,'You smell foul, $N. Have you been traipsing in sulfur fields? And where are my components?!',12340),
	 (2561,1,1,'$N, be wary when approaching my physical form; the enchantment it is under is quite powerful.',12340),
	 (2541,1,1,'If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?',12340),
	 (2523,1,0,'You have found a sickly, corrupted version of what appears to be a songflower plant. A pungent, unhealthy odor emanates from the plant. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (2522,1,0,'Have you found another flawless draenethyst sphere?',12340),
	 (2521,1,0,'I have dedicated my life to the search of flawless draenethyst spheres. A lifetime, $r!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2519,1,0,'',12340),
	 (2520,1,0,'Have you placed the sacrifice at the fountain, $n?',12340),
	 (2518,18,18,'I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope.$B$BIt is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.',12340),
	 (2501,6,6,'Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...',12340),
	 (2500,6,6,'Have you gotten the things I need yet?  You won''t get paid unless you bring me those reagents.',12340),
	 (2499,6,6,'Have you located Oakenscowl yet, $R?',12340),
	 (2480,1,0,'',12340),
	 (2498,1,0,'',12340),
	 (2460,5,5,'Practice!',12340),
	 (2478,1,0,'What have you to report, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2479,1,0,'What''s this???',12340),
	 (2440,3,3,'Greetings, $C! Are you here for alchemy training, or perhaps something else?',12340),
	 (2458,1,0,'',12340),
	 (2459,6,6,'Ferocitas and the Gnarlpine Mystics must return what is mine. Please retrieve the emerald so that I may repair my emerald dreamcatcher.',12340),
	 (2439,6,0,'Welcome to the Vault of Ironforge, $N.  What may I do for you today?',12340),
	 (2438,6,6,'Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg.$b$bHave you recovered it yet, $N?',12340),
	 (2399,1,0,'',12340),
	 (2418,0,0,'Do you have the power stones, $N?  I have a robotic rodent that needs a power supply...',12340),
	 (2398,1,0,'',12340),
	 (2383,6,0,'What''s that you have there? A parchment? You''re not a scholar, I hope...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2382,1,0,'',12340),
	 (2380,1,0,'',12340),
	 (2381,1,0,'Well, at least you still have all of your body parts. Did you find the treasure?$b$b',12340),
	 (2379,1,0,'',12340),
	 (2378,1,0,'',12340),
	 (2361,1,0,'',12340),
	 (2360,1,0,'',12340),
	 (2359,6,6,'Any news from Agent Kearnen?',12340),
	 (2358,6,6,'Do you have the demon prince''s horns?',12340),
	 (2341,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2342,20,0,'The sweeping never ends... these bats are prolific in their mockery of me and my broom.  Please tell me you''ve reclaimed my family''s treasure!  I''ve offered you my silver - is that not enough?!',12340),
	 (2340,1,0,'Well, look who it is! Took your sweet time getting here, I see. Let''s hope this isn''t a waste of my time! You''ll not get paid unless you have everything I asked for. And trust me on this - we''ll be double and triple checking everything!',12340),
	 (2339,0,0,'You''ve got another trip into the depths of Uldaman in store for yourself if you don''t have the gems and a power source capable of channeling magical power back into the necklace.$B$BYou''ll be getting the gems back to deliver to the goons in Orgrimmar; I will be keeping the power source, since it will be the thing that will make the necklace work in the first place...',12340),
	 (2282,6,6,'Did I forget to mention the orcs?$B$BI hear they have been nosing around up by the mill.',12340),
	 (2283,6,6,'Well, do you have the necklace?  You won''t see a copper from us if you don''t have that necklace!',12340),
	 (2284,1,0,'',12340),
	 (2298,1,0,'',12340),
	 (2299,1,0,'',12340),
	 (2300,1,0,'',12340),
	 (2318,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2338,1,0,'You''ve thought about it, yes? You''re a smart $C if you take this deal - you and I will get what we both want, and Droffers and Son Salvage will think they''re getting what they want.',12340),
	 (2281,1,0,'',12340),
	 (2279,6,6,'Yes, may I help you with something?  I assure you I am a very busy right now.  If it is grave importance to the Explorers'' League, however, then I am all ears!',12340),
	 (2280,1,0,'Yes young one, I see you marching into my tent with intensity in your stride... with determination in your purpose. You seek my counsel is some matter of grave importance to the Horde? Perhaps you wish a mystery of the universe revealed to you?',12340),
	 (2278,1,0,'The voice of the stone watcher seems to resonate within your very inner being:$b$b"You must first satisfy the data assimilation prerequisite of Discs of Norgannon; once you fulfill this requirement, you will then be permitted to obtain a portable version of the stored data. Please be sure you have fully explored the information within this repository first."',12340),
	 (2259,1,0,'',12340),
	 (2260,1,0,'',12340),
	 (2258,6,6,'Have you gotten the things I need yet? You won''t get paid unless you bring me those reagents.',12340),
	 (2242,1,0,'Have you anything to report from Sethir the Ancient, $N?',12340),
	 (2241,1,0,'Oh, isn''t this wonderful. You''ve brought flowers for your own funeral.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2240,1,0,'Do you have something to report?',12340),
	 (2239,6,0,'Did ye enjoy the stench of leper gnome? I only ask because ye got a crazy smile on yer face.$B$BWhat news do ye bring from Onin?',12340),
	 (2206,25,25,'Your mortality wanes with every moment you waste loitering in the barracks, $C.',12340),
	 (2218,1,0,'',12340),
	 (2238,1,0,'',12340),
	 (2205,6,6,'Can I help you, $C?',12340),
	 (2204,6,6,'You didn''t even stop to tidy yourself up after leaving Uldaman, did you.  You just came straight here, lingering dungeon odors be damned.  Well, let''s hope this visit is merely an odiferous one, and not a useless one to boot.$B$BDo you have the power source for the necklace?',12340),
	 (2203,6,6,'Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...',12340),
	 (2202,6,6,'Have you obtained the magenta fungus caps I need for my alchemical work? No caps - no reward!',12340),
	 (2200,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2201,0,0,'Talvash''s image comes into focus from the waters of the scrying bowl.$b$b"Wow, you''re still alive! Did you manage to find the gems? Are you truly the savior of my reputation I have hoped for? Please tell me you didn''t waste a charge on the phial just to chat; those things are NOT cheap, and I''m already in dire financial strai',12340),
	 (2199,0,0,'Have you got the five silver bars I asked for?  I will share my sad tale of woe with you concerning the necklace you now possess... but only after I get those bars!  Please, help a gnome out, won''t ya?',12340),
	 (2198,6,6,'You''ve got the wrong gnome, pal! I was never there! You can''t prove anything!$B$BWait a second... who are you? What the... where did you find this necklace at?',12340),
	 (2178,0,0,'The pot is empty and I''m hungry! What''s taking you so long?',42083),
	 (2161,1,0,'Welcome to Razor Hill!',12340),
	 (2160,3,0,'Hi there! Come in, take a seat by the fire and warm yourself with a flagon of ale.',12340),
	 (2158,2,0,'',12340),
	 (2159,6,1,'How might I be of service to you, young one?  Are you here to rest in the inn?  Do you require a hearthstone?',12340),
	 (2139,1,0,'With the infected Den Mother slain, the population of Rabid Thistle Bears entering our land is lessened. Waste no time, $N.',12340),
	 (2138,1,0,'Is your task complete?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (2118,1,6,'Have you brought me the sick animal, $N?$B$BShould you fail to spring the trap, do not fret - Tharnariun''s Hope is eternal. If you require another trap, abandon your task and report back to me.',12340),
	 (2098,0,0,'Have ye found me broke down key, landlubber?',12340),
	 (2078,1,0,'Where be me first mate, $N? Shackles n'' sharks fer ye soon if ye don''t hurry!',12340),
	 (2041,1,0,'',12340),
	 (2040,6,6,'Have you found the Gnoam Sprecklesprocket, $N?',12340),
	 (2038,6,6,'$N! Where are my things?!',12340),
	 (2039,1,0,'',12340),
	 (1999,1,0,'Have you located the documents, $N?',12340),
	 (1998,1,0,'I have placed the utmost faith in you to perform this service for Lord Varimathras.',12340),
	 (1961,1,0,'Anastasia said you would come to me, and I am prepared to fashion your robes.  Do you have the gems and the linen?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1962,1,0,'',12340),
	 (1963,1,0,'It is a fool who believes a charge with axe drawn is more dangerous than a knife in the dark.',12340),
	 (1978,1,0,'Yes?',12340),
	 (1960,1,0,'Have you investigated the disturbance, $N?  Have you captured the creatures?',12340),
	 (1958,1,0,'',12340),
	 (1959,1,0,'',12340),
	 (1957,1,1,'You have not killed the required amount of mana surges, $N.',12340),
	 (1956,6,6,'Have you been to Uldaman, $N?  Did you defeat the obsidian sentinel?',12340),
	 (1955,1,1,'You''ll have to kill that demon to remove its taint from the orb, $N.',12340),
	 (1954,6,6,'Do you have an infernal orb, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1952,1,0,'',12340),
	 (1953,1,0,'',12340),
	 (1951,2,2,'Greetings, $N.  Did you find the book, Rituals of Power?',12340),
	 (1948,3,3,'Hello, $N. Do you have the items I require?',12340),
	 (1949,1,0,'',12340),
	 (1950,5,5,'What are you waiting for? I need my magic phrase!',12340),
	 (1946,1,0,'',12340),
	 (1947,1,0,NULL,12340),
	 (1945,1,0,'Greetings, $N. Deino said you would come, and would bring the laughing sisters'' hair. Do you have it?',12340),
	 (1943,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1944,1,0,'I am pleased you have returned with your skin intact, $N. Do you have the water sample? I am eager to study its properties.',12340),
	 (1942,1,0,'',12340),
	 (1941,1,0,'',12340),
	 (1940,1,1,'Ah, yes. The mages of the Wizard''s Sanctum said you''d speak with me. Do you have the required silk?',12340),
	 (1939,1,0,NULL,12340),
	 (1938,6,6,'Do you have the book, $N? Its secrets are not meant for the untrained, and plumbing its depths can lead to doom and ruin.',12340),
	 (1921,3,3,'Hello, $N.  Jennea told me you would come.  Do you have something for me?',12340),
	 (1920,6,6,'Have you captured the creatures, $n?  They must be studied in order to determine the reason behind their arrival.',12340),
	 (1919,1,0,'',12340),
	 (1899,1,0,'Success, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1918,6,0,'Yeah, what do you need?',12340),
	 (1898,1,0,'Hello. Something I can do for you?',12340),
	 (1886,1,0,'Success to report?',12340),
	 (1883,1,0,NULL,12340),
	 (1884,1,0,'You must hurry, $N. Destroy the ju-ju heaps!',12340),
	 (1885,1,0,'',12340),
	 (1881,1,0,NULL,12340),
	 (1882,1,0,'Do you have the snapdragons? That breed of flower is highly receptive to magic energies, and studying the snapdragons so close to the Plaguelands can tell us if the plague has entered Tirisfal Glades.',12340),
	 (1879,1,0,NULL,12340),
	 (1880,6,6,'Did you find the gizmonitor? I must have it before its energy supply runs out!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1878,5,5,'Back again, $n?  If you have five more Wastewander water pouches, then I have a care package with your name on it!',12340),
	 (1859,1,0,NULL,12340),
	 (1860,1,0,NULL,12340),
	 (1861,6,6,'Do you have the sample, $N? The flow of magic in Stormwind and Elwynn has been altered, and I must know if it is seeping into the water.',12340),
	 (1847,1,0,NULL,12340),
	 (1848,1,0,NULL,12340),
	 (1858,1,0,'Is it not vexing to have the subject of your desire within your grasp, but to have no way of getting to it?',12340),
	 (1844,1,0,'Do you have the horn? Is the matriarch free of pain?',12340),
	 (1845,1,0,NULL,12340),
	 (1846,1,0,'I''m waiting for those shinbones, $N. They''ll make a nice frame for your leg guards.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1843,1,0,NULL,12340),
	 (1841,1,0,NULL,12340),
	 (1842,1,0,'Do you have the hooves, $N? The magic within them is strong.',12340),
	 (1840,1,0,NULL,12340),
	 (1839,1,0,NULL,12340),
	 (1838,1,0,'Do you have the items on my scroll, $N?',12340),
	 (1825,1,0,NULL,12340),
	 (1822,1,0,NULL,12340),
	 (1823,1,0,NULL,12340),
	 (1824,1,0,'Do you have the antennae? If so then give them to me quickly, for twitching antennae do not twitch forever...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1821,1,0,'Do you have the heirlooms, $n?',0),
	 (1820,1,0,'',12340),
	 (1818,1,0,NULL,12340),
	 (1819,1,0,'Your task is yet undone, $N. It is not wise for a $C to show fear...',12340),
	 (1805,1,0,'Yes, $N? Of what service can I be to you?',12340),
	 (1806,1,0,'',12340),
	 (1804,1,0,'Haven''t seen you around these parts for a while. Have you found the tome and the rods?',12340),
	 (1803,1,0,'It may be that you are chasing after fairy tales, $N, but truth can be found at the center of even the wildest rumors.',12340),
	 (1801,1,0,NULL,12340),
	 (1802,1,0,'Did the rumors prove true, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1800,1,0,'Are we there yet?',12340),
	 (1798,1,0,NULL,12340),
	 (1799,6,6,'And obviously not being a mage, I wonder if I can trust you at all. I can smell the power of the arcane on you, but you seem to have eluded the stank of corruption that comes so willingly with your kind.$B$BYes, a $C... a $C has come to ask for my help.$B$BWell, what is it I can do for you, $N?',12340),
	 (1796,6,6,'How goes your search for the robes, $N? Have you created them yourself? Such personal touches I find make the imbuing of magic that much sweeter. It gives you a greater sense of accomplishment. But I understand if you choose the quicker path and have it made for you - there''s something to be said for such... ambition.',12340),
	 (1793,1,0,NULL,12340),
	 (1794,1,0,NULL,12340),
	 (1795,1,0,'Every $C should have a felhunter at his command. Though it be difficult to tame, the powers it brings to its master far outweigh the cost.',12340),
	 (1788,1,0,NULL,12340),
	 (1789,1,0,NULL,12340),
	 (1790,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1791,1,0,NULL,12340),
	 (1792,1,0,NULL,12340),
	 (1787,6,6,'Is Henze safe, $N? Were you successful?$B$BBetween your skill with a weapon, and the power of the Light, I''d imagine Heroes'' Vigil is safe from any Defias threat, but that''s for the King and his advisors to say.',12340),
	 (1786,1,0,NULL,12340),
	 (1785,1,0,NULL,12340),
	 (1784,1,1,'Yer back! I''m glad to see it, $N. My wounds are healed and I''m about ready to return to Helm''s Bed lake as soon as I c''n convince me wife that I''ll be fine.',12340),
	 (1782,1,0,NULL,12340),
	 (1783,1,0,NULL,12340),
	 (1781,1,0,NULL,12340),
	 (1778,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1779,1,0,NULL,12340),
	 (1780,1,0,NULL,12340),
	 (1758,1,0,NULL,12340),
	 (1740,1,0,'It took me many years to collect the pieces of the orb of Zargain, but it has served me well, as I am sure the orb of Soran''ruk will serve you.',12340),
	 (1739,11,11,'Sometimes I wonder if Surena was not a succubus in disguise, sent to warp and twist my mind... Ha! I give her too much credit, I think.',12340),
	 (1715,1,0,NULL,12340),
	 (1716,1,0,NULL,12340),
	 (1717,1,0,NULL,12340),
	 (1718,1,0,NULL,12340),
	 (1719,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1738,6,6,'Was your search a success, $N?',12340),
	 (1713,5,5,'$N, I must have the whirlwind heart!',12340),
	 (1714,1,0,'The cauldron bubbles. Its vapors beckon...',12340),
	 (1712,6,6,'Do you have the items, $N? Gathering them is the proof I need that you have the strength to face Cyclonian.',12340),
	 (1711,1,0,NULL,12340),
	 (1709,1,0,NULL,12340),
	 (1710,6,6,'Do you have the shells, $N? They are quite strong, and can be rendered into a lacquer I will use to coat the links of my new mail armor.',12340),
	 (1708,3,3,'Hello hello, $N! Do you have the searing coral? I can''t wait to get to work!',12340),
	 (1706,1,0,NULL,12340),
	 (1707,6,6,'Got the five Wastewander water pouches we need?  If you do, then the Gadgetzan Water Company Care Package, Model 103-XB, will be yours!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1705,6,6,'$N, do you have the burning blood and rock? I''ll need them to complete the armor.',12340),
	 (1704,2,0,'Good day, or morning or evening. I can''t tell from way down here. So do you have business for me?',12340),
	 (1702,3,0,'Hello! Dry times, don''t you think?',12340),
	 (1703,2,0,'I bid you greetings, $C.',12340),
	 (1701,6,6,'How goes the scavenger hunt, $N? Do you have the materials?',12340),
	 (1700,2,0,'Hello, and well met. How might I be of service to you?',12340),
	 (1699,1,0,NULL,12340),
	 (1698,1,0,NULL,12340),
	 (1692,1,0,'Greetings, young $C. How might my skills serve you?',12340),
	 (1693,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1691,1,6,'Well, were you able to take out those nomads like I asked? The Gadgetzan Water Company is developing plans based on your success here! Don''t let us down, now...',12340),
	 (1690,1,0,'Back so soon? I hope you were able to bring some goblin-style justice to those Wastewander Bandits and Thieves like I asked you to!',12340),
	 (1689,1,1,'I cannot show you how to control a voidwalker until you have overtaken one.',12340),
	 (1688,1,1,'Even the older and wiser can be unmanned by the wiles of youth and beauty, $N. A piece of advice you would do well to remember throughout your life.',12340),
	 (1687,1,0,'Are we there yet?',12340),
	 (1686,1,0,'Have you defeated the Shade of Elura, $N? And do you have the lost elunite ore?',12340),
	 (1684,1,0,NULL,12340),
	 (1685,1,0,NULL,12340),
	 (1683,1,0,'Do you have the horn, $N? Is our moonwell free of the fiend Vorlus?',12340),
	 (1682,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1680,1,0,NULL,12340),
	 (1681,1,0,'Have you entered Ironband''s Compound? Did you find the umbral ore?',12340),
	 (1678,1,0,'Have you been to Vejrek''s hut, $N? Is that $R stink I smell on you?',12340),
	 (1679,1,0,'Did you make the switch?',12340),
	 (1665,6,0,'I saw your fight with Bartleby. Nicely done! Did you get his mug?',12340),
	 (1666,1,0,NULL,12340),
	 (1667,6,6,'Do you have my badge? I don''t want to think of the mischief Dead-tooth Jack could cause with it.',12340),
	 (1661,1,0,NULL,12340),
	 (1655,11,11,'So, any luck yet? Haha, those ogres didn''t get the best of ya yet, did they?',12340),
	 (1656,1,6,'Yes, young one? What can Kauth do for you?$B$BThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1653,1,0,NULL,12340),
	 (1654,1,1,'The items you''re seeking will be difficult to acquire, but I can assure you, the weapon I will craft for you will be worth the effort.$B$BIt will be my finest work to date, and only a small payment for the service you''ve done me.',12340),
	 (1649,1,0,NULL,12340),
	 (1650,1,0,NULL,12340),
	 (1651,1,0,NULL,12340),
	 (1652,1,0,NULL,12340),
	 (1648,1,1,'What with the influx of tradesmen here and throughout Azeroth, there''s a smaller supply of items we use to make clothes for the children of our orphanage. Helping me collect linen so my wife can make new clothes for them is very noble of you, $N. Thank you.$B$BHopefully, I''ll be able to return home to my wife soon.',12340),
	 (1645,1,0,NULL,12340),
	 (1646,1,0,NULL,12340),
	 (1647,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1643,1,0,NULL,12340),
	 (1644,1,1,'I hope my John is having better luck in Ironforge. He so dislikes his trips there because it leaves the kids and me alone, but he knows it must be done. He''s so kind-hearted.$B$BSome years have been easier than others, but this one''s been rougher by far. It''s almost as though something in the air is signaling a huge change. Who knows though?',12340),
	 (1642,1,0,NULL,12340),
	 (1640,1,0,NULL,12340),
	 (1641,1,0,'',12340),
	 (1639,1,0,NULL,12340),
	 (1638,1,0,NULL,12340),
	 (1618,1,1,'I hope you''re here with good news from Ironforge. Because I''m at my wit''s end!',12340),
	 (1599,1,0,'Those feather charms the novices carry have some sort of magical power to them. It will be interesting to research them. I wouldn''t have expected it from the trolls.',12340),
	 (1598,11,0,'It was too conspicuous for me to steal the book myself. What luck one of their own patsies did the dirty work for me.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1581,1,0,'Hello, $N. Do you have the elixirs to trade?',12340),
	 (1582,0,0,'Greetings, $N.',12340),
	 (1580,6,6,'Did you find any electropellers? I''ll need them if I''m to continue my research on duck decoys...',12340),
	 (1560,1,0,NULL,12340),
	 (1578,6,6,'I have no time to chat. Do you have business with me?',12340),
	 (1579,6,6,'Did you find my gaffer jacks, $N? Without my gaffer jacks I can''t tune my stintle pegs!',12340),
	 (1558,1,0,'Are we there yet?',12340),
	 (1559,1,0,NULL,12340),
	 (1536,1,0,'The well remaining pure within the town reminds me of stories told to me when I was younger, $N. Even in times of great pain and sorrow one can find a sliver of hope, a small symbol to rally around. The orc people see Thrall this way. He survived against great odds and rose up to lead our people through his strength and example.$B$BI''m not sure any orc has suffered as much as he has, but at the same time, I''m not sure any orc is as strong as he is either.',12340),
	 (1535,1,0,'I am just about prepared to send you on your other tasks. Have you filled the skin yet?$B$BI know how protective the quilboar can be. Even such a small water source is a vast hoard of wealth to them. They have great feasts when even the slightest rain comes to the Barrens. Water is sacred to their kind because it is so scarce. Do you understand?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1534,1,0,'Do you have the water yet, $N? Tales say the ruins were protected by large creatures of nature that do not care for visitors, but those could be myths to scare off the enemies of the night elves.$B$BRegardless, be careful.',12340),
	 (1532,1,0,NULL,12340),
	 (1531,1,0,'',12340),
	 (1527,1,0,'Yes, $N? What do you have there?',12340),
	 (1528,1,0,NULL,12340),
	 (1529,1,0,NULL,12340),
	 (1530,1,0,NULL,12340),
	 (1526,1,0,'The brazier stands about a third your height, and looks normal, save for the inscriptions along its smooth metal rails. The metal shows no signs of wear from the weather, and the bowl seated at the top of it feels cool to the touch.',12340),
	 (1525,1,0,'I have enough ingredients for a sapta of fire if you can find the reagent pouch and some fire tar. The Burning Blade fanatics carry the proper components for most of their spells in those pouches, and usually have enough of the items I need that we will not have to search much farther for anything else.$B$BThe saptas are always made from ingredients that are closely tied to their respective elements. It makes our work easier because of the warlocks'' ties to fire.',12340),
	 (1523,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1524,1,0,'Greetin''s, $N. You''ve found yerself at the Shrine of the Dormant Flame. Only those knowledgeable enough in the shamanistic arts will ever learn the secrets of this place and the power it holds. I''m sorry you made the trip all this way, only to be turned back now--the journey up here is far from safe after all--but I am the keeper of the shrine, and I cannot allow just anyone to wander around here.',12340),
	 (1522,1,0,NULL,12340),
	 (1520,1,0,NULL,12340),
	 (1521,1,0,'Greetings, $N. You would not return to me if you had not accomplished your task. May I be the first to welcome you fully to the first path of four that will forever rule your travels.$B$BIf you have the stone the earth gave to you, I will give you the totem it promised. If not, then I pity you. There is much pride to be had when you''ve fully dedicated yourself to the elements.',12340),
	 (1519,1,0,'The earth is patient, and will wait for you until you are ready because she knows in time all things erode and are reborn. It is the cycle of things. Mountains become deserts. Rivers become canyons. The earth is the most stubborn and wise of all the elements.$B$BYou must learn patience and stamina above all things. The earth calls for you now because she feels you are ready. Consider this your rebirth if you succeed. You will never be able to go back to ignorance afterwards.',12340),
	 (1518,1,0,'I wish to be the first to welcome you fully to the first of four paths that will forever lead you in your destiny.$B$BIf you have the stone the earth gave to you, I will give you the totem it promised.$B$BIf not, then be gone with you until you have found your way.',12340),
	 (1516,1,0,'Patience is earth''s greatest virtue. The earth witnesses the cycle of all things: the mountains becoming deserts; rivers becoming canyons. The earth is the most stubborn and wise of all the elements and it does not tolerate impatience.$B$BThe earth beckons you now because a time of conflict draws near. When you return to me successful, then you shall be that much closer to being made whole.$B$BOthers will be envious of your wisdom and hate you for their ignorance.',12340),
	 (1515,1,0,'Urrrghhhh...',12340),
	 (1514,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (1513,1,0,'When I look upon a succubus, my heart begins to soar... But at the same time, I can almost sense my soul''s ebb, drifting away like the tides.$B$BBe wary, my friend.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1512,1,0,'You have returned. Are you ready to battle a succubus?',12340),
	 (1505,1,0,NULL,12340),
	 (1506,1,0,NULL,12340),
	 (1507,1,0,NULL,12340),
	 (1508,1,0,NULL,12340),
	 (1509,1,0,NULL,12340),
	 (1510,1,0,NULL,12340),
	 (1511,1,0,'Yes, what is it?',12340),
	 (1504,1,0,'The voidwalker is a powerful creature. I remember when it was I that was in your shoes, $N. Over the years, my own voidwalker has grown to fight me less, though I suspect that is only because it hopes I will let my guard down.$B$BRemember that, $N.',12340),
	 (1503,1,0,'Do you have my steel bars?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1502,1,0,NULL,12340),
	 (1501,1,0,'Do you have the Tablet of Verga, $N? If not, I do not wish to speak with you until you do.',12340),
	 (1499,1,0,NULL,12340),
	 (1498,1,0,'Do you have the scales, $N? Unless you can withstand the attacks of the thunder lizards, you will not benefit from my instruction.',12340),
	 (1490,1,0,NULL,12340),
	 (1491,0,0,'Where is my wailing essence?',12340),
	 (1492,0,0,'You seek passage on the next ship, or have some item you wish to send aboard it?',12340),
	 (1489,1,0,'Your masters are fools to send you here, for I will never again be a Scourge slave!',12340),
	 (1488,1,15,'Glory to the Horde, and death to our enemies, $N!$B$BThe demons in Desolace pose a greater threat than ever before. My hope of returning to the Warchief dwindles as more and more of the foul creatures seem to appear.$B$BI sometimes wish it was only the centaur we had to deal with.',12340),
	 (1486,0,0,'I am very interested in examining the hides from the deviate creatures who have infested these caves. Have you had any luck in collecting some, $C?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1487,1,0,'$N, we, the Disciples of Naralex, need your help. Our numbers are dwindling with our master trapped in his twisted nightmare. We have not the forces necessary to deal with the corrupt creatures which now haunt these caverns.$b$bI beg of you, enter the caves and wage war on the deviate creatures!',12340),
	 (1483,1,0,NULL,12340),
	 (1484,1,0,NULL,12340),
	 (1485,1,0,'It is important that you can control the beings that you summon through your magic. There are few enough interested in learning the ways of the $C that I would risk throwing your life away by teaching you something before you are ready.',12340),
	 (1482,0,0,'I am ready for the oracle crystal, $c. Finding and destroying this Lord Azrethoc would garner a great deal of favor with the Warchief for both of us. We would do well to work together and to do so swiftly so we may further our own ends and curry favor with the Warchief. ',12340),
	 (1481,0,0,'Do not bring me an incorrect scalp, $c. Using the incorrect reagents could cause our deaths. The demon lord may have contingency spells on his person to slay those who would scry upon him.$B$BFate has already dealt me enough pain.',12340),
	 (1480,0,0,'The Burning Blade begin to realize how weak they truly are. Their magics are pathetic, their strength feeble.$B$BTheir only power comes from those they serve, and not from any understanding of true power and knowledge.',12340),
	 (1478,1,0,NULL,12340),
	 (1479,1,0,'Are we there yet?',12340),
	 (1477,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1476,1,0,'I have been pleasantly surprised by the speed of your progress so far, $N. Bring me the hearts and you will impress me once again.',12340),
	 (1475,1,1,'As dusk slowly descends upon my career I turn to you, $N, to help me in my final quest for the Explorers'' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.$B$BPride makes it hard for me to ask for your help in collecting the Atal''ai Tablets. But old age forces the necessity.$B$BPlease help me, $N. I want to retire from the Explorers'' League having completed their final bidding.',12340),
	 (1474,1,0,'Of the powers from beyond the void, the succubus is one of the most dangerous, as the weak are most easily wrapped around its fingers.$B$BRemember that now and in the future.',12340),
	 (1472,1,0,NULL,12340),
	 (1473,1,0,'Egalin was the teacher that taught me. With hardly a look, he was able to command the voidwalker he had summoned.$B$BWhen it came my turn to try, I was overconfident. Do not trifle with the powers that you wield, $N, they can consume even the vigilant.',12340),
	 (1471,1,0,'I expect to hear of your success, $N. Not meeting my expectations will be the least of your worries, however, should you fail.',12340),
	 (1470,1,0,'Your power is little now, though I suspect already you sense the possibilities.$b$bEven the dead might feel alive, with that power coursing through us.',12340),
	 (1468,1,0,NULL,12340),
	 (1469,6,6,'At long last you have returned, $N. It has been quite some time since we last spoke. I thought perhaps you had forgotten about my quest.$B$BDid you locate that wily gryphon rider? Did he have anything to report?',12340),
	 (1467,1,0,'Well met, $N. Business is booming, the sounds of anvils being struck rings throughout Ironforge, the bellows blow the fires hot, and me wife''s making me a pie for dessert after tonight''s dinner. Could life be any grander?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1466,1,1,'I didn''t even realize these demon things were in Desolace. Last I read, centaur pretty much owned the land after the night elves picked up and left years ago.$B$BI wonder why they took up here, and how.',12340),
	 (1465,0,0,NULL,12340),
	 (1464,1,0,'Speak to Telf Joolam for another Fire Sapta.',12340),
	 (1463,1,0,'I give you one in good faith. You already proved yourself once, but me tinkin'' you should be more careful in the future.',12340),
	 (1462,1,0,NULL,12340),
	 (1459,1,1,'Sorry I couldn''t tell you where to find the kodo or the scorpashi. I''m not terribly familiar with the area, and I haven''t had time to explore.',12340),
	 (1458,1,1,'Despicable creatures, the satyr. Story says they''re somehow tied to the night elves, but I''m not so sure I believe it.$B$BI think they get that on account of that one elf that brought them into the war few years back. World''s never been the same since. Lot more dangerous, and a lot scarier.',12340),
	 (1457,1,0,'Business is booming, $N, and I don''t have a lot of time for questions. If you''ve got business with the Reclaimers, then let''s hear it. If not, I''m gonna have to ask you to talk to one of me underlings - they''re adept enough at taking care of things ''round here.',12340),
	 (1455,1,0,NULL,12340),
	 (1456,1,1,'No offense to whoever Nijel is, but this camp ain''t the most comfortable place I''ve spent a night, if you know what I mean, $N.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1454,1,0,NULL,12340),
	 (1453,1,0,NULL,12340),
	 (1452,6,6,'Ya ever had a Rhapsody Malt? One of my finest brews, if I do say so myself. Hiccup!$B$BBut if I''m gonna relive the horrors of that fateful flight over... hiccup... the swamp, well I''m gonna need me something a wee bit stronger. Hiccup!$B$BDon''t suppose you found me those gizzards and livers I need to add that extra kick to my Kalimdor Kocktail?$B$BHiccup!',12340),
	 (1450,1,0,NULL,12340),
	 (1451,1,0,NULL,12340),
	 (1449,1,0,NULL,12340),
	 (1448,1,0,'I have traveled the world from the jungles of Azeroth to the snowy peaks of Khaz Modan.$B$BNever before have I asked for help in my adventures. But my old bones are tired.$B$BNothing would leave me feeling more satisfied than knowing that I completed my final quest for the Explorers'' League$B$BIf you''d be so kind as to help me search for the Temple of Atal''Hakkar, $C, I''d greatly appreciate it.$B$BScour the Swamp of Sorrows and report back with your findings!',12340),
	 (1447,11,0,'I didn''t mean anything by the comment ''bout you being a stupid $C. We''re friends, right? No hard feelings?',12340),
	 (1446,1,1,'Once Jammal''an has been removed, I stand a chance of returning to my people.$b$bWith Jammal''an as their spiritual leader, the Atal''ai face certain destruction.',12340),
	 (1445,1,0,'If the Atal''ai fetishes hold the power to summon Hakkar and fulfill Jammal''an''s prophecy they must be seized. Such powers must be understood by the Horde!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1444,1,0,NULL,12340),
	 (1440,1,0,NULL,12340),
	 (1442,1,0,'I would be less trustful of one not on a holy path if they came asking about a Kor gem. But I trust your kind more than some of my kin. I do not judge your entire order based on the actions of just one of your fallen kind.',12340),
	 (1439,1,1,'I fear Tyranis will attempt to learn the Burning Blade''s secrets and count himself among their kind if they allow it - he has always adored the power magic brings to those who are seduced by it.$B$BI''m not sure I could endure returning home to my family with news of Tyranis'' spirit flirting with such dangers. It''s a terrible enough crime among my kind to pursue such things, but to become that which we attempt to protect ourselves from, well, that''s apprehensible.',12340),
	 (1438,1,0,NULL,12340),
	 (1436,1,0,NULL,12340),
	 (1437,1,0,NULL,12340),
	 (1435,0,0,'I have tried to make the magics as simple as possible. Drawing the spirit of your victim out of its injured form should be child''s play. Do not rely on the gem''s power to slay your foe completely. You must only activate the gem when they are close to death, or it will be useless.',12340),
	 (1434,1,0,'I was warned by a tauren companion that the satyr are not all they appear to be. He believes there is something more to them, that their evil is a twisting of their true nature. But I have not seen such things.$B$BI see only the ruthless slaughter of the weak and the corruption of those who seek dark power.$B$BI will continue in my duty of annihilating them until the Warchief directs me otherwise. Until then, I take no pity on them.',12340),
	 (1433,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1432,1,0,NULL,12340),
	 (1431,1,0,NULL,12340),
	 (1430,1,1,'I have a cask of wine waiting for your success, $N. It''s only right I taste the goods before I have it shipped back to my customers.',12340),
	 (1429,1,0,'You are brave to come here. Brave or foolish...',12340),
	 (1427,1,0,NULL,12340),
	 (1428,1,0,'Not until the sea and all her children are silenced will I be pleased... especially those disgusting fish men.',12340),
	 (1425,0,0,'You have business with me?',12340),
	 (1426,1,0,'I am patient. Patient and everlasting like an old kank stone from Draenor. The fish men shall not make it past our borders--not while I still stand. If we had an army at our disposal I would cleanse this world and all others of their presence. I feel my hatred seethe just speaking about them.',12340),
	 (1424,1,1,'No one knows what dark practices went on inside The Temple of Atal''Hakkar. But we do know that great and powerful forces of magic were used.$b$bWe must learn as much as we can about such magic. Perhaps the spells of the Atal''ai will prove of use to the Horde.$b$bOnce you have gathered enough Atal''ai artifacts from around the Pool of Tears, I can begin to understand what the trolls were hoping to accomplish and what went so horribly wrong.',12340),
	 (1423,6,0,'You have something for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1422,1,0,NULL,12340),
	 (1421,0,0,'Do you have the wizard''s reagents, $N?',12340),
	 (1420,6,6,'You returned. You have a report?',12340),
	 (1418,1,0,NULL,12340),
	 (1419,0,0,'Do you have the jawbones?',12340),
	 (1398,6,6,'Did you find any driftwood, $N?',12340),
	 (1396,1,0,'The swamp creatures press close, $N. Please, you must defend the camp!',12340),
	 (1393,1,0,NULL,12340),
	 (1394,1,0,NULL,12340),
	 (1395,3,3,'Hello! Don''t mind all the commotion, it''s just business as usual at Nethergarde Keep.$B$BYou have something for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1392,0,0,'Greetings.  And welcome to the Harborage.',12340),
	 (1391,20,0,'Please have mercy on me! I have information that goes beyond alliance boundaries. While I am no sympathizer of the Horde, there is political treachery going on that must be revealed!',12340),
	 (1390,1,0,'',12340),
	 (1389,6,6,'Do you have the crystals?',12340),
	 (1388,0,0,'I hope you have proven yourself of use to our dear friend, Apothecary Faustin.',12340),
	 (1387,0,0,'Do you have a report, $N?',12340),
	 (1386,1,0,'Are you afraid of the Kolkar? Why do you not kill them? Maybe you forgot how to kill. Hurry and kill Kolkar before they are dead!',12340),
	 (1384,1,0,'You have the charms? You showed the Kolkar they are weak?',12340),
	 (1385,1,0,'You will go now, or the Magram will crush you! To be our friend, you must kill Gelkis.',12340),
	 (1383,11,11,'That Infiltrator in Stonard will surely.... open up... after he drinks my special serum. Haha!$b$bThe ingredients required are by no means easy to procure. Shadow Panthers are common in the Swamp but collecting enough hearts for our purpose can be daunting. And the Mire Lord can be such a fussy beast.$b$b',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1381,1,0,'Do what I ask.  Prove to me that you are an ally of the Magram!',12340),
	 (1382,1,0,'Be gone! The Gelkis do not want you here. Leave now!!$B$BReturn after killing many Magram, and then I will speak with you.',12340),
	 (1380,1,0,'Is Khan Hratha dead? Do you have the key fragment?',12340),
	 (1374,1,0,'Show me you are a friend of the Gelkis, $N.',12340),
	 (1375,1,0,'Do tasks for the Magram, and I will help you.',12340),
	 (1372,1,0,NULL,12340),
	 (1373,0,0,'Show me you are a friend of the Gelkis, $N.',12340),
	 (1371,1,0,'If you are not our enemy, then you will do what I ask!',12340),
	 (1370,1,0,'Return after you further prove your worth to the Gelkis!',12340),
	 (1369,1,0,'If you are not our enemy, then you will do what I ask!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1368,1,0,'Your two feet step on Gelkis earth. You are not welcome here!$B$BProve you seek friendship with the Gelkis. Kill Magram centaur. Return when the ground is wet with Magram blood.',12340),
	 (1367,1,0,'Leave! The Magram do not speak with the weak. We kill them!$B$BIf you want to speak with me, then show me you are strong. Return after you slay many Gelkis.',12340),
	 (1365,0,0,'$N, have you defeated Khan Dez''hepah?',12340),
	 (1366,0,0,'How is your collection of ears, $N? Large?',12340),
	 (1362,1,0,NULL,12340),
	 (1363,1,0,NULL,12340),
	 (1364,6,6,'What brings you to Nethergarde Keep, $R?',12340),
	 (1361,1,0,'I note that your task is unfinished, $N. Shall I inform Sharlindra of your ineptitude?',12340),
	 (1360,6,6,'Well now, we''re you able to get slap around those troggs long enough to get into my chest and nab my treasure?',12340),
	 (1359,6,0,'You have something for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1358,0,0,'You have a package for me?',12340),
	 (1339,1,0,NULL,12340),
	 (1338,6,0,'A letter from the dwarven lands? I wonder who would call from so far to the north...$B$BPlease, let me see the order.',12340),
	 (1324,1,0,'Hello again, $N. I hope you don''t mind the assistance, but we couldn''t have Hendel escaping, or worse, wind up dead.',12340),
	 (1323,1,0,NULL,12340),
	 (1322,0,0,'Did you get them sacs from the spiders?',12340),
	 (1318,1,0,NULL,12340),
	 (1319,6,6,'Something for me to look at?',12340),
	 (1320,1,0,NULL,12340),
	 (1321,0,0,'Something for me, $c?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1301,1,0,NULL,12340),
	 (1302,1,0,NULL,12340),
	 (1289,1,0,'',12340),
	 (1288,1,0,NULL,12340),
	 (1287,1,0,NULL,12340),
	 (1286,1,0,NULL,12340),
	 (1285,1,0,NULL,12340),
	 (1284,1,0,NULL,12340),
	 (1282,1,0,'',12340),
	 (1276,3,0,'Hello there, $c. Something I can help you with?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1273,1,0,'Did you find Reethe?',12340),
	 (1274,1,0,NULL,12340),
	 (1275,1,0,'Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.$B$BPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.',12340),
	 (1271,1,0,NULL,12340),
	 (1270,1,0,NULL,12340),
	 (1268,1,0,NULL,12340),
	 (1269,6,0,'Have you found any leads on what happened at the Shady Rest Inn?',12340),
	 (1266,1,0,NULL,12340),
	 (1267,1,0,NULL,12340),
	 (1264,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1265,1,0,'Yes, $N?',12340),
	 (1262,0,0,'You traveled from Brackenwall Village in Dustwallow? How fares Nazeer, and how fare his efforts in the marsh?',12340),
	 (1260,1,0,NULL,12340),
	 (1261,0,0,'$N, did you discover Marg''s fate?',12340),
	 (1259,1,0,NULL,12340),
	 (1258,6,6,'My research with the Mudrock tongues is progressing nicely. I trust your crab hunt goes well?',12340),
	 (1253,6,6,'Have you found evidence from the site of the Shady Rest Inn?',12340),
	 (1252,6,6,'Have you found anything of interest at the Shady Rest Inn?',12340),
	 (1250,1,0,NULL,12340),
	 (1251,6,0,'What''s that you have there, $n? Evidence from the remains of the Shady Rest Inn?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1246,14,0,NULL,12340),
	 (1247,1,0,NULL,12340),
	 (1248,1,0,NULL,12340),
	 (1249,1,0,'Did he slip away? He looked a little shady the way he was watching us.',12340),
	 (1245,6,6,'I see you''re back, and in one piece. We both know you''re not here for cheese, so let''s cut out the pleasantries. Was Backus any help, or have you even left for Duskwood yet?',12340),
	 (1244,1,1,'Be careful out there, $N. I know Trias was the one to send you here, but that doesn''t mean there isn''t anything lurking out in the woods that couldn''t cause you some trouble... especially with you investigating the Defias.',12340),
	 (1243,6,0,'Not too safe to be traveling about in the woods, $N. Be careful, and if you see anything suspicious or dangerous, contact the Watchers immediately. Don''t try and take anything on yourself. We''re not responsible for anything terrible that might happen to you.$B$BBut we both know you''re gonna ignore me and fight whatever comes out of the darkness anyway, don''t we? Haha, yeah, you adventurer types... all the same.',12340),
	 (1242,6,0,'Hello, $N. Is there something I can do for you? Perhaps you''d like to try some of our special Trias cheddar? Or a block of Darnassian bleu?',12340),
	 (1241,1,0,'Hmph, you better have good reason to interrupt a man and his fishin''. I don''t take kindly to peddlers, let alone beggars.',12340),
	 (1239,0,0,'You have another matter to report, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1240,6,0,'There is an angry spirit about you, $gbrother:sister;. What brings you to Kin''weelay?',12340),
	 (1222,1,0,'Have you seen Mr. Ignatz? I sent him into the swamp some time ago and he hasn''t returned!',12340),
	 (1238,6,0,'You have something for me?',12340),
	 (1221,0,0,'Do you have the tubers, $N?',12340),
	 (1220,0,0,'You have something for me?',12340),
	 (1219,0,0,'Do you have a report to make?',12340),
	 (1206,0,0,'Where are those eyes?',12340),
	 (1218,6,6,'Spice.  We could all use some spice in our life.  You agree?',12340),
	 (1205,0,0,'Do you have the tooth of Deadmire, $N?  Have you ended the creature''s suffering?',12340),
	 (1204,6,6,'Did you get the forked tongues?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1203,6,6,'You have my blade??',12340),
	 (1201,1,0,'Did you find the infiltrators, $N?',12340),
	 (1202,0,0,'Did you find the documents, $N?  They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.',12340),
	 (1200,1,1,'Time is a precious commodity, $C.$B$BMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.$B$BState your business quickly or be on your way.',12340),
	 (1197,6,6,'I am eager to put my hands upon the Cloven Hoof. Have you taken it yet?',12340),
	 (1198,1,0,NULL,12340),
	 (1199,1,1,'Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight''s Hammer.$B$BHave you made any progress in ridding their presence?',12340),
	 (1196,6,0,'I don''t suppose you''ve been sent by Zangen, hm?',12340),
	 (1194,1,0,NULL,12340),
	 (1195,1,1,'Once we have the filled phial, we can send it along to my associate, Rau, in the Thousand Needles. He was the one who requested the phial of water, so he''ll better know how we can make use of it.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1193,1,0,'A large, broken trap lies before you. From the looks of it, the ogres have tried to repair the trap but to no avail. A hastily written note lies next to the trap, and strangely enough it details exactly what is needed to repair it: a thorium widget and some frost oil. Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.$b$bClearly, it would seem fortuitous that very few ogres know how to read.$b$bClearly.',12340),
	 (1190,1,0,NULL,12340),
	 (1191,1,0,NULL,12340),
	 (1192,1,1,'I''d like to integrate indurium into different parts of our racers, but I need large amounts of raw indurium to create these parts.$B$BYou can find indurium ore in the Uldaman excavation in the Badlands, across the sea in Khaz Modan.$B$BThe gnomes are getting their own supply of it, so it''s important we get our own to keep pace with them.',12340),
	 (1189,1,0,'Can you believe Pozzik put a bucket of sand on the racer? How am I supposed to hit my maximum speed with a bucket of sand under the seat?',12340),
	 (1188,0,0,'As I''m sure you know, the Gizmorium can service all of your tinkering needs! How can I help you?',12340),
	 (1187,0,0,'How''m I supposed to show my face around the track without a little extra kick to get me going? It''s a travesty, I tell you.',12340),
	 (1186,1,0,NULL,12340),
	 (1184,1,0,NULL,12340),
	 (1185,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1183,1,0,'$N! Did you manage to track down the fuel regulator?',12340),
	 (1180,1,0,'',12340),
	 (1181,1,0,NULL,12340),
	 (1182,0,0,'Much as I hate to admit it, that gnome team they have out there is pretty good. Our boys need every edge they can get.',12340),
	 (1177,0,0,'Gimme food or me eat you.',12340),
	 (1178,1,0,NULL,12340),
	 (1179,5,0,'Watch where you''re stepping!  Watch watch watch!!  This is delicate stuff you see here, and if we''re to win then it must all work perfectly!',12340),
	 (1176,6,6,'Do you have those bones for me? I was just about to start working on lightening the steering rig, but I don''t want to open her up without all the parts I need.',12340),
	 (1175,1,0,'It''s bad enough having to clear out the wreckage of the racers without having to pick them out of burnt animal parts.',12340),
	 (1173,1,0,'I thought you were going to attempt to drive Mok''Morokk out of the village. Instead you have come to me to chat?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1170,1,0,NULL,12340),
	 (1171,1,0,NULL,12340),
	 (1172,1,0,'You must hurry to the Dragonmurk, $n. With Onyxia''s eggs riddled around the Wyrmbog, we face overwhelming numbers unless something is done quickly.$b$bDestroy her eggs! Don''t let the black dragon plague spread across our homeland!',12340),
	 (1169,0,0,'With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.$b$bOf course, convincing Mok''Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...',12340),
	 (1167,1,0,NULL,12340),
	 (1168,1,0,'Mok''Morokk tell all ogres to stay and keep this place safe. Me think ogres need to kill black dragon army and get old home back.$b$bYou help ogres get home back. Help ogres get revenge.',12340),
	 (1164,5,5,'Kill them all and bring me their heads!',12340),
	 (1166,0,0,'Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok''Morokk.$b$bGo find south in old home. Me too busy leading ogres to get.',12340),
	 (1160,1,1,'I hope you made the Scarlet Crusade suffer some before stealing the book from them.$b$bMy views of their kind are not unwarranted. The Crusade may have been followers of the Light at one time, but now, they seek to destroy any creatures that have not sided with their religion. They believe all undead, Forsaken or otherwise, must be cleansed, and those traveling in their lands must either be insane, or subject to the undead''s powerful magics. Idiots. Idiots and fools; all of them.',12340),
	 (1159,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1154,1,1,'Bring me the book after you''ve studied it. I will not ask you your question until after you have given me the book.',12340),
	 (1152,1,0,NULL,12340),
	 (1153,1,1,'I saw the travelers again - the ones that would not sell me a sample of the ore. I spit at them for not helping the warchief.$B$BMay they die in battle like cowards and not like warriors as should be the right of all people who ally themselves with the Horde.',12340),
	 (1151,1,1,'Rok''Alim is also called the Pounder by the centaur tribes in Thousand Needles because of the thundering his fists make as he pummels the creatures brave, or stupid, enough to stand in his path.',12340),
	 (1150,1,1,'You must be prepared spiritually, physically and mentally for the challenges that lie ahead of you.$b$bToo often do we rush forward before we are ready. I consider it my duty to the youth, no matter which tribe they belong to, to prepare them for the dangers they may face after they leave the sanctity of their home.',12340),
	 (1149,1,0,'Faith. It is far more important than some realize.$B$BIt does not matter what you believe sometimes. It is just important that you believe in something.',12340),
	 (1148,1,1,'Ah, it been a long time since you''ve come to see me, $N. What can I do for you today? You be looking like you''ve seen the face of battle recently. Good... good for the Horde and good for you. The more battle you''ve seen, the more helpful you''ll be; stronger, too.',12340),
	 (1147,1,0,'With the amount of travelers heading out to the Flats for those races, I''m sure we can convince enough adventure seekers to help push back those insects. My party and I won''t be able to leave until we do.',12340),
	 (1146,1,0,'War brings my group and I to the Shimmering Flats, $C. What brings you here?',12340),
	 (1144,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1145,25,0,'I envy you, $C. You have the look of someone who''s been outside the walls of Orgrimmar for a while.$B$BI myself would travel in the name of the Warchief if Thrall didn''t have need of my skills here in the city. But he leads us well, and I trust his judgement - I remain here for as long as he needs me.',12340),
	 (1141,1,1,'There''s plenty of good dishes you use Darkshore groupers for.  They''re good to eat, but I think it''s more fun catching them.$B$BYou caught any Darkshore groupers yet?',12340),
	 (1142,1,0,'What brings you to my home, $R?',12340),
	 (1143,1,1,'Athrikus Narassin is an ancient and powerful warlock. Perhaps we should wait for Delgren''s assistance, but he obviously had much faith in you to send you alone.',12340),
	 (1140,1,1,'I heard whisper once that the satyrs'' history is somehow related to that of the night elves, but I have found my esteemed hosts reticent to speak of the matter.',12340),
	 (1139,1,1,'Hammertoe''s quest must be actualized, $N. I owe him that much.$B$BYour return to Uldaman is imperative not only to that goal, but also to the safety of all dwarven kind. With the tablet in the hands of the Dark Irons who knows how powerful their army of golems would become.',12340),
	 (1138,0,0,'...lemon crab, whipper root crab, and Ironforge surprise crab.  That''s about it.$B$BOh, hello there $N.  Do you have them fine crab chunks I was telling you about?',12340),
	 (1137,1,0,NULL,12340),
	 (1136,0,0,'Have you been to the Alterac Mountains, $N? Did you face the elusive Frostmaw?',12340),
	 (1135,1,0,'Did you find Highperch, $N? Any luck with the wyverns there?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1134,0,0,'Do you have the pridewing venom sacs, $N? We cannot allow the orcs to use the beasts'' poisons against us!',12340),
	 (1132,1,0,NULL,12340),
	 (1133,1,2,NULL,12340),
	 (1131,0,0,'Have you defeated the foul Steelsnap, $N?',12340),
	 (1127,1,0,'Do you have those Zanzil mixtures yet, $N?',12340),
	 (1130,1,0,NULL,12340),
	 (1126,6,6,'Well, did it work? You''re still in one piece, which is good news. Did you find anything?',12340),
	 (1125,1,1,'Alliance or Horde, it doesn''t matter - no being deserves to be trapped on this world as a tortured spirit.  The freeing of these souls will make things right, $N.',12340),
	 (1123,1,0,NULL,12340),
	 (1124,1,0,'This is a dangerous land to be so casual, $C. What brings you to the wastes of Silithus?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1121,6,0,'What are you looking at?',12340),
	 (1122,1,0,'Hello $N. How''d that stout work out? It''s strong stuff, isn''t it?',12340),
	 (1119,3,0,'Hello, $N. Was Fizzlebub able to help us?',12340),
	 (1120,6,0,'Hi! You have something for me?',12340),
	 (1118,3,0,'Hello hello. And what brings a noble $R such as you down to Booty Bay?',12340),
	 (1117,6,0,'Did you get anything on Nazz Steamboil? Anything he might want to keep a secret??',12340),
	 (1115,1,0,NULL,12340),
	 (1116,6,6,'Back so soon? Do you have my dream dust?',12340),
	 (1114,0,0,'You have something for me? That''s great! let''s see it!',12340),
	 (1113,1,0,'Have you returned from the Scarlet Monastery? I''ll need many hearts for this delightful experiment!$b$bNo doubt, Varimathras and the Dark Lady will be pleased to be rid of the Scarlet Scum as well...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1110,6,6,'$N, have you been out into the Flats? Did you bring back that load of parts I wanted?',12340),
	 (1111,0,0,'Speak up! Tell me, are you dropping off or picking up?',12340),
	 (1112,0,0,'Did you make it to Ratchet and get those parts?',12340),
	 (1109,1,0,'Ah, I see you have returned. Were you able to procure any Kraul Guano?',12340),
	 (1107,6,6,'Do you have the tail fins?  If I can''t protect our car from its own speed, then it won''t last long in these races.',12340),
	 (1108,6,6,'Did you find any indurium flakes, $N. I have my forge heated up and ready to test them.',12340),
	 (1106,35,0,'Well, you found me. Good for you.$b$bAre you here about that axe I made for Gath''Ilzogg? Or are you here to reclaim Duchess Pamay''s honor?$b$bActually, I don''t care which it is. If you''re here to fight, then let''s get it over with...',12340),
	 (1105,1,1,'My brother is making progress with his new fuel design, and that has me worried. I need to start work on a tortoise shell fuel tank as soon as possible!',12340),
	 (1104,6,6,'Hi hi hi! Did you get that venom??',12340),
	 (1103,1,0,'Ya have the sapta, $G brotha:sista;?$B$BI know another that had trouble after defeating da corrupt water spirit--seems he waited too long and he came out of the spirit world too quick fer his taste. Hate to see dat happen to another, so I''ll just wait here fer a bit to make sure no one else be needin'' me help.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1102,6,6,'Once I know the foul beasts of Razorfen Kraul have been driven from their foul lair, I will be able to rest in peace, knowing that revenge has been served.$b$bHave you the driven the quilboar from the Kraul? Do you bring to me good news in the form of Razorflank''s heart?',12340),
	 (1101,1,1,'So long as Charlga Razorflank is mustering a force in Razorfen Kraul, these lands are in great danger.',12340),
	 (1097,1,0,NULL,12340),
	 (1098,1,0,NULL,12340),
	 (1100,6,0,'From your look of concern, I can tell that something is amiss....',12340),
	 (1096,0,0,'Sputtervalve will want some sort of proof that Gerenzo''s dead. I think his mechanical arm will probably do.',12340),
	 (1094,3,0,'Hello there! How can I help you?',12340),
	 (1095,1,0,NULL,12340),
	 (1093,0,0,'Did you find those plans? I''m eager to impress the new boss. Hopefully, once he''s convinced of my loyalty--well, as much as he can be convinced... goblin''s honor, you know?--he''ll feel comfortable making use of my rather impressive genius.',12340),
	 (1092,0,0,'Something I can help you with?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1090,1,0,NULL,12340),
	 (1091,6,0,'Yes, $N? What can I do for you?',12340),
	 (1089,1,0,'Three keyholes are carved into the stone.',12340),
	 (1084,1,1,'I have a feeling Gaxim will find a use for the shrapnel regardless of how the Venture Co. has used it in the past.',12340),
	 (1085,1,0,NULL,12340),
	 (1086,1,0,'You must find the Venture Company airport if it exists, $N.',12340),
	 (1087,0,0,'Here, channeling magic is like drawing water from a well with a bucket full of holes.',12340),
	 (1088,0,0,'When my master bade me to the peak of Stonetalon, I expected that all I would need was to lay waste to the night elves that crawled the sacred ruins of our ancient temple of Azshara, their touch despoiling its sanctity... but Ordanus had slipped my grasp.',12340),
	 (1080,6,6,'How''d it go, $N?',12340),
	 (1081,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1082,1,0,NULL,12340),
	 (1083,0,0,'The first time I saw the Charred Vale I almost wept, $N.',12340),
	 (1079,6,6,'Did you get the plans, $N?',12340),
	 (1078,2,2,'Hello again, $N.$B$BHave you already returned from the Vale in Stonetalon with those scales?',12340),
	 (1076,6,6,'Hello, $N. Have you found the component I need?',12340),
	 (1077,5,0,'Haha! you''re back! Do you have it? Do you have the spell?',12340),
	 (1075,1,0,NULL,12340),
	 (1074,0,0,'Ah, goodie goodie, you''re back.',12340),
	 (1072,1,0,NULL,12340),
	 (1073,6,6,'I can''t make any Nitromirglyceronium if I don''t have the potions... they''re vital to its creation.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1071,1,6,'How goes the battle on your end, $N?',12340),
	 (1070,1,0,NULL,12340),
	 (1069,1,1,'Did you get the eggs, $N? I already made a shipping deal with Wharfmaster Dizzywig!',12340),
	 (1067,6,0,'You have returned, $N. Do you bring aid from Apothecary Lydon?',12340),
	 (1068,1,1,'The tree spirits wail at the loss of their brethren, $N. You must destroy the shredders XT:4 and XT:9, or I fear Stonetalon will never be healed.',12340),
	 (1066,6,6,'Did you find the Syndicate Shadow Mages, and collect from them the blood?',12340),
	 (1065,1,0,'Ah, are you here with my new test subjects?',12340),
	 (1063,1,0,NULL,12340),
	 (1064,1,0,NULL,12340),
	 (1061,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1062,1,1,'The Greatwood Vale lies to the northwest, $N. Go. Strike fear into those who would pillage this land!',12340),
	 (1060,0,0,'You seem a shady character. You have something for me to see?',12340),
	 (1059,1,0,NULL,12340),
	 (1058,11,11,'Look at our poor little elf friends. All caged up with no forest to frolic in!$b$bNow were you able to find me some sap? How about the whiskers from the twilight runners? Don''t suppose you have that fey dragon scale on you?$b$bAnd eyes! I''ll need so many eyes! You just can''t mix up a fierce forest magic brew without a good helping of eyes!',12340),
	 (1057,1,0,'There is much work to be done before the Charred Vale can be restored to the lush forest it once was.$B$BClear the area of those foul menaces, $N! Only then can we begin to reclaim what belongs to nature.',12340),
	 (1055,1,0,NULL,12340),
	 (1056,1,0,NULL,12340),
	 (1054,1,1,'The furbolgs'' corruption has caused Ashenvale to become a fraction of its former glory.',12340),
	 (1053,1,5,'The corruption in the Monastery will not end until the highest ranking officials have been removed.$b$bIn the name of the Light, slay High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey. Once they have fallen, perhaps the true cause can be rekindled. Until then, anyone who crosses the path of the Crusade lies in peril.$b$bVenture forth from Southshore and make it so!',12340),
	 (1052,6,0,'Who goes there? What do you want from me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1051,1,0,'What do you want, stranger?',12340),
	 (1050,1,1,'The Monastery was a seminary for Paladins-in-training. Once a stronghold of the Light, it fell into the hands of the crazed zealots of the Scarlet Crusade.$b$bThe Crusade believed their goal a noble one: to purify the land of the undead plague. But insanity tainted their plight and now they stand enemies to all.$b$bBring Mythology of the Titans to me so I can study it and house it here in Ironforge.$b$bThe corrupt halls of the Monastery are no place for such a historical treasure.',12340),
	 (1049,1,1,'Cairne is a brave and noble leader and I would trust him with my own life. But it is others that I do not trust in this political climate.$b$bOnce I have a chance to gather all the knowledge available I can provide sound council to the Chieftain.$b$bHave you had a chance to travel to Tirisfal Glades? To the Scarlet Monastery? The Compendium of the Fallen is just one piece in this complicated puzzle...',12340),
	 (1047,1,0,NULL,12340),
	 (1048,1,0,'Perhaps I was not explicit in my orders, $c. I want High Inquisitor Whitemane killed once and for all. And while you''re at it, take out her top brass as well.$B$BKill that zealot, Scarlet Commander Mograine. Lay waste to Herod, the Scarlet Champion. And slaughter Houndmaster Loksey and his filthy mutts too.$B$BNow begone!',12340),
	 (1046,6,0,'The Sentinels do what they can here in Ashenvale, but it''s thanks to $rs like you that we have gained the ground we have.',12340),
	 (1045,0,0,'Have you slain Ran yet, my friend?$B$BEven the Night elves do not truly deserve his wrath. His hatred burns even brighter than my own, but his mind is no longer his own. He is a threat to all the natural creatures of this forest.',12340),
	 (1044,1,0,NULL,12340),
	 (1040,1,0,NULL,12340),
	 (1041,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1042,1,0,NULL,12340),
	 (1043,1,1,'The woods are perilous for the unprepared. Keep your weapons close at hand and your wits even closer, or your next journey into the haunted forest may be your last.',12340),
	 (1039,1,0,NULL,12340),
	 (1038,0,0,'What''d you find out?',12340),
	 (1037,1,0,NULL,12340),
	 (1036,1,0,NULL,12340),
	 (1034,6,6,'Do you yet have the Stardust, $N?',12340),
	 (1035,6,6,'Did you face the Shadethicket Oracle, $N? If so, then please hand me the fallen moonstone. Relara has strength left for only a few more breaths!',12340),
	 (1033,6,6,'$N, did you find Iris Lake? Do you have the Tear?',12340),
	 (1029,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1030,1,0,NULL,12340),
	 (1031,1,0,'Have you found them? What did Anilia say? Where is she?',12340),
	 (1032,1,0,'Please, help me avenge Anilia''s death.',12340),
	 (1028,1,0,'You can sense a subtle yet powerful force within the shrine and surrounding trees.$B$BYou begin placing the rod within the shrine and a soft thrumming noise emits from around you as the shrine begins to glow...',12340),
	 (1027,1,0,'Did you find the final piece of the rod, $N?',12340),
	 (1026,1,0,'It upsets me so that the treants have become corrupt. I wish I could do more to help them.',12340),
	 (1025,1,0,'The furbolg were not always our enemy, $N. But times change, and it is no longer a time of peace here in these dark woods.',12340),
	 (1024,1,0,'Hello. How are you?',12340),
	 (1023,2,2,'Ah, welcome back, $N.',12340),
	 (1022,1,0,'The tome of the shrine is a mysterious object. It is not a book in the traditional sense. The leaves of the tome were blessed by Mel''Thandris herself, and records events of import in its pages.$B$BIt is hard for me to explain. If you go to the shrine, you will understand.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1021,1,0,NULL,12340),
	 (1020,1,0,'I must apologize, for I have no time to speak.  My child, Relara, is deathly ill!',12340),
	 (1018,1,0,NULL,12340),
	 (1019,1,0,NULL,12340),
	 (1017,6,6,'Is it done? Is Sarilus Foulborne dead?',12340),
	 (1016,1,1,'Since you must destroy the bracers to kill the elementals, it will probably be difficult to find the specific ones that contain the information the divining scroll needs. You can trade bracers with others in order to obtain the ones you need, or perhaps you have the divined paper already?',12340),
	 (1015,1,0,NULL,12340),
	 (1014,1,1,'With Arugal''s death we stand to increase the Dark Lady''s stronghold on Lordaeron.',12340),
	 (1013,1,0,'Did you find the book, $N?',12340),
	 (1012,1,0,'The anguish of the Dor''danil druids still haunt my dreams, $N. You must destroy their leaders!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (1011,6,6,'Did you find the camp, $N? Do you have a bottle of disease?',12340),
	 (1010,6,6,'Have you gathered the Bathran''s Hair, $N?  The child''s health grows weaker by the hour...',12340),
	 (1009,0,0,'It is said that the Ring of Zoram is the key to any lock within the city. Do you have it, $N?',12340),
	 (1004,1,0,NULL,12340),
	 (1007,0,0,'Have you found the statuette, $N?',12340),
	 (1008,0,0,'We cannot allow the naga to invade our coasts, $N.  It is vital that you go to the Zoram Strand and complete your mission.',12340),
	 (1003,1,0,'You hear singing coming from Buzzbox 525.$b$b"Though crawler wine''s shweet, and thresher ale fine, and moonstalker moonshine ish grand. There''s nothing sho dear, as a thistle bear beer, and shoon I shall have shome on hand!"$b$bThe hatch is open and awaits the 4 grizzled scalps as you hear the song repeated over and over.',12340),
	 (1002,1,0,'Though you have yet to place the 6 Moonstalker Fangs inside, you believe you hear the sounds of static and incoherent gnome ramblings coming from within. Could someone else have fixed the machine already?',12340),
	 (1001,1,0,'The machine''s hatch is open and it seems to wait expectantly for 3 Thresher Eyes to be placed inside.',12340),
	 (1000,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (997,6,1,'You have something for me?',12340),
	 (998,1,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant. The berries that hang from the plant appear rotten and poisonous. It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (995,1,0,'Yes, $n?',12340),
	 (996,0,0,'You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.',12340),
	 (994,1,0,'',12340),
	 (993,0,0,'',12340),
	 (992,6,6,'Welcome back, Junior Surveyor $n!  Have you completed your assignment yet?',12340),
	 (990,1,0,NULL,12340),
	 (991,1,0,NULL,12340),
	 (986,1,0,'I can''t in good conscience permit you to seek Volcor until I''ve crafted that cloak for you.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (985,1,1,'Do not stay your hand from what must be done, child. I know how repulsive the idea of killing the creatures of the forest must be, but in this case it is necessary. No cure has been discovered for the corruption let loose upon the forest, and we must do what we can to halt its progress until one is found.',12340),
	 (984,1,0,'How goes your search, $N?',12340),
	 (983,1,0,'Buzzbox 827 sits with an eerie silence. A single flashing light indicates that it needs 6 Crawler Legs to be placed in its holding box.',12340),
	 (981,1,0,NULL,12340),
	 (982,1,1,'The captains of those ships were good night elves, and they deserve a better fate than they were given. Perhaps tending to their personal effects will be the best way to put their spirits to rest.',12340),
	 (980,1,0,NULL,12340),
	 (979,1,0,NULL,12340),
	 (978,6,6,'Where could these powers have originated from? I think we are on the right track to find the answer, $N.',12340),
	 (977,0,0,'I''ve just about finished attaching the fur, $N. Please, hurry back with those horns!',12340),
	 (975,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (976,1,0,'The Sentinels have a great need for supplies to reinforce themselves in Darkshore.',12340),
	 (974,1,1,'I''d go there myself, but... I''m a little scared of the fire elementals there!',12340),
	 (973,6,6,'You look a bit shaken up, $n. Are you well?',12340),
	 (971,1,1,'The journey to Ashenvale is long, and your task is not easy. But if you get me the manuscript, $N...then your reward will be great.',12340),
	 (970,6,6,'Have you acquired that soul gem?',12340),
	 (969,11,11,'Bring back da shards, and I be tellin'' you more!',12340),
	 (967,6,0,'You have some business with me, $C?',12340),
	 (968,3,0,'Hello, $Gsir:madam;.$B$BMay I interest you in one of my tomes?',12340),
	 (965,1,0,NULL,12340),
	 (966,6,6,'Have you found any more of their scrolls? I should be able to piece together a larger picture of the cult if you can find them.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (964,1,1,'Kill many and kill often, $C - we''ll need a decent supply of suitable skeletal fragments to make up the outer layer of the key. They don''t call it a Skeleton Key for nothing, you know.',12340),
	 (963,1,1,'With a great sorrow in my heart, I followed the Shan''do Stormrage into hibernation, and took my sorrow to my dreams, sleeping for the passing of thousands of years.',12340),
	 (961,1,0,'',12340),
	 (962,1,1,'I am eager to see if you can gather enough Serpentbloom from the Wailing Caverns. I''ve sent many to do my bidding but none have returned.',12340),
	 (960,1,0,NULL,12340),
	 (959,0,0,'The dockmaster has been on my case ever since Mad Magglish made off with that 99-year-old port. I guess that bottle was intended as a gift for Gazlowe from none other than Baron Revilgaz himself.$B$BIf you''re brave enough and patient enough to seek out Mad Magglish and get that port back, I''ll see to it you get a nice reward.',12340),
	 (958,0,0,'If only the tools of their undoing could have been destroyed in the cataclysm that destroyed our world... Nonetheless, we must do what we can to ensure that the horrors of our past are not repeated in the future.',12340),
	 (957,1,0,'In truth, $N, I am afraid... Afraid that your coming--all of this--is merely a figment of a deranged mind. Can you know the torture that this is? I... Please, you must go quickly.',12340),
	 (956,0,0,'The pillars of this shrine are as the bars of a prison to me, $N. No strength I still possess might break them, and no magic I wield might destroy them...$B$BFor a thousand years and more I have stared at them, wondering if at long last I outlived even the stone, would I be free? Or would it be invisible bars that held me then...',12340),
	 (954,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (955,1,0,'Once I have the earrings, I will cast the spell to search for the whereabouts of the seal that binds me. For centuries I have thought on the freedom destroying the seal would bring to me... Perhaps those centuries have taken a toll upon my mind that I might never recover...',12340),
	 (953,1,0,'When you have studied the tablets and learned of Ameth''Aran''s fall, I will take the knowledge on to Auberdine, and inform the Circle of Ancients.',12340),
	 (952,1,0,'Ah. $C. How may Onu assist you?',12340),
	 (951,1,0,'$N. Has your rooting through the Ruins of Mathystra been fruitful?',12340),
	 (950,1,0,'$N. You return.',12340),
	 (949,1,0,NULL,12340),
	 (948,1,0,NULL,12340),
	 (945,1,0,'',12340),
	 (947,6,6,'Do you have my mushrooms, $N? Have you been to the cave?',12340),
	 (944,1,0,'The Master''s Glaive, $N.$B$BGo there, then speak with me again.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (943,1,0,'With the Stone of Relu I will be able to release the hidden secrets of my fossil as well as Remtravel''s fossil from Darkshore, $N.',12340),
	 (942,1,0,'What ya got there, friend?',12340),
	 (941,1,0,'This planter is filled with soil, specially prepared by Denalan.',12340),
	 (940,1,0,'Hmm... You come with the spirit of the forest strongly within you, $C. What business do you have with the Arch Druid of the Kaldorei?',12340),
	 (939,6,6,'What is it, $C? You look concerned.',12340),
	 (938,1,0,'Mist... It was my fault! The witches caught me off guard... I should not have let them take you...',12340),
	 (936,1,0,NULL,12340),
	 (937,1,1,'Their slashing talons and piercing beaks may prove a difficult match for your own abilities, $N, but I have faith that you will not fail in this task.',12340),
	 (935,0,0,'I know that I did not summon you, so I cannot help but wonder why it is you have come to speak with me.$B$BWhatever it is, please make it quick.',12340),
	 (934,1,0,'Along with the druids, the Oracle Tree and the Arch $C have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (933,1,0,'At first the reports of crazed furbolg attacks were dismissed. Who could have thought that the peace-loving bear-men would turn to mindless rage? Yet another of the problems that plagues us here in our new home.',12340),
	 (931,0,0,'You have something for me?',12340),
	 (932,6,2,'Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, $N. His continued existence is an embarrassment to us all.',12340),
	 (930,0,0,'$N, you look like you have something to tell me. Do you have news concerning the timberlings?',12340),
	 (929,3,3,'Hello again, $N. Have you completed your task?',12340),
	 (926,1,0,'',12340),
	 (927,1,0,'$N! You have something for me?',12340),
	 (928,1,1,'Greetings, $C. For what purpose do I owe the pleasure of our meeting?',12340),
	 (925,1,0,'When the orcs were alone and without friends, the tauren welcomed them to a strange land and shared with them without asking anything in return. That''s honor, $N.',12340),
	 (924,1,0,'The Demon Seed still exists. I can sense its power...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (922,2,0,'Hello...$b$bAnd how may I help you?',12340),
	 (923,3,3,'Have you been to Wellspring Lake, $N? Have you been hunting the timberlings there?',12340),
	 (920,0,1,NULL,12340),
	 (921,1,1,'The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.$B$BThe druids take advantage of its properties, and the Sentinels revere the wells as shrines to Elune, but sorcery is forbidden to all.',12340),
	 (919,3,3,'Hello, $N. Have you found any sprouts near the waters?',12340),
	 (918,6,6,'Do you have the seeds? I am eager to plant them.',12340),
	 (917,6,6,'Have you been inside the Shadowthread Cave, $N? Did you find a spider egg?',12340),
	 (916,6,6,'Did you gather the venom sacs, $N?',12340),
	 (915,1,0,'I wish they''d make more flavors of ice cream other than strawberry, but I guess I''m lucky that strawberry is my favorite!',12340),
	 (914,6,6,'Memories of my nightmares haunt me, $N. Have you defeated the leaders of the fang and acquired their gems?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (911,1,0,'Are we there yet?',12340),
	 (913,6,6,'Is it done? Have you slain the thunderhawk?',12340),
	 (910,1,0,'Are we there yet?',12340),
	 (909,1,0,'Ah, hello again $N. I was just reading the waves the sea, much like I always do. What brings you to the outpost?',12340),
	 (907,0,0,'Are the thunder lizards defeated, $N?',12340),
	 (908,1,0,'Have you been successful in locating the fathom core? Without it we''ll have no idea what the Twilight''s Hammer is exactly up to down there.',12340),
	 (906,6,0,'Yes, what is it?',12340),
	 (905,1,0,'Have you been to the nests, $N?',12340),
	 (903,0,0,'How goes your hunt, $N? Have you found the prowlers?',12340),
	 (902,1,0,'Oh, you''re back, $N! Do you have the samophlange?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (901,1,0,'The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.',12340),
	 (900,1,0,'Blinking lights on the control console indicate that the main control valves have not been closed off.',12340),
	 (898,1,0,'Yes?',12340),
	 (899,1,1,'The quilboar will pay for this, $N. I swear it.',12340),
	 (897,6,6,'You seemed troubled, $N. How go your lessons in the Barrens? Did you find something that disturbs you?',12340),
	 (896,0,0,'If only we knew which one of the miners had found the emerald, it''d be a walk in the park...',12340),
	 (894,1,0,NULL,12340),
	 (895,0,0,'What''s happening? Something I can help you with? Goods to ship, perhaps an engineering job?',12340),
	 (893,1,1,'I, too, have doubts that the pathetic quilboars could attain any level of skill in the area of smithing, but I do as the Warchief commands, and I shall learn what I can about the Razormane tribe.$B$BI have had more menial tasks, and I do so willingly if it aids the orc people.',12340),
	 (892,0,0,'So, what did Dizzywig have to say?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (891,5,5,'My fleet is in peril with Captain Fairmount and her damned cannoneers blasting away from Northwatch Hold. I want her soldiers to pay as well. Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.',12340),
	 (890,0,0,'Wares to send on the next ship, $N?',12340),
	 (889,1,0,'Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.$B$BIt will not last long, but it should be enough to help you travel throughout the Barrens.',12340),
	 (888,1,1,'Did you find my things, $N?',12340),
	 (887,1,0,'I don''t even want to think about the profits I''ve lost from pirate raiding, and now they set up camp on my doorstep? It''s getting out of hand, Undermine''s got to do something about it.',12340),
	 (886,1,0,NULL,12340),
	 (885,0,0,'There is new resolve within you, $N. A resolve born from pain...$B$BAre you burdened with the death of Washte Pawne?',12340),
	 (884,0,0,'$N, there is a new power behind your eyes! You have met with the mighty Owatanka, have you not?',12340),
	 (883,0,0,'$N, when you approached I saw a new power in your stride. Tell me -- has your spirit met with the great Lakota''mani?',12340),
	 (882,0,0,'$N, have you bested Ishamuhale?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (880,6,6,'How goes your collection? Did you get the shells?',12340),
	 (881,0,0,'The great cat calls to you, $N.',12340),
	 (879,1,0,'How goes your hunt, $R? <snort>$B$BThork thinks he knows the truth about who leads the raids against his people, <snort> but he shall learn how wrong he is if you are successful.$B$BMy death is inescapable, but you have caused great pain to my enemies, so Mangletooth regrets nothing. <snort>',12340),
	 (878,1,0,'More information <snort> for the Horde when you''ve killed the Bristleback''s wise ones, $R. <snort> Not a moment earlier! Mangletooth is no fool.',12340),
	 (877,1,6,'Have you been to the Stagnant Oasis? Was there a fissure beneath its waters?',12340),
	 (876,0,0,'You''re not getting anything until I see Serena''s head.',12340),
	 (874,1,0,NULL,12340),
	 (875,0,0,'Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.',12340),
	 (873,0,0,'Fear not the waters, $R.',12340),
	 (872,1,1,'Cut off the head of their leader, and chaos ensues, $N. Learn this lesson well. It will aid you in the future.$B$BThe boars will flounder without direction, and we will be able to take back the Barrens.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (871,1,0,'The longer it takes to stop these attacks, the harder it will be to provide supplies for the people of the Crossroads.',12340),
	 (870,1,0,'Have you been to the Forgotten Pools, $n? Did you find anything?',0),
	 (869,0,0,'Do you have those heads, $N?',12340),
	 (868,1,1,'Be careful with the eggs you find, $N. If they break, they be no good to me.',12340),
	 (867,0,0,'Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons.',12340),
	 (866,1,0,'Hello, $N. Did you get those root samples?',12340),
	 (865,0,0,'Did you get the horns, $N? Those things are going to make me a fortune!',12340),
	 (864,1,0,'Welcome back. At least, welcome back if you have returned with a sealed testing kit. Otherwise, I will pretend not to notice your utter incompetence and spare my wrath from you until you do as you have been tasked and accomplish my task.',12340),
	 (863,1,0,'Can I help you?',12340),
	 (862,6,0,'Whack enough dig rats yet, $n?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (861,3,3,'Greetings. There is an air about you that tells me much. Do we have business, you and I?',12340),
	 (860,1,0,NULL,12340),
	 (858,1,0,'Quick, we need to get out of here before someone gets suspicious!',12340),
	 (857,5,5,'Where is the Tear of the Moons? I need it now! Need I say!',12340),
	 (854,1,0,NULL,12340),
	 (855,0,0,'How goes your hunting, $N?',12340),
	 (853,0,0,'You have something from Apothecary Helbrim?',12340),
	 (851,0,0,'Did you find Verog, $N?',12340),
	 (852,0,0,'Is Hezrul defeated, $N?',12340),
	 (850,0,0,'Hello, $N. Do you have Barak''s Head for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (849,1,0,'Once the dwarven flying machine has been destroyed I will feel the sweet satisfaction of revenge.',12340),
	 (847,1,0,NULL,12340),
	 (848,0,0,'Do you have the spores, $N? There is a concoction I must send to my associate in Thunder Bluff, which requires the spores...',12340),
	 (846,1,1,'I see you are back, $N.$B$BWhile Khazgorm''s death might delay the digging in my ancestral lands some, it will by no means bring a total end to the destruction.$B$BThe Keep at Bael Modan is an increasing military threat. Built to defend the dig site, it is now poised for offensive force as well.$B$BIf you have the ingredients I requested, I can fashion a charge that will make the hasty dwarves reconsider their actions here in the Barrens.',12340),
	 (845,0,0,'How many zhevra have you slain?',12340),
	 (844,6,6,'Have you collected the plainstrider beaks?',12340),
	 (843,5,5,'Many innocent tauren lost their lives or were forced off their ancestral birthplace when the dwarves of Bael Modan arrived. My land must be reclaimed!',12340),
	 (842,0,0,'Well well well, what do we have here? Has Kargal deemed me worthy of another recruit?',12340),
	 (841,1,0,'Well, have you got the ten water pouches?',12340),
	 (840,15,0,'What do you want, pup? If you''re not here for recruitment, I don''t have time for you.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (838,1,0,NULL,12340),
	 (837,1,0,'Though they do possess some intelligence and some organization, I find it constantly amazing that the quilboars were able to capture and hold so much territory in Kalimdor. Perhaps they are more crafty an enemy than I give them credit for...',12340),
	 (836,1,0,NULL,12340),
	 (835,1,0,'You wouldn''t think it from a guy like my boss Gazlowe, but he always seemed to know the score. "Don''t be afraid to take that big step," he said.$B$BHarpies won''t stop bothering us and the caravans won''t stop being attacked unless we do something about it, eh?',12340),
	 (834,0,0,'I''m great at what I do, don''t get me wrong, but this is ridiculous! What am I supposed to do, build sand castles?',12340),
	 (833,5,5,'The Bristleback Interlopers must be driven away from our sacred burial ground, $n.',12340),
	 (832,2,0,'You have something vital to report. I can sense it behind your eyes.',12340),
	 (831,6,6,'Can you not see that I am busy? This had better be pressing....',12340),
	 (830,6,6,'There is a look of concern on your face, $c. What have you there?',12340),
	 (828,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (829,2,2,'My most humble greetings, $c.  How might I help my $r $gbrother:sister; today?',12340),
	 (827,1,0,'Have you yet entered Skull Rock, $N? Do you have the Searing Collars?',12340),
	 (826,0,0,'Is Zalazane defeated, $N?',12340),
	 (825,1,1,'Once we learn how the humans operate their strange machinery, we will stand a greater chance of defeating them in future battles.$b$bWith our new gained knowledge, the Horde only stands to grow in strength.',12340),
	 (823,1,0,NULL,12340),
	 (824,1,0,'Ah, hello there. I spend a great deal of time studying the water - all the elements really - so much so that sometimes I don''t even notice people around me.$b$bIs there something I can help you with?',12340),
	 (821,0,0,'How''s the search going?',12340),
	 (822,6,6,'You working hard at finding those ingredients, $N?',12340),
	 (819,0,0,'Yes?',12340),
	 (818,1,1,'Time is the true test of your strength and will. Lose patience or give in to weakness, and your true self will be shown.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (817,1,1,'I remember my first tiger hunt, $N. I chose to hunt on the largest of the Echo Isles, and I sat perfectly still in the shadows of its foliage for almost a full day... watching... waiting.$b$bMy muscles were taut, and I was ready to strike. It was one of my greatest victories when that tiger finally took the bait.',12340),
	 (816,1,1,'I pray that Kron will return to me, but I''m almost certain I know his fate already.',12340),
	 (815,1,1,'Breakfast, lunch, dinner! Who cares which meal it is? It still has to be cooked by someone--namely me!',12340),
	 (813,1,1,'Remember, no matter what creature you hunt, you would do well to study it and understand its behavior. That knowledge could save your life.',12340),
	 (809,1,0,NULL,12340),
	 (812,1,1,'I''m almost glad I can''t return to Sen''jin as I am now. My weakness and stupidity would surely be mocked.',12340),
	 (808,0,0,'Do you have my brother''s skull, $N? Is he finally free?',12340),
	 (806,0,0,'Did you find Fizzle, $N? He, and rest of the Burning Blade, must be scoured from our lands!',12340),
	 (804,1,0,NULL,12340),
	 (805,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (795,1,0,'The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.',12340),
	 (794,0,0,'Is your task complete, $N? Do you have the Burning Blade Medallion?',12340),
	 (793,0,0,'There are few enemies more deadly than dragonkind, and there were few dragons that fought as ferociously as Blacklash and Hematus.',12340),
	 (792,1,1,'To prove yourself against the Burning Blade, you must first defeat its Vile Familiars. Return to me when you have done this.',12340),
	 (791,1,1,'I fought proudly alongside the Warchief when these lands were pioneered. The scars of battle mark my skin.$b$bThe honor of the Horde has been upheld with the help of my axe and battlecry during the defeat of Archimonde, when the unholy alliance was made with the humans and elves, wrought from necessity.$b$bBut my position as watchman and provider has given me a new sense of worth.',12340),
	 (790,16,0,'Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I''m afraid it looks like he was right.$b$bAt least I wish to die knowing that my last enemy in life lays dead.',12340),
	 (789,1,0,'The carapace of a scorpid isn''t so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.',12340),
	 (788,0,0,'I hope you haven''t returned to try and convince me that you have completed your task, $N? No, of course not. I would think better of you.',12340),
	 (787,1,0,NULL,12340),
	 (786,5,5,'The centaurs have proven to be a consistent nuisance to the Horde. Their intentions to lay siege to our homeland cannot be tolerated.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (782,0,0,'Tho''grun''s betrayal... is there any wonder why the ogres are part of the Horde no longer? I will be glad to see him dead, and the Sign of the Earth returned.$B$BIf you''ve not dispatched him yet, then waste no time going to Camp Boff.  It is to the southeast of Kargath.',12340),
	 (783,1,0,NULL,12340),
	 (784,1,25,'You have your orders, $N. The safety of Durotar is in question. Complete the task before you or hang your head in shame.$B$BShow your honor and defeat the humans of Tiragarde Keep.',12340),
	 (781,6,6,'You have a look of concern about you, $N. What news do you bring?',12340),
	 (780,0,0,'The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?',12340),
	 (779,1,0,'The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.',12340),
	 (778,6,6,'Not quite the outcome I was expecting. Could you get my shackles back?',12340),
	 (777,0,0,'<Without looking up from the shackles, Lotwil holds out a hand and waggles his fingers impatiently.>$B$BThe cog, $N, the cog!',12340),
	 (776,6,6,'Have you tracked down Arra''chea yet?',12340),
	 (775,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (773,1,0,NULL,12340),
	 (772,1,0,NULL,12340),
	 (771,1,1,'Once you have gathered enough well stones from around the water wells and Ambercorn from beneath the trees, I will prepare the Water of the Seers for you.',12340),
	 (770,1,0,NULL,12340),
	 (769,6,6,'Do you have my supplies, $N?',12340),
	 (768,3,3,'Hello again. Have you been hunting? Do you have skins for me?',12340),
	 (767,1,0,NULL,12340),
	 (766,1,1,'My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn''t be able to handle a beast my grandfather was unable to defeat...$b$bDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.',12340),
	 (765,0,0,'I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.',12340),
	 (763,6,6,'What brings you to my village, $c?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (764,1,0,'The Venture Co. was refused mining rights here in Mulgore, but it would seem that they do not take no for an answer. We tauren are not ones to mince words, however, and we have other ways of getting our message across.',12340),
	 (762,1,1,'Time is of the essence, $N. Ragnaros will not wait for us to prepare.',12340),
	 (760,1,0,NULL,12340),
	 (761,0,0,'Have you found the swoops, $N.  Do you have their quills?',12340),
	 (759,0,0,'$N. Do you have the teeth I asked for?',12340),
	 (758,1,0,NULL,12340),
	 (757,6,6,'Have you completed the Rite of Strength, $N? I require proof of your valor against the enemy of our tribe, the Bristlebacks.',12340),
	 (756,0,0,'$N, do you have the claws I sent you to gather? The Thunderhorn Water Well grows more tainted with each passing hour!',12340),
	 (755,1,0,NULL,12340),
	 (754,1,0,'Do not delay, $n. The Winterhoof Well''s taint must be removed!',0);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (752,1,0,NULL,12340),
	 (753,6,6,'You look as though you have returned from the plains. Do you have any word from Greatmother Hawkwind?',12340),
	 (751,0,0,'Hail, $N. Have you learned anything new about the Venture Co.''s plans and operations in our homeland?$b$bIf they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.',12340),
	 (749,1,0,NULL,12340),
	 (750,1,1,'If you can provide pelts for the tribe I will pass word along to my father, Chief Hawkwind, of your generous deeds.',12340),
	 (748,6,6,'Do you have the paws and talons, $N?',12340),
	 (747,1,1,'Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.',12340),
	 (746,0,0,'Hello, $N.  Do you have the Broken Tools?  The dwarves'' digging will enrage the kodos of Mulgore.  This defilement must be stopped!',12340),
	 (745,1,0,'If the Palemanes had respected the land and its inhabitants more, this conflict would have never occurred.',12340),
	 (744,0,0,'This headdress will certainly be a wonderful gift for my brother.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (743,1,1,'The Windfuries are deadly foes. Their strength in battle is only rivaled by their desire for fresh meat.',12340),
	 (741,1,0,'What can I do for you, $R?',12340),
	 (742,1,0,NULL,12340),
	 (739,1,0,'Do you have news of Agmond''s fate? Did you find him?',12340),
	 (738,1,0,NULL,12340),
	 (737,6,6,'Ho! You were gone a long time. Did you get the digest?',12340),
	 (736,6,6,'How goes your mission, $c.',12340),
	 (735,6,6,'Do you have the relics for which I asked?',12340),
	 (734,1,0,NULL,12340),
	 (733,6,6,'Well, I''ve made do with what I could, but... it''s not much. Have you found any more supplies?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (731,1,0,'Is the prospector alive?',12340),
	 (732,1,1,'The nomadic band of ogres travels between their camps across the Badlands; heat rising from the dry earth and the swirling winds will make it difficult to track their progress. I have heard that sometimes they travel through Camp Boff. If you are lost, you might try your search there.',12340),
	 (729,1,0,'',12340),
	 (730,1,0,'',12340),
	 (728,6,6,'Ah, we have an eager $C, I see. Are you here to learn from my collection? Good!$B$BBut be warned: just as knowledge gives power to the strong...it will drive the weak mad.',12340),
	 (727,3,3,'Hello. Welcome to my shop, but watch what you touch.$B$BKnowledge can be deadly.',12340),
	 (726,1,0,NULL,12340),
	 (725,6,6,'Hmm? Yes, $C.',12340),
	 (724,1,0,'Ah, yes. Another traveler seeking something from the dwarves.$B$B$G Sir : Ma''am;, I''m truly sorry, but I''ve no time to answer meaningless questions right now.',12340),
	 (723,1,0,'I''d say it was a bad day, but this is the Badlands: every day''s a bad day.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (722,1,1,'The Shadowforge clan... is dangerous. Be careful. You must find the amulet.',12340),
	 (721,1,0,NULL,12340),
	 (720,1,0,NULL,12340),
	 (719,1,1,'Not sure what the Shadowforge were lookin'' for, but they definitely had a purpose.',12340),
	 (718,1,1,'The desert''s a bad place to be hungry, my friend, let me tell you that.$B$BHey... what''s that over there...',12340),
	 (717,1,1,'Strong magics and powers held the drakes'' prison for so long, but we cannot allow any possibility that Blacklash and Hematus may be released.',12340),
	 (716,6,6,'I wouldn''t wait too long to get that bracer, $N.$b$bWho knows what''s going to happen next?',12340),
	 (715,6,6,'He''s getting closer to finishing. How are things going on your end?',12340),
	 (714,0,0,'Yes, yes, yes. Just a moment.',12340),
	 (713,6,6,'Have you found the oil I need? It would be so helpful if you were able to find some.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (712,1,1,'The stone slabs you found were ideal, $N. Lucien will be taking the extra ones back to Kharanos when we''re done here. After all, they could prove useful again.$B$BFor instance, they''d be a nice basis for a handy little shelter once I start looking into a multidisciplinary approach to high-yield explosives...',12340),
	 (711,0,0,'I''m most pleased, $N. My spells affected the smaller pieces just as I predicted. If this experiment is as successful as I foresee, then the elementals I''ll be able to control will put anything summoned prior to this to shame.',12340),
	 (709,5,5,'Did you find the tablet? It must hold secrets! Secrets to save us!',12340),
	 (710,6,6,'This area''s perfect for-- Could you hold these in place for a moment? Yes, just like that, along the vector normal. Now, what was I... Right. Perfect for testing my latest project. The raw materials, the open space... what more could an intelligent and enlightened practitioner of the arts ask for?',12340),
	 (707,1,0,NULL,12340),
	 (708,1,0,NULL,12340),
	 (705,6,6,'Did you get my pearls?  I''m almost out of flash bombs!',12340),
	 (706,6,6,'How goes the hunt, $C?',12340),
	 (704,6,6,'Did you find those urns, $N? We must find the link between them and the troggs!',12340),
	 (703,0,0,'Hello, $N. Did you bring me my wings?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (700,1,0,NULL,12340),
	 (701,0,0,'My preparations are made, all I require are the raptor hearts.',12340),
	 (702,0,0,'Returned again have you? Indeed there is nothing more I could wish for now than more of Tor''gan''s pity.$B$BWhat have you for me this time? Perhaps a piece of brightly colored string? Or a length of rope to end this misery of mine...',12340),
	 (699,0,0,'Good mead, a warm fire, an army of orcs and an arsenal of weapons... that''s all we really need out here along the coast. I don''t regret my position out here safeguarding Stonard, but it would be nice if we could one day get a burrow, or at least a tower.',12340),
	 (698,66,66,'Lok''tar, $C. Traveling through the swamps isn''t a risk taken lightly. You''re brave to test your mettle here.',12340),
	 (695,1,0,NULL,12340),
	 (696,1,1,'You do this, an'' I''m sure Malin''ll be more than pleased with you.',12340),
	 (697,6,6,'Yes? You look vaguely familiar. I do apologize, but have we met? I get so busy I lose track.',12340),
	 (694,6,6,'$N, hello again. Have you found an azure agate yet?',12340),
	 (693,1,1,'Our goal is the wand, $N. Focus on that for now.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (692,5,5,'Did you find those fragments?!?! You''ll need the Scroll of Myzrael if you want to trap her again, before it''s too late!',12340),
	 (690,5,5,NULL,12340),
	 (691,6,6,'Have you had any luck so far, $N?$B$B<Kryten makes some notes in his journal as he reads.>$B$BIf my research is correct, the tusks should come from any Witherbark troll. The medicine pouches come from the Witherbark witch doctors, and the strongest of the Witherbark shadow hunters should carry the special knife given to them after they''ve completed their rites of passage. There''s no way to tell which shadow hunters will have the knife until you do battle.',12340),
	 (689,5,5,'$N, $N, $N! Tell me you have enough Alterac Granite for me to begin my masterpiece in honor of Sully Balloo.',12340),
	 (688,1,0,NULL,12340),
	 (686,1,0,NULL,12340),
	 (687,1,0,NULL,12340),
	 (685,6,6,'Hello. Do you have a report to submit?',12340),
	 (684,6,6,'Greetings, $C. You have a report to make?',12340),
	 (683,6,0,'So you are $N the $C? News of your contributions to the Alliance has traveled quite far, you know?$B$BOn what business do you come before me today?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (682,0,0,'Have you retrieved any Stromgarde Badges, $N? The Syndicate must learn they cannot profit from our dead.',12340),
	 (681,1,0,'$N, with each passing hour our hold on Stromgarde grows more tenuous. You must make haste or our city will surely fall.',12340),
	 (680,0,0,'Near the Tower of Arathor--that is where you will find Or''Kalar. His death will stop the attacks on Hammerfall and protect my husband''s life.$B$BI see in your eyes that you think me weak--even dishonorable--for my silence. Some day you will learn what it is to love as I do. Perhaps then you will understand a different kind of strength and honor.$B$BIn the meantime, do as I ask, and slay Or''Kalar.',12340),
	 (679,1,0,'I see your courage finally wanes. It seems my instincts were correct about you: your strength is nothing compared to your bravado.$b$bReturn to me when the beast''s head has been severed, or return never again.',12340),
	 (678,1,6,'You hesitate. Why? You have shown great strength thus far, $N. Do not fail me now.',12340),
	 (677,1,25,'If you have not yet completed my task, then perhaps you are a coward in heart as well as a tyro in war.',12340),
	 (676,1,5,'I have not the time to sharpen my axe, let alone leave the outpost to slay those beasts that would try and slay my kin.$B$BYou do not seem to have the experience of a grunt let alone a full-fledged warrior, what do you want, $N?',12340),
	 (675,1,0,NULL,12340),
	 (674,0,0,'What hope is there when the hand of a coward can slay the mightiest of the mightiest? What hope, I ask you!',12340),
	 (673,0,0,'The burning in my blood... it grows by the day. The warlock must be stopped.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (672,0,0,'I will create an amulet that will give Gor''mul some of the strength of the raptors. Perhaps that will awaken some flame within him...',12340),
	 (670,1,0,'So was Seahorn impressed? I bet you his smile reached from Booty Bay to Ratchet.',12340),
	 (671,0,0,'Once-cursed blood still runs through my veins, $N. If someone... something is summoning demons, it must be stopped.',12340),
	 (669,6,0,'What brings you to Booty Bay, $C?',12340),
	 (668,0,0,'Ahoy, $C. What brings you to the bridge?',12340),
	 (667,1,0,NULL,12340),
	 (666,6,6,'How did the goggles work? Did everything function properly? Adjustments can be made if necessary.$b$bOh, and I''ll need those goggles back when you''re done. I am sure Captain O''Breen will have many uses for them later on.',12340),
	 (665,1,0,'This is no time to talk! The goggles need to be charged with the power of the stone!',12340),
	 (663,1,0,NULL,12340),
	 (664,1,0,'Bah, maybe I should go kill those naga scum myself. It''s obvious you''re not goin'' to do it.$B$BMaybe I can find some knitting needles so you can keep yourself busy.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (659,1,0,NULL,12340),
	 (660,1,0,NULL,12340),
	 (661,1,0,NULL,12340),
	 (662,0,0,'How goes the search and recovery mission, $n?  We really need to get those Logs and Charts back from the Maiden''s Folly and Spirit of Silverpine.$b$bIf the information from those sources were to fall into enemy hands, Fleet Master Seahorn would force us down the plank.$b$bThat is if we ever get out of this mess...',12340),
	 (658,1,1,'We appreciate your help in looking for that courier, $N.$B$BWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I''m confident that they''re up to no good--I just need proof of it before we go off and do something rash.$B$BHave you had any luck yet?',12340),
	 (657,1,0,NULL,12340),
	 (656,1,0,'The Shards of Myzrael are now strangely quiet.',12340),
	 (655,1,0,NULL,12340),
	 (653,1,0,NULL,12340),
	 (654,5,5,'Well, did you get everything you needed? If you didn''t and the power runs out, everything inside will be ruined and you''ll have to start over.$B$BHey, don''t look to me for sympathy; I''m all about the Gadgetzan Water Company making a profit, and if that means selling you power sources until we can afford to import water in from the icy springs of Dun Morogh, so be it!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (652,1,0,'The Keystone is charged with tremendous geomantic energy.',12340),
	 (651,1,0,'This is the Stone of Inner Binding. It is the strongest of the binding stones and must be unlocked for the others to open.',12340),
	 (649,1,0,NULL,12340),
	 (650,1,0,NULL,12340),
	 (647,6,6,'What''s the good word, $R?',12340),
	 (648,1,0,NULL,12340),
	 (646,6,6,'$N! Have you taken the sword?',12340),
	 (644,6,6,'You''ve returned, $N. Is the line of Ignaeus Trollbane broken?',12340),
	 (645,1,0,'Etchings in the stone upon the face of the tomb of Trollbane match the glowing lines of the Sigil of Ignaeus...',12340),
	 (643,0,0,'Valorcall will not be easy to track down, $N. Mounted on horseback, he can cover ground quickly. Nonetheless, we must have his sigil.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (642,0,0,'This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.',12340),
	 (641,6,0,'$N! Do you have the second sigil?',12340),
	 (640,66,66,'Throm''ka, $c. Zengu informed me that you required my assistance?',12340),
	 (638,1,0,NULL,12340),
	 (639,6,6,'Have you located the first sigil yet? It is most likely carried on the person of one of the Syndicate agents in Stromgarde.',12340),
	 (637,1,0,'You look as though you have traveled a great distance and seen much turmoil in your time, $C. These times we live in are trying on the soul. What news do you bring to me now?',12340),
	 (635,1,0,NULL,12340),
	 (636,1,0,NULL,12340),
	 (634,1,0,NULL,12340),
	 (633,1,5,'The cache of explosives must be destroyed!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (631,1,0,NULL,12340),
	 (632,6,0,'Any sign of Ol'' Rustlocke, $N?',12340),
	 (629,0,0,'I await the Tablet Shard, $N.',12340),
	 (630,0,0,'I thank my ancestors someone has come to aid me. Do you have the key that will free me?',12340),
	 (628,1,0,'I read somewhere that the saltwater crocilisks are slowly dying out... bad news for my business, isn''t it?$b$bAnyways, I hope you have that elder saltwater crocolisk skin for me!',12340),
	 (627,1,0,'Hello, $N. Did you have luck getting the bloodstone?',12340),
	 (626,1,0,'',12340),
	 (624,1,0,'',12340),
	 (625,1,0,'',12340),
	 (623,1,0,'Yeah?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (622,1,0,'Hello, $N. Did you make it to Booty Bay? Did the goblin Krazek fix my pot??',12340),
	 (620,1,0,NULL,12340),
	 (621,0,0,'Do you have the samples of Zanzil''s Mixture??',12340),
	 (619,1,0,'This is an abandoned lifeboat.  Printed along its side in scratched, faded paint are the words:$B$B"Smotts'' Revenge"',12340),
	 (618,1,0,'Did you get my cutlass, $N?',12340),
	 (617,0,0,'If ya got no business with me, then move along, $N.',12340),
	 (615,1,0,NULL,12340),
	 (616,1,0,NULL,12340),
	 (614,3,3,'Ahoy, $N! Did you find Gorlash? That chest was my favorite, and it has a hidden compartment that held my greatest treasures!',12340),
	 (613,6,6,'Ahoy, $N! Have you yet found Maury''s Key?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (611,1,0,'Have you retrieved the Stone of the Tides for me, $N? I''ve already cleared out a space and purchased a fine stand for it.',12340),
	 (610,1,0,'I''d never been beat before, you know, $N? Sure I''d been cut, can''t get in a knife fight without that, but he just smacked me on the side of the head, blacked me out. When I came to my blade was gone.$B$BAs much as my nickname might indicate, I still need a knife to fight, and for me, it has to be that one.',12340),
	 (609,0,0,'$N, did you find those three dogs? Did you collect their valuables?',12340),
	 (608,1,0,'What''s the problem, $N? We need to attack before the Bloodsail Buccaneers do!',12340),
	 (607,0,0,'Here here, $N.  Did you get Shaky''s payment?',12340),
	 (606,25,25,'Hey!  I don''t like the look you''re giving me, $gmister:lady;.',12340),
	 (605,0,0,'Do you have those shards yet?  I''ll give you a decent cut from the profits!',12340),
	 (603,1,0,NULL,12340),
	 (604,6,6,'Ahoy, $n.  What word do you bring of the Bloodsail encampment to the south?',12340),
	 (602,1,0,'If you wouldn''t mind, I am rather busy right now.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (601,1,0,'Have you had any luck, $N?',12340),
	 (599,1,0,NULL,12340),
	 (600,0,0,'Do you have those crystals?? I need them!!$b$bI mean...I need to know the evil Venture Company is losing ground in Stranglethorn. Because, you know, we honest folk have to make a living!',12340),
	 (598,0,0,'The Skullsplitters will curse the day they brought us to war! Is your task complete?',12340),
	 (597,1,0,NULL,12340),
	 (595,1,0,NULL,12340),
	 (596,0,0,'The Bloodscalps will one day be crushed by the Darkspears! Do you have the necklaces of our doomed foe?',12340),
	 (594,1,0,NULL,12340),
	 (593,1,0,'Yenniku stands stunned before you, his mind in another place...',12340),
	 (592,1,0,'$N. Kin''weelay told me you set out to capture Yenniku.$b$bIs it true? Do you have him?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (591,1,0,'Greetings, $N. The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai''Zoth.$b$bDo you have the Eye?',12340),
	 (590,1,0,NULL,12340),
	 (588,1,0,NULL,12340),
	 (589,1,0,'Do you have the shards, $N? They are needed for my final ritual, after we have the Mind''s Eye.',12340),
	 (587,6,6,'Any luck finding the goods, matey?',12340),
	 (585,0,0,'I await the skulls...',12340),
	 (586,1,0,'Although my own flesh boils off my skull, I can still smell your fear.$B$BHah!  You will never complete my task...',12340),
	 (583,1,0,NULL,12340),
	 (584,1,0,'The greenish broth within the cauldron bubbles.',12340),
	 (582,1,0,'$N. I fear for our chief''s son. Do you have the shrunken heads so I may inspect them?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (581,0,0,'$C. Show me you have made prey of the Bloodscalp tribe.$b$bShow me your trophies.',12340),
	 (580,5,5,'Sink me!  I''m almost outta booze here!  Cap''n is goin'' to weigh anchor and Ol'' Slim will be caught dry as the Tanaris Desert.  And once he discovers his port is missing. . . blimey!',12340),
	 (579,1,1,'King Varian has placed great importance on learning, and thus has provided funds for making copies of various tomes and writings available to the public. It''s very simple. You bring me a library scrip, and I can give you a copy of one of the available books.',12340),
	 (578,1,0,'The trolls truly possessed some amazing magical objects, $N. And now, perhaps, I have the opportunity to add one to my extensive collection. Did you have any luck finding the source of the rumor?',12340),
	 (577,1,0,'Drizzlik''s Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocilisk skin boots. None finer!$b$bCan''t beat a glowing description like that, can you?$b$bExcept, maybe, if you have those skins for me?',12340),
	 (576,3,3,'Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.$b$bCould really use me eye back.  Captain''s going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.$b$bWhat good is a lookout who can''t see?  The crow''s nest used to be me home...without me deadlights I''d be lucky to scrub the bilge.',12340),
	 (575,0,0,'My equipment is all ready to go, $n, I just need those skins. We don''t want to keep Riddlevox waiting, that''s for sure.$b$bIt''s not a good idea for anyone to keep the chief inventor of the Tinkers'' Union unsatisfied.',12340),
	 (574,1,0,'Sergeant Yohwa tells me you are skilled and brave, $C. Do you have something to report?',12340),
	 (572,6,6,'Did your gathering efforts prove fruitful?',12340),
	 (573,6,6,'I am almost ready to complete the enchantment. Have you performed my bidding?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (570,6,6,'What news do you bring?',12340),
	 (571,6,6,'Has fortune been on your side, $N? Were you able to obtain an aged gorilla sinew?',12340),
	 (569,1,6,'Have you made any progress with the ogres of the Mizjah Ruins yet, $C?',12340),
	 (568,1,0,'Our supply efforts are still being hampered by the indigenous raptor population, $c.',12340),
	 (567,1,0,'Yes?',12340),
	 (566,6,6,'Ah, $N. Perhaps you''ve come to collect the bounty on the head of Baron Vardus?',12340),
	 (565,94,94,'So you have returned to the great Bartolo. Perhaps you have finished gathering the materials needed for your Yeti Fur Cloak? Or maybe you just enjoy basking in the greatness of me, Bartolo!',12340),
	 (564,1,5,'Mountain Lions killin'' off our horses left and right and here you are wantin'' to jibber-jabber about the weather and what not.$B$BOught to go and find myself a real hero. More killin'' and less talkin''.',12340),
	 (563,1,0,'Greetings, citizen. May the Stormwind city guard be of assistance?',12340),
	 (562,0,0,'I''ve a letter ready to go to Major Samuelson in Stormwind. All I need are the results.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (561,1,0,NULL,12340),
	 (560,0,0,'Greetings, citizen. Have you come to lend your arm to upholding the safety of Southshore?',12340),
	 (559,0,0,'Did you get those heads for me, $N?',12340),
	 (558,0,0,'Someday, I wanna be a hero just like Jaina... well, a boy hero that is.',12340),
	 (557,0,0,'Hello, $N. Elementals are tough quarry, but I know you''re up to the task. Do you have those bracers of binding?',12340),
	 (556,0,0,'Do you have the Worn Stone Tokens, $N?  The Magus is eager to unlock their secrets.',12340),
	 (555,6,6,'Any luck finding the ingredients? I''ll tell you, this territory isn''t the peaceful place it once was. Ah, if only this unrest never occurred...',12340),
	 (554,6,0,'More interruptions?$B$BAh, this parchment is covered with a very intricate, finely woven spell. I can untangle it, of course, but it''s going to take time. And time is very valuable to me...$B$BPerhaps I will just purchase it from you?',12340),
	 (553,1,0,'Helcular''s grave teems with a mystical energy.',12340),
	 (552,6,6,'Have you recovered Helcular''s Rod yet? There are so many Yeti in this region, it will be very difficult to locate. But we must have it in order to proceed.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (551,6,0,'Oh. You have something you''d like me to look at? Some scrap of lore gathered from up in the mountains, I hope...',12340),
	 (549,1,0,'Do you have nothing better to do than stand here before me, $c? As High Executor, I have more pressing matters than to stare at your rotting visage.',12340),
	 (550,1,0,'What brings a $C all the way to the Undercity from the battlefield?',12340),
	 (547,6,6,'Were you able to retrieve my sword, $N? High Executor Darthalia will hang me from the rafters if she discovers my folly.',12340),
	 (546,6,6,'So the lucky $N returns? How many humans have you slaughtered today? Hundreds I do hope!$b$bHave you any skulls for me?',12340),
	 (545,1,0,'Have you yet thinned the Dalaran patrols around their ruins?',12340),
	 (544,0,0,'Did you find the thieves?  And more importantly, did you find what they stole?',12340),
	 (543,1,1,'Salutations, $N. Do try to avoid stepping on my pant cuffs. This outfit is newly tailored.',12340),
	 (542,6,6,'$N, you''ve returned! How did your foray into Alterac go? Did you bring anything back with you?',12340),
	 (541,1,0,'Dun Garok proves to be too much of an obstacle for you, $C? And here I thought you had established yourself valiantly in Hillsbrad.$B$BIf you''re not up to handle the mission assigned to you, I will find another who can produce better results. As for you, well, I am sure the Dark Lady could always use more grave diggers back in Tirisfal Glades.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (540,6,6,'I wish I could search the ruins too, but I fear these bones wouldn''t hold me during my climb up the mountains. However, how does your hunt for knowledge progress, $N?',12340),
	 (538,1,0,NULL,12340),
	 (539,1,0,'You were given direct orders to attack the Azureload Mine. Your reasons for loafing about Tarren Mill better be good or I will behead you for treason.',12340),
	 (537,0,0,'Did you find the envoys of The Argus Wake?',12340),
	 (536,1,0,'Another ale, please, the last one just seemed to have disappeared!$B$BLight, how much longer am I going to be stuck out here?$B$BOh, it''s you, $N. Have you killed those murlocs yet?',12340),
	 (535,1,0,'Did you bring me something to drink or did you just come back to finish the job?',12340),
	 (532,6,6,'What news have you?',12340),
	 (533,6,6,'Have you found anything? I fear Gol''dir''s prospects grow worse by the day...',12340),
	 (531,11,0,'Great job, $N! We really showed him! Here, give me the head and I''ll take care of it.',12340),
	 (530,6,6,'Do you have those hands, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (529,6,6,'Were you able to carry out your orders, $C? Did you dispose of Verringtan and his assistants? And where is that iron shipment?',12340),
	 (528,1,0,'You have your orders, $c. Quit dawdling here in Tarren Mill when there is work to be done elsewhere.',12340),
	 (527,1,0,'As High Executor of Tarren Mill, under the direct command of Varimathras and the Dark Lady, you are subject to follow my command.$B$BPerhaps you take this war with the Alliance lightly? If such is the case I should behead you right here and now. Otherwise, travel west to the town of Hillsbrad and wage battle against the humans, as ordered.$B$BDismissed.',12340),
	 (526,1,0,'Did you find the lightforge iron you need?',12340),
	 (525,0,0,'$N. Have you been traveling through the foothills and mountains again? What news do you bring?',12340),
	 (524,1,0,'A musty smell emanates from the rug.',12340),
	 (523,0,0,'Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity. I want his head!',12340),
	 (522,0,0,'You look out of breath! Do you have something to report?',12340),
	 (520,1,0,'Three heads I have, a fourth I need. It will be Mug''Thol''s, or it will be yours, $N. That I promise.',12340),
	 (521,1,0,'Yes? Do you have something to report?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (519,1,0,'I want their heads, $N, not excuses.',12340),
	 (518,1,0,'I note that your task is unfinished, $N. Shall I inform Sharlindra of your ineptitude?',12340),
	 (517,1,1,'Sometimes I get so bored out here in Tarren Mill I like to open up the formaldehyde jar and let the lovely aroma waft through the air. Makes Umpi a little nervous though.$b$bSo were you able to get a keg from the Dwarves? I swear if I have to stare at this deadly elixir without using on it someone for another day I am going to scream.',12340),
	 (516,1,0,'Have you located their base yet, $n? Time is of the essence!',12340),
	 (515,1,1,'So glad to see you back, $N. I was growing so terribly bored here. Not a single entertaining thing to do besides poison and disease Umpi and reanimate her. . .over and over and over again.$b$bHow went the trip to the Undercity? Were you fortunate enough to slaughter any humans along the way?',12340),
	 (514,6,0,'Dibbs from Southshore sent you, did he? How is the old bookworm doing?',12340),
	 (513,5,0,'Can you not see I am busy, $C? The Dark Lady insists on a new plague before the Scourge advance from Northrend overwhelms us. And with the human threat pressing from the south, time becomes my most precious commodity. This better be important!',12340),
	 (512,0,0,'Have you been hunting the Syndicate? Do you have those rings?',12340),
	 (511,6,0,'Yes, $N? Do you have some business with me?',12340),
	 (508,6,0,'You''ve returned, $N. Success to report?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (509,6,6,'Any luck at Nethander Stead?',12340),
	 (510,0,0,'$N, you look anxious. Is there something you wish to tell me?',12340),
	 (507,1,0,'W-what do you want?',12340),
	 (506,1,0,NULL,12340),
	 (505,1,0,'You have slain those Syndicate thugs, I trust?',12340),
	 (504,1,0,'You have more Warmongers to slay, $N. You should be up on the mountains on your task, not down here with your weapon stowed.',12340),
	 (503,0,0,'Give me the key, $C, I will undo the lock myself.',12340),
	 (502,1,0,'Woof?',12340),
	 (501,1,1,'I remember you, $N. You were going to help me out in concocting my latest elixir. I''ll need that blood before I can bring my own special brand of misery to the inhabitants of Hillsbrad.',12340),
	 (499,1,0,'Ribbit!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (500,0,0,'$N, are you still hunting ogres? Do you have the knucklebones I had you gather?',12340),
	 (498,1,0,'You must make haste, $C. I shudder to think what the humans might be doing to Drull and Tog''thar.',12340),
	 (496,1,1,'I see you are back. I hope you were able to gather the agents I need. Another deathless day will put me in such a gloomy mood.',12340),
	 (495,1,0,NULL,12340),
	 (493,6,0,'You have something for me?',12340),
	 (494,1,0,NULL,12340),
	 (492,14,0,'Why if I had my trusted rifle you''d be as good as dead, $C.  Just wait until the Steam Tank Brigade arrives to rescue me!',12340),
	 (489,4,0,'What do you have for me, $N? A lovely snack I presume?',12340),
	 (491,0,0,'$N. Have you defeated Thule Ravenclaw?',12340),
	 (488,0,0,'Have you been a busy little bee, $N? I''ve been waiting for you to bring me what I need.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (487,1,5,'The road is still not safe, $c. Travel forth and slay 6 Gnarlpine Ambushers and return to me.',12340),
	 (486,1,0,'Our brethren cannot be awakened until Ursal the Mauler has been slain, $N.',12340),
	 (485,1,0,'You appear to have uncovered the wreckage of... a robotic chicken? The voice from within the egg crackles to life again:$b$b"Yes, excellent work! This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs. Go ahead and place the beacon inside the rover - the beacon will take care of the rest!"',12340),
	 (484,6,6,'$N, right? Do you have my skins?',12340),
	 (483,1,0,'$N, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban''ethil Barrow Den to the west.$b$bFor every minute we delay their fate comes one step closer to eternal doom.',12340),
	 (482,1,0,NULL,12340),
	 (481,0,0,'Yes, $C? What is it?',12340),
	 (479,0,0,'We must hurry, their plans must not come to fruition, or we may lose our hold on Silverpine Forest.',12340),
	 (480,0,0,'Quickly, time runs short, $N!',12340),
	 (477,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (478,0,0,'Have you learned anything useful, $N?',12340),
	 (476,0,5,NULL,12340),
	 (474,0,0,'Have you killed Nek''rosh?',12340),
	 (473,1,0,NULL,12340),
	 (472,1,0,NULL,12340),
	 (471,18,18,'My apprentice is like a son to me. It''s going to be hard for him to live his life with only one leg.$b$bAh, $N, how goes it? Do you have my skins?',12340),
	 (470,0,0,'Did you find my bag?',12340),
	 (469,1,0,'Hello there, $C. Could I interest you in a pair of boots? Perhaps some newly cured skins?',12340),
	 (466,0,0,'Where is that ore, $N?!',12340),
	 (467,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (468,1,0,NULL,12340),
	 (465,1,0,'The first catapult is before you. Will you set it aflame?',12340),
	 (463,1,0,NULL,12340),
	 (464,0,0,'Have you attacked the Dragonmaw encampment?',12340),
	 (461,1,0,'This is the spot! Bring me closer...',12340),
	 (460,1,0,'This grave was hastily dug.',12340),
	 (459,0,0,'Satisfy my suspicions, $N. Bring to me 8 Fel Moss.',12340),
	 (457,25,25,'Your task is not yet complete, $N. Return to me once 5 mangy nightsabers and 5 thistle boars have been killed.',0),
	 (456,1,1,'There is still work to be done, $N. Return to me once you have thinned the nightsaber and thistle boar populations.',12340),
	 (454,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (455,1,0,'You''re coming from Loch Modan? How is the orc situation at Algaz Gate?',12340),
	 (452,1,0,NULL,12340),
	 (453,5,0,'Who are you?? Leave me be!',12340),
	 (451,6,6,'What brings you back to the Undercity, $N?',12340),
	 (450,1,1,'I see you are back, $N.',12340),
	 (449,0,0,'Did you discover the fate of the Deathstalkers?',12340),
	 (448,1,0,NULL,12340),
	 (447,66,66,'Hail, $C. What business do you have with the Royal Apothecary Society?',12340),
	 (446,0,0,'Greetings, $N. What did Bethor have to say?',12340),
	 (444,0,0,'My studies require great concentration. So I hope your visit is not a frivolous one.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (445,6,0,'What business do you have with me, $C?',12340),
	 (443,0,0,'Do you have the rot hide ichor, $N?',12340),
	 (442,0,0,'The Scourge cannot be allowed to remain in Silverpine, $N. Come back to me when you have proof of Thule''s death.',12340),
	 (441,6,0,'Do I know you?',12340),
	 (440,0,0,'Hello, $N. What brings you back to Brill?',12340),
	 (439,0,0,'$N. You return, so I assume your investigations bore fruit?',12340),
	 (438,1,0,NULL,12340),
	 (437,0,0,'Have you defeated Nightlash, $N?  Our success against the rot hides depends on her destruction!',12340),
	 (435,1,0,NULL,12340),
	 (436,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (434,1,0,'Yes, $N? Are things going well with Tyrion? He apprised me of the situation and I''ve helped him trick Marzon into going to the castle.$B$BMarzon has been a thorn in the side of many people in Stormwind; many of which are close friends of mine. No one messes with my friends... not if they know what''s healthy for them.$B$BIt''s just a shame I''m indirectly doing a favor for Shaw and SI:7 in the meantime. Oh well, not every plan is perfect.',12340),
	 (433,1,0,'If we can remove the troggs from Gol''Bolar quarry, it will be the first step of many that we will have to undertake to rid ourselves of this menace.',12340),
	 (430,6,0,'My sister told me you were here to aid us. Is that true?',12340),
	 (431,1,0,NULL,12340),
	 (432,1,15,'It makes me so mad! Grrr...',12340),
	 (429,0,0,'My time is short, $c, for the Dark Lady has charged me with a grave task.',12340),
	 (428,1,0,NULL,12340),
	 (427,1,0,'If you wish to prove your worth to The Dark Lady, slay 10 Scarlet Warriors, $C.',12340),
	 (426,0,0,'Our battles with the Scourge wage on, $N. Do your part and throw those cursed, mindless undead back into the Plaguelands!',12340),
	 (425,0,0,'Have you killed Ivar the Foul? If you won''t do it for me and my brother, then do it for the Forsaken.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (424,6,6,'Has Grimson the Pale been slain? Varimathras will not be pleased if we ignore his bidding.',12340),
	 (423,0,0,'I will need 6 Glutton Shackles and 3 Darksoul Shackles before I can assess the situation and devise a final solution for Arugal. Now heed your bidding and slay Moonrage Gluttons and Moonrage Darksouls until you have what I need.',12340),
	 (422,1,1,'Before I know what we are dealing with here, $C, I need to study the spell known as Remedy of Arugal. Bring it to me now or I shall be forced to find myself a worthy servant.',12340),
	 (421,1,1,'If you wish to prove yourself to me, you must kill 5 Moonrage Whitescalps.  Accomplish that task, and I will see to it your skill is put to more worthy assignments.',12340),
	 (419,1,0,NULL,12340),
	 (420,1,0,'How are you? Like to share a drink with me, perhaps? Not much else to do in the cold.',12340),
	 (418,6,6,'I''m all ready to start cooking, do you have the ingredients for me?',12340),
	 (417,6,6,'Hello, $N. Do you have word of my friend Hildelve?',12340),
	 (415,1,0,NULL,12340),
	 (416,6,6,'Hail, $N. How goes the rat catching?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (414,2,0,'Greetings, $C, and welcome to Thelsamar!',12340),
	 (413,3,0,'Hello, $C!  And what business takes you all the way out here?$B$BSomething exciting, I hope.  I haven''t been in a good fight in days, and this barrel of ale is almost dry...',12340),
	 (412,0,0,'The Recombobulator will be up and running as soon as we have sufficient Restabilization Cogs and Gyromechanic Gears.',12340),
	 (410,1,0,'This is an old, beaten, bloody table.',12340),
	 (411,0,0,'Have you returned Gunther''s book? Has he responded?',12340),
	 (408,0,0,'Time is not a luxury we have, $N. With each passing hour, the Scourge''s hold on Tirisfal Glades grows more firm.',12340),
	 (409,1,0,'I await proof of your allegiance, $c.',12340),
	 (407,5,0,'Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your. . .$b$b. . .oh wait.  Is that food for me?  I am so hungry. . .',12340),
	 (405,0,0,'Greetings. Either you do not know who I am, or your business with me is urgent.$b$bBecause if neither of these were true, then you would not be foolish enough to disturb me...',12340),
	 (403,1,0,'',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (404,0,0,'Have you completed the task with which I have charged you?  Do you have those putrid claws?',12340),
	 (401,1,0,'',12340),
	 (400,0,0,'Hm?  You look a little young to be a siege engine pilot.  But no matter...do you need something fixed?$B$BWell take a number and get comfortable.  I''m working on a couple engines right now and won''t have time for another job for at least a few days.$B$BOr, were you here for something else...?',12340),
	 (399,6,6,'$N! Did you have any luck?',12340),
	 (398,6,0,'Yes?',12340),
	 (397,1,0,NULL,12340),
	 (396,6,6,'$N, yes? I was informed by Baros Alexston that you would be coming. I must say, I am most interested in what you have to say.',12340),
	 (394,1,0,NULL,12340),
	 (395,1,0,NULL,12340),
	 (393,6,6,'Greetings. Of what service can I be to you, $C?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (392,6,6,'Yes, $N? What have you found?',12340),
	 (391,6,6,'Either you bring me Thredd''s head, or I''ll take yours, understand, $N?',12340),
	 (389,1,0,NULL,12340),
	 (388,6,6,'I see you are back, $c.  Have you collected 10 Red Wool Bandanas from those Defias Scum in The Stockade yet?',12340),
	 (387,1,5,'The Stockade is still overrun! These Defias Rats must be shown that their actions will not be tolerated. Now get back down there and show some force!',12340),
	 (386,6,6,'Have you been to Stormwind yet, to The Stockade? I fear whatever trickery that has kept Targorr the Dread alive for this long will eventually bring about his freedom. He was sentenced to die, $N, not act as some political pawn on a noble''s whim.',12340),
	 (385,6,6,'Did I tell you about the time I almost lost my hand to one of the crocs? Nasty bugger it was, teeth like knives. But I was lucky... Jammed the brute''s jaw shut with my knife. Still have the knife around here somewhere...',12340),
	 (383,0,0,'Yes, what do you want?',12340),
	 (384,1,1,'I''m going to need six crag boar ribs and a mug of Rhapsody Malt, $N.',12340),
	 (382,6,0,'How goes your mission, $N?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (381,1,0,'Those fools... They happily send themselves to their own graves.',12340),
	 (380,1,0,'Be wary of the spiders'' venom, $N. If you feel a sharp burning, you may want to have it looked at.',12340),
	 (379,6,6,'Well, did the nomads ''volunteer'' up those water pouches for you?',12340),
	 (378,1,1,'I won''t let foolish Human bureaucracy interfere with Dwarven matters, $N. Kam Deepfury is a proven conspirator in the Thandol Span attack. King Magni''s good people lost their lives because of Deepfury''s deceit. The Humans might be content to let Deepfury rot in The Stockade but I will not sleep soundly at night until Deepfury is slain.',12340),
	 (377,5,5,'So long as a molester of the dead like Dextren Ward is permitted to live, justice stands betrayed. Return to me once Lord Ebonlocke''s sentence of death is carried out on that defiler, Ward. We shall give the families of the dead the closure they deserve and better yet, we will send a clear message to the House of Nobles in Stormwind.',12340),
	 (376,0,0,'Do try your best to keep yourself unharmed until I get you some armor.',12340),
	 (375,0,0,'Do you have five Duskbat Pelts and some Coarse Thread yet, $N?',12340),
	 (374,6,0,'Have you collected 10 Scarlet Insignia Rings yet, $c?',12340),
	 (373,0,0,'Yes? Is there something I can help you with?',12340),
	 (372,1,5,'You have not yet performed your duty, $c.  We cannot expect to carry out The Dark Lady''s plan with the Scarlet Crusade pestering our soldiers.  Bring about their deaths and perform your duty to Sylvanas!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (371,1,0,'I see you have returned but your task is not complete. Perhaps you are at ease with the mere humans interfering with The Dark Lady''s plan? Or perhaps you can heed the call of duty and slay Captain Vachon and his band of Scarlet Friars!',12340),
	 (370,1,0,'Young $C, you shouldn''t be wasting your time here in Brill when your people need you fighting for their cause. Now, take up arms and travel to the southwest, to the ruined tower, and slay Captain Perrine along with 3 Scarlet Zealots and 3 Scarlet Missionaries. We shall herd the Scarlet Crusade like cattle to their demise.',12340),
	 (369,6,0,'Do you have some venom from a Vicious Night Web Spider yet, $N? It''s the final component I need in order to test my experiment.',12340),
	 (367,5,0,'Have you collected 5 vials of darkhound blood yet, $N? Time is fleeting!',12340),
	 (368,6,0,'$N, were you able to obtain 5 Vile Fin Scales from the Murlocs?',12340),
	 (366,1,0,'Your masters are fools to send you here, for I will never again be a Scourge slave!',12340),
	 (365,6,6,'Deathguard Simmer sent word that you were going to provide me with some much needed reagents. Were you able to gather 10 pumpkins yet, $N?',12340),
	 (364,1,0,'You will not go far in this new life if you are unable to kill even the weakest of zombies, $n. Do not return until you have success to report.',12340),
	 (362,0,0,'Did you find Devlin?',12340),
	 (363,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (360,1,0,NULL,12340),
	 (361,1,0,'Yes?',12340),
	 (359,1,0,NULL,12340),
	 (357,0,0,'$N, have you acquired the book?',12340),
	 (358,0,0,'Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?',12340),
	 (356,1,0,'Do you have a report of your patrol?',12340),
	 (355,1,0,NULL,12340),
	 (354,0,0,'Do you have the remains of the Agamands? Are those cursed beasts finally destroyed?',12340),
	 (353,6,0,'You come all the way from Stormwind? I hear it''s getting dicey down there in the human lands, with brigands and orcs running about. A perfect place for a $C to prove his worth!',12340),
	 (351,1,0,'You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:$B$B"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover.  The beacon will take care of the rest!"',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (350,1,0,NULL,12340),
	 (349,1,0,'Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!$b$bMe speak with spirits and make he come, I do.$b$bBut other Gorilla-beast like spirit talkin'' too.  You protect Witch Doctor Unbagwa and I make he come to you.$b$bWitch Doctor Unbagwa want something first.  You bring a Gorilla Fang and me start spirit talking!',12340),
	 (347,6,6,'Do you have the Rethban Ore?',12340),
	 (348,0,0,'....mother?$b$b...so cold...$b$b...heading into the Twisting Nether...h-h-h-hold me mother....',12340),
	 (346,6,0,'Were you able to find the book?',12340),
	 (345,1,0,NULL,12340),
	 (344,1,0,NULL,12340),
	 (343,1,0,NULL,12340),
	 (342,6,0,'We just need three pages to finish off Chapter IV, $N.  Do you have pages 25, 26 or 27 yet?',12340),
	 (341,6,0,'Any luck with pages 18, 20, 21 or 24?  Those are the only ones we need to piece together Chapter III.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (340,1,0,'We still need pages 10, 11, 14 and 16 to complete Chapter II, $N.',12340),
	 (339,6,0,'I don''t suppose you were able to track down pages 1, 4, 6 and 8?  Those four are all we need to piece Chapter I back together.',12340),
	 (337,6,0,'Ooh! What''s that old book you have there? Can I see it??',12340),
	 (338,6,6,'Have you assembled the chapters yet, $N?',12340),
	 (336,5,5,'Can you not see that I am busy? My words must be heard! I am very important to the future of this Kingdom!$B$BOh... what have you there? Why it looks like a refreshing drink...',12340),
	 (335,6,6,'Wishock will soon garner enough support to cause us much grief. Were you able to obtain the Tear of Tilloa or Musquash Root yet?',12340),
	 (333,6,0,'You bring word from Mr. Bagley?',12340),
	 (334,1,0,'Are you here to buy clothes?',12340),
	 (332,2,0,'Greetings and welcome, $N. Have you yet tried one of our fine wines?',12340),
	 (331,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (330,1,0,NULL,12340),
	 (329,1,0,'Did you discover who knew Thorsen''s secret? Is there a traitor among us?',12340),
	 (328,1,0,'The strongbox is bound in bronze, very sturdy, and very heavy.',12340),
	 (324,6,6,'Did you find the lightforge iron you need?',12340),
	 (325,1,0,'Hello, $N. You haven''t been gone that long, but I see a fire in your eyes I did not see before.',12340),
	 (322,6,6,'How might I ply my craft for you, $C?',12340),
	 (323,1,1,'Battle hard, $Nn. And do not despair, for despair is evil''s greatest weapon.',12340),
	 (321,1,0,NULL,12340),
	 (320,6,0,'Did you get that Evershine?',12340),
	 (319,1,0,'Have you taken care of those wild animals?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (318,1,0,NULL,12340),
	 (317,1,1,'Preparations are going well.  How goes your hunting?',12340),
	 (315,6,6,'Do you have that shimmerweed?  I almost have a batch of stout ready to brew, and I want to try throwing the weed in with this mixture.',12340),
	 (314,0,0,'Vagash still terrorizes the herd! Please help us by killing the wretched beast.',12340),
	 (313,0,0,'Hey, $N.  Been to the Grizzled Den yet?  Those Wendigos can be fierce.',12340),
	 (312,6,6,'Were you able to get into my meat locker, $N?',12340),
	 (311,0,0,'Did you make the switch?',12340),
	 (309,1,0,NULL,12340),
	 (310,1,0,'The date on this barrel shows that it''ll soon be tapped.',12340),
	 (308,0,0,'Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (307,6,6,'Do you have that Miners'' Gear, $N?',12340),
	 (306,6,6,'Were you able to find Merrin? Did she send word?',12340),
	 (305,1,0,NULL,12340),
	 (304,6,6,'Were you able to locate Balgaras the Foul yet, $C? He has been evading us for quite some time.',12340),
	 (303,1,1,'Roggo has been unable to contact the reserve forces. We need offensive pressure on that Dark Iron encampment, $c. Now get back out there and serve your duty to King Magni!',12340),
	 (302,1,0,NULL,12340),
	 (301,25,0,'We Stormpikes don''t like being bothered with trivial matters, $C. I hope you brought news worthy of my valuable attention.',12340),
	 (299,6,6,'Have you uncovered the four fragments yet, $N?  Ados, Modr, Golm and Neru...',12340),
	 (298,1,0,'Oh, a progress report from the site? Very good!',12340),
	 (297,6,6,'Do you have those Idols? We must study them and report our findings to Ironforge!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (296,20,20,'Is Sarltooth dead? Have you redeemed the memory of the fallen?',12340),
	 (295,1,21,'I want to make those Mottled Scytheclaws and Mottled Razormaws pay for what they did. Have you killed 10 of each yet?',12340),
	 (294,1,0,'Kill 10 Mottled Raptors and 10 Mottled Screechers, $N. My co-workers did not deserve the fate that was brought upon them. It''s time to even the score.',12340),
	 (293,6,0,'What is that orb you have? It looks...soiled.',12340),
	 (292,6,0,'That drunk Fitzsimmons sent you to me? Well, you can tell him I don''t have any extra ale. He''s going to have to panhandle someone else!',12340),
	 (291,0,0,'Hmm... it would seem that my guards are becoming less discriminatory with petitioners. Well, what do you want? Make it quick.',12340),
	 (290,1,0,'This chest is securely locked.',12340),
	 (289,1,0,'In my dreams, I can sometimes hear the doomed moans of my brethren! Please, good sir, free them from the bonds and quiet their cries.',12340),
	 (288,1,1,'Oh, I''m so very thirsty! Won''t you buy a drink for this poor, pathetic fool?',12340),
	 (287,1,0,'You can''t find it? My directions were very clear! We don''t have much time, you''ve got to hurry! Don''t come back until you''ve found the cave.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (286,0,0,'Do you have the statuette?',12340),
	 (285,1,0,NULL,12340),
	 (283,1,0,NULL,12340),
	 (284,1,0,NULL,12340),
	 (280,1,0,'The top of the keg slowly twists off.',12340),
	 (281,1,0,NULL,12340),
	 (282,66,66,'Hail! Have a care, $N, the tunnel to Dun Morogh is infested with troggs and is not safe for travel.$b$bIf you haven''t any pressing business in Dun Morogh, I''ll have to ask you to remain in Anvilmar until the tunnel is safer.',12340),
	 (279,0,0,'Our merchants will not be safe until we are rid of Gobbler and those Murlocs.',12340),
	 (278,5,5,'Do you have the needed items? Time is of the essence!!',12340),
	 (275,1,0,'The Wetlands still weep, and the Fen Creepers still rage. Return to me when your task is done.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (276,1,0,'Your task is still at hand, young $C.',12340),
	 (277,1,0,'Do you have the Gnolls'' tools for fire?',12340),
	 (273,1,0,NULL,12340),
	 (274,6,0,'What is that you bring from Ashlan?',12340),
	 (272,1,0,'Have you formed your pendant for me to inspect, $N? If you need help in locating the parts, try asking the local populace for information. Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.',12340),
	 (270,1,0,NULL,12340),
	 (271,1,1,'Ah, $N! Back so soon? No doubt you''ve been at the hunt again? Don''t worry if you''ve had some setbacks, in the long run it will make you better!$B$B... You couldn''t get much worse, anyway...',12340),
	 (268,6,6,'Did you find who the Shadowy Figure was?',12340),
	 (269,1,0,'Rest, $gbrother:sister;. I can tell you have traveled far, and you bear a heavy burden. Can you tell me what casts that dark shadow over you?',12340),
	 (267,6,6,'Do you have 8 Trogg Stone Teeth to show me?  If not, there is still work to be done, $N.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (266,1,0,'The Scarlet Raven doesn''t see the business it used to, but we still do get travelers passing through.$B$BIf you can describe the person you''re looking for, maybe I''ll remember him.',12340),
	 (265,1,0,'Sometimes I''ll sell blank books to scholars and mages, or to anyone who wants to keep a journal.$B$BI remember well everyone to whom I sold a book within the last few months...',12340),
	 (264,1,0,'The stone is cold to the touch, but has obviously been abused. Trash litters the area; nicks and gashes decorate the relief atop the coffin; and the foliage around the grave has started to grow over the site.$b$bNo one cares for whoever is buried here, especially not any victims of the plague.',12340),
	 (263,1,6,'Back so soon? In case I didn''t make myself clear we need you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers, $N. Now go get''em, Trogg-Slayer!',12340),
	 (261,1,25,'The Scourge grows in power with the passing of each day. If you truly wish to halt its advances, then show me.',12340),
	 (262,1,0,'If you have something that belongs to the shadowy figure for whom you seek, then let me see it. I may be able to divine something of its owner.',12340),
	 (256,6,6,'Yes? Is there something I can do for you?',12340),
	 (257,1,1,'No luck? Don''t feel too bad, $N...$B$BNot everyone can be me.',12340),
	 (258,1,1,'It''s only natural to feel sorry for yourself when shown up by someone so new to this world. You shouldn''t feel bad, $N.$B$BHm? Did I get your name wrong?',12340),
	 (252,1,0,'Ah, is the note translated? Please, let me see it...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (253,6,6,'Have you yet found Eliza''s grave? Do you have the Embalmer''s heart?',12340),
	 (254,1,0,'',12340),
	 (255,1,6,'Have you had any luck?',12340),
	 (251,0,0,'A note from Abercrombie the hermit, eh? I don''t know him, though if he lives out at the graveyard then I do know his brains have rotted out!',12340),
	 (250,1,0,NULL,12340),
	 (249,5,5,'Hurry, $N, before my fears of Morganth spreading his power are made real!',12340),
	 (247,1,0,NULL,12340),
	 (248,1,0,'This jar once held a foul-smelling liquor, but now lies empty and forgotten on a pair of barrels.',12340),
	 (246,1,0,'Excuse me, $N, but we have a lot to keep our hands tied here. If you have nothing to report, then I must put my mind to other matters.',12340),
	 (243,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (244,1,0,NULL,12340),
	 (245,1,0,'You''d best be careful when dealing with the spiders, I''ve lost a few of my men to them, and trust me, it isn''t a pleasant sight to see a man hanging upside down in their webs after the venom has started to soften them up.$B$BI wouldn''t want to see one of the bugs having you for lunch.',12340),
	 (240,5,5,'$N, you''re here! Do you have my food?!?',12340),
	 (239,1,0,NULL,12340),
	 (238,1,0,'Yes, I think Luca is as disturbing as you do. It matters not - hand me the field sampling kit. I will need to make some adjustments to it in order to survey for the proper base materials.$b$bYou have the kit, don''t you?',12340),
	 (237,1,25,'We need more time, $r. Your orders are to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers. Keep the enemy under pressure until we are granted reinforcements. This is no time for idle behavior.',12340),
	 (235,1,0,NULL,12340),
	 (236,0,0,'Well? Did you manage to find the embers or did the Horde beat you to it and leave you crying?',12340),
	 (234,1,0,'Is there something I can help you with?',12340),
	 (233,6,0,'Yes? Do you have something for me?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (232,6,0,'Yes, and what may I assist you with?  Are you here on business for the Royal Apothecary Society, or have you arrived here merely to brighten my day?',12340),
	 (231,1,0,'Leave me be...',12340),
	 (229,1,0,NULL,12340),
	 (230,5,0,'You found what?? Please, let me see it...',12340),
	 (228,1,1,'I don''t blame you if you''re having trouble with him, $N. Some of our strongest Watchers have been lost to Mor''Ladim.',12340),
	 (227,1,0,NULL,12340),
	 (226,1,6,'You still hunting wolves...?',12340),
	 (225,1,0,NULL,12340),
	 (224,1,5,'Loch Modan is under siege, $N!  We need every able-bodied member of the Alliance to aid our cause.  Have you killed 10 Stonesplinter Troggs and 10 Stonesplinter Scouts yet?',12340),
	 (222,1,0,'Intimidating beasts aren''t they? But have no fear, $N, those who stand for the Light will never fall!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (223,0,0,'Yes, what is it? Make it quick, I''ve pressing matters to attend to.',12340),
	 (221,1,0,'Back so soon, $N? I hope you haven''t come to tell me you''ve given up.',12340),
	 (220,1,0,'Hello again, $N. You''re looking well.$B$BWhat brings you back to me so soon?',12340),
	 (219,1,0,'Yes?',12340),
	 (218,6,6,'$N! Any luck?',12340),
	 (217,1,1,'Grawmug and his two guards, Gnasher and Brawler, are still alive. Your mission is not complete until all 3 have been brought to death. The Dwarven empire is counting on you, $N.',12340),
	 (216,1,6,'Have you taken the fight to the Thistlefur?  With a clear path between our bases, our chances of claiming the whole of Ashenvale increase dramatically.',12340),
	 (215,1,0,NULL,12340),
	 (214,6,6,'Have you been reclaiming our land from the Defias gang? If so show me 10 Red Silk Bandanas as proof.',12340),
	 (213,5,5,'I need those stones, $n. By whatever means necessary! Just do it, don''t give me the details!$b$bIt''s about results, $n, nothing more, nothing less.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (212,5,5,'$N! Do you have that haunch? I must begin preparing it soon, or the banquet will be ruined!',12340),
	 (211,6,6,'Your task has been given to you, $N.  Do you have a shard from the lich''s phylactery as proof of the task being accomplished?',12340),
	 (210,1,0,'Hello! You brought me something?',12340),
	 (209,6,6,'Tough buggers, aren''t they? Well, have you had any luck? Sorry to seem impatient, but this has been a huge thorn in my side! Well?',12340),
	 (208,1,1,'I see you''re back, $g old bloke : lass;.  King Bangalash has caused me to come crawling back to camp many times.  Hang in there.',12340),
	 (207,1,0,'$N! Do you have the troll legends? I must know their secrets!',12340),
	 (206,0,0,'I give you my blessing. Mai''Zoth''s strength is matched only by his evil.',12340),
	 (205,1,0,'Do you have those fetishes, $N? They might hold the secret to Kurzen''s degradation...I must know!',12340),
	 (204,1,0,'I''m waiting on those remedies and that extract, $N.',12340),
	 (203,1,0,'I hope you''ve been successful in your hunting, $N. We won''t last long against him without your help.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (202,1,0,'Dare I hope that Kurzen and his defenders are dead, $N?',12340),
	 (200,1,0,NULL,12340),
	 (201,1,6,'Well?  Did you have any luck in locating the camp?',12340),
	 (199,6,0,'Did you happen to discover any clues, $N?',12340),
	 (197,6,6,'How goes the hunt for Tethis?  Tracked her all the way back to camp, did you?',12340),
	 (198,1,0,'Yes? What do you want? Oh, supplies from the goblins. Strange seeing a $R delivering them, usually they send their own. No matter... you didn''t touch them did you? Good good... we wouldn''t want anything to happen to our mines, oh no.',12340),
	 (196,1,0,'Bah! What are you doing standing around, $N! A true big game hunter never gives up once his prey is in his sights. Those Jungle Stalkers aren''t going to come running up to this campfire and throw themselves in it. Silly bloke.',12340),
	 (195,1,0,'A true hunter sets his focus on his prey. You, my friend, seem more concerned with chit-chatting around the campfire. Now get out there and kill 10 Lashtails before I go and rid the entire bloody jungle of them in one hunt.',12340),
	 (194,1,0,'I never met a hunter who got any kills by standing around the campfire - well, except for my father. Were you planning on killing those Stranglethorn Raptors or were you hoping they would die of old age?',12340),
	 (193,6,6,'Bhag''thera can prove to be an elusive beast.  How fares the hunt?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (191,1,0,'Go kill 10 panthers! Show us what you''ve got!',0),
	 (192,1,0,'What are you doing here, $n! You should be crawling through the brush, trying to kill 10 Shadowmaw Panthers. I thought you fancied yourself a big game hunter?',0),
	 (189,0,0,'You''ve had success I hope? All over the place, those trolls. Filthy devils.$b$bOh yes, that reminds me! Be sure to tell your friends, yes? We could use much assistance!',12340),
	 (190,1,25,'A true panther hunter would be out in the fields, trying to stalk his prey. Show some commitment to your goal, $c, and get back out there.',12340),
	 (188,6,6,'How goes the hunt for Sin''Dall?',12340),
	 (187,1,0,'You must kill 10 Elder Stranglethorn Tigers before I give you the final challenge that will determine if you are a true tiger hunting master.',12340),
	 (186,1,0,'If you strive for greater challenges you must first prove yourself with the task at hand. Return to me after you''ve killed 10 Stranglethorn Tigers.',12340),
	 (185,1,1,'I don''t feel confident in training you further, $n, until you have proven yourself skilled in slaying the youngest of the tigers first.',12340),
	 (184,5,0,'You have the deed to my farm?? That''s good news! Some ruffians stole it days ago... I thought it was gone for good!$b$bPlease, let me have it. We''re on our way out of Westfall and ain''t coming back any time soon, but if we do then we''ll need those papers...',12340),
	 (183,2,6,'How goes the hunt?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (180,6,6,'What news do you bring before the Court?',12340),
	 (181,6,6,'Were you able to convince Zzarc''Vul to lend us his monocle for our experiment?',12340),
	 (182,6,1,'From what I''ve learned, these trolls hail from the Frostmane clan. I''m afraid I don''t know much else about them that would be of any use to you, $N.',12340),
	 (179,11,11,'Wolves giving you a bit of trouble? You''d do well to avoid the fangs and claws and other sharp bits, yes?',12340),
	 (178,0,0,'I spoke to you through a pendant, you say? Hmm...give it to me, so that I might study it.',12340),
	 (177,6,6,'I showed Cog the beginnings of our star-viewing machine. He was impressed. Did you happen to find a reflective device?',12340),
	 (176,0,0,'Yes, Hogger has been a real pain for me and my men. You have something to report about the beast?',12340),
	 (175,1,0,NULL,12340),
	 (174,6,6,'Have you found a skilled engineer to create a bronze tube yet?',12340),
	 (173,1,0,'$N, how fares the hunt?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (172,1,0,NULL,12340),
	 (171,6,0,'It is a pleasure to see you again, $N. Have you attended to the duties you''ve volunteered for during Children''s Week?',12340),
	 (170,1,1,'Tenacious little buggers, aren''t they?',12340),
	 (169,6,6,'What do you have there, $R?',12340),
	 (168,6,6,'Were you able to retrieve any of my old co-worker''s Miners'' Union Cards?',12340),
	 (167,6,6,'Did you find any sign of my brother? Is there any hope after all this time?',12340),
	 (165,1,0,NULL,12340),
	 (166,6,6,'How goes the hunt for Edwin VanCleef?',12340),
	 (164,6,0,'You look a sturdy type, $C. Have you come to join our fight?',12340),
	 (163,1,0,'Ah, $N! Back so soon? No doubt you''ve been at the hunt again? Don''t worry if you''ve had some setbacks, in the long run it will make you better!$B$B...You couldn''t get much worse, anyway...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (162,2,0,'Peace and tranquility be upon you, stranger.  Why have you sought me out this day?',12340),
	 (161,6,0,'You say somethin'', sonny? Can''t hear a bloody thing besides the ringin'' in me ears. Say, what''s that you got there?',12340),
	 (160,6,0,'Abercrombie...? I don''t know a person of that name. You say you have a letter for me from this Abercrombie fellow?$B$BWell let''s have it then...',12340),
	 (159,0,0,'I need that Zombie Juice to keep me warm on these cold, dark nights. Did you get it for me?',12340),
	 (158,1,0,NULL,12340),
	 (157,0,0,'I need to string the Ghost Hair Thread along my door and my windows to keep out unwanted spirits. Did you get it for me?',12340),
	 (156,6,6,'Hi, $N. You have that rot blossoms for me yet?',12340),
	 (155,1,0,'What business do you have with me? I am a very busy man...',12340),
	 (154,6,6,'I sense that you have seen Blind Mary. You have my Comb...?',12340),
	 (153,1,1,'Bring me 15 red leather bandanas and I''ll pay you well.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (152,1,0,'Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.',12340),
	 (151,6,6,'Old Blanchy is on her last leg. Did you happen to find any oats for her?',12340),
	 (150,0,0,'Do you have those fins? Hurry, we need those murlocs driven from the lake!',12340),
	 (149,1,0,'Oh please, don''t look at me! I tore out these eyes with my own hands, but I can still feel your gaze!$B$BI''m hideous! Hideous! Please, look away!!',12340),
	 (148,1,0,NULL,12340),
	 (147,0,0,'Did you find the Collector? Did you discover whom he''s working for?',12340),
	 (146,6,6,'Ah, good to see you back, messenger. Shall I inform the Marshal that the Night Watch is on its way from Darkshire?',12340),
	 (145,6,6,'You appear to have traveled from afar, $C. What business do you have here in Darkshire?',12340),
	 (144,6,6,'Shall we expect the People''s Militia soon? Does Lord Stoutmantle''s news bode well?',12340),
	 (143,6,6,'Hail, $C. What business do you have with The People''s Militia?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (142,6,6,'$N, were you able to gather any information? Did you locate the messenger?',12340),
	 (141,6,0,'Did Master Shaw shed any light on things?',12340),
	 (140,1,0,NULL,12340),
	 (138,1,0,NULL,12340),
	 (139,1,0,NULL,12340),
	 (136,1,0,NULL,12340),
	 (135,6,0,'What business do you have with me? I am a very busy man. . .',12340),
	 (134,0,0,'Do you have my crate? If so, then please...give it to me quickly!',12340),
	 (133,0,0,'I think I hear a pack of Ghouls scurrying around the back of the house - I better put that effigy up quick! Did you get those Ghoul Ribs for me?',12340),
	 (132,6,0,'Good to see you back, $N. What did Wiley have to say for himself?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (130,1,0,NULL,12340),
	 (131,0,0,'Hello again, $N. Did Parker like the lunch I sent him?',12340),
	 (129,0,0,'Darcy sent me a lunch, did she? Such a kind heart she has. Well...let''s have it!',12340),
	 (128,1,25,'Return once you have slain 15 Blackrock Champions.',12340),
	 (127,0,0,'You have some sunfish for me, eh?',12340),
	 (126,0,0,'Yowler is a dangerous creature, $N. If you''re not ready for him, I understand.',12340),
	 (125,6,6,'Were you able to find my tools?',12340),
	 (124,1,0,'Yes? Is there something I can do for you?',12340),
	 (123,0,0,'What?!? We haven''t had our people working the Elwynn mines for months!$B$BLet me see that note you have...',12340),
	 (122,0,0,'I know that greedy Argus will send someone to collect his scales if I don''t give them to him soon. Have you found those scales yet?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (121,6,6,'Did the General send news? Are reinforcements on the way?',12340),
	 (120,6,6,'What have you there?',12340),
	 (119,0,0,'Great, you''re back! Did you get the shoes?',12340),
	 (118,0,0,'What''s that? Verner sent you, you say? Well give me his note. And SPEAK UP!',12340),
	 (117,94,94,'Hurry, my friend, move with haste $bIn order for our rich lager to taste $bMore like beer and less like stew, $bHops are needed to make the brew.',12340),
	 (116,25,25,'I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire. Bring those back to me and I will see to it you are rewarded.',12340),
	 (115,6,6,'How goes your conflict with the shadowcasters? Did you find the midnight orbs?',12340),
	 (114,0,0,'Did you deliver my letter to Tommy Joe? What did he say??',12340),
	 (113,6,0,'Well Junior Surveyor $n, has ol'' Pestlezugg got that report ready yet?',12340),
	 (112,0,0,'Do you have that crystal kelp? I''m sure Maybell is anxious to see her beau...',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (111,1,0,'I can''t wait to hear how my friends react!$B$BThey''ll never expect it',12340),
	 (110,1,0,NULL,12340),
	 (109,1,0,'An... Any luck??',12340),
	 (107,0,0,'You have a note from "Gramma" Stonefield, eh? I haven''t seen Mildred in years! I wonder what she has to say...',12340),
	 (106,5,0,'You have what?? Maybell is the light of my dull life. Hurry, let me see her letter!',12340),
	 (105,6,6,'Your task has been given to you, $N. Do you have a shard from the lich''s phylactery as proof of the task being accomplished?',12340),
	 (104,0,0,'Have you laid waste to the menace known as Old Murk-Eye yet? He has been spotted roaming the coastline of Westfall.$B$BReturn to me when the foul beast is dead.',12340),
	 (103,0,0,'The flame will not burn for long without oil, $N.',12340),
	 (102,6,6,'Have you collected 8 paws from those treacherous Gnolls yet?',12340),
	 (100,1,0,NULL,12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (101,1,1,'Bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom. For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.',12340),
	 (99,0,0,'Have you secured the Pyrewood Shackles yet, $N?',12340),
	 (97,1,5,'Yes, $N?',12340),
	 (98,6,6,'Yes, $N?',12340),
	 (96,1,0,'You''ve returned. Splendid!$B$BHow went your journey to Silverpine? Did it take you long?$B$BIt is hard for me to tell if you were successful there because so much of the land has become corrupt. Its stench overwhelms any good that you might have done. But small successes are sometimes as important as large ones. Purifying the water there was instrumental for you, and for all shamans.',12340),
	 (95,1,0,NULL,12340),
	 (94,1,0,'This Lion Statue has sat here for decades, and keeps a lonely watch over the infamous Tower of Ilgalar.$B$BThere is a depression at the base of the statue, where a gem or glyph might be set...',12340),
	 (93,3,3,'Hail, $N. Did you get those Gooey Spider Legs yet?',12340),
	 (92,0,0,'I still need five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.',12340),
	 (91,1,1,'Turn in 10 Shadowhide Pendants to me, and you shall be rewarded.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (90,6,6,'Were you able to find 10 Lean Wolf Flanks yet? How about the herbs from Felicia in Stormwind?',12340),
	 (88,6,6,'Did you see her yet? Did you get her?',12340),
	 (89,6,6,'This bridge isn''t going to build itself! Now where are those iron pikes and iron rivets?',12340),
	 (87,3,3,'Hello, $N. Have you found my necklace?',12340),
	 (86,6,6,'I don''t think it''s right feeding the boy who stole my necklace in the first place, but if that''s what it takes to get back what''s mine, then so be it!$b$bDo you have that boar meat?',12340),
	 (85,1,0,NULL,12340),
	 (84,1,0,'Ugh... I''m starving! Do you have that pie for me, $N?',12340),
	 (83,6,6,'I''m running low on linen, $N. Do you have any for me?',12340),
	 (82,5,5,'You''re Junior Surveyor $N, yes? Quickly now, there is a dire situation at hand! Do you have the insect parts that Fizzledowser said you would?!',12340),
	 (81,5,0,'If you''re not here to buy anything, and you''re not here to deliver anything, then you''re wasting my time! You better have that ripple!',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (80,6,6,'Back again, $N? What do you have this time?',12340),
	 (79,1,0,'This better be good, $C. Let me see what you have and tell me your tale. But by the Light, be quick about it. Darkshire''s defense is my number one priority. I have not the time to squander on dead-end leads.',12340),
	 (78,6,6,'Marshal Haggard sent you? Why didn''t you say so?$B$BAh, good ol'' Haggard. Poor chap is going to be completely blind before long. Anyway, let me see what you''ve got there.',12340),
	 (77,6,6,'I trust that your arrival here at our camp is to deliver the bottles of ripple that are integral to the task at hand, yes?',12340),
	 (76,1,0,'Hail, $N. What do you have to report? Have you scouted the Jasperlode Mine?',12340),
	 (75,6,6,'Did you find that page I mentioned, $N?',12340),
	 (74,6,6,'What have you got there? I cannot see. My eyesight is very bad. Put it in my hands.',12340),
	 (72,1,0,NULL,12340),
	 (71,0,0,'Hello, $N. Have you discovered the fates of Rolf and Malakai?',12340),
	 (70,6,6,'What have ya got there? Let me take a look at that. . .',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (69,1,0,NULL,12340),
	 (67,1,0,NULL,12340),
	 (68,6,6,'Ah, I remember you. You''re the one who was asking about that Stalvan fellow. Did you ever find what you were looking for?',12340),
	 (65,1,0,NULL,12340),
	 (66,1,0,NULL,12340),
	 (64,6,6,'Don''t suppose you were able to get my watch?',12340),
	 (63,1,0,'The brazier still reflects the ambient light from the are, and the flame shifts slightly as you move closer.$B$BThe corruption along the hills seems to have kept its distance, and besides the missing components, the brazier looks prepared for the ritual to summon a cleansed manifestation of water.',12340),
	 (62,1,0,'What do you have to report, $N? Have you been to the Fargodeep Mine?',12340),
	 (61,0,0,'Oh, a shipment from my brother? Splendid! Fortune truly shines on me today!',12340),
	 (60,0,0,'Did you gather those candles yet?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (59,2,0,'I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor.$b$bIf you have a marker for me, then I''d be happy to make you something.',12340),
	 (55,5,5,'Is Morbent Fel defeated?!',12340),
	 (56,1,6,'Have you killed those warriors and mages?',12340),
	 (57,1,25,'Return to me once you have killed 15 Skeletal Fiends and 15 Skeletal Horrors, $N.',12340),
	 (58,1,25,'I need your assistance, $N. Travel to the cemetery to the northwest and rid the eastern mausoleum of 20 Plague Spreaders.$B$BReturn to me when your task is complete.',12340),
	 (54,1,0,'You have word from McBride? Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.$b$bHere, let me have his papers...',12340),
	 (52,1,0,'Have you killed those wolves and bears?',12340),
	 (53,94,94,'Sure, I''ll sing it again for you, friend!$B$BMellifluous liquid clear as a baby''s tears$BTurns a lovely deep amber over the years$BBut before we proceed to get lit to the hilt$BA barrel of charred oak must be built.',12340),
	 (51,94,94,'An encore? Why for you, anything!$B$BNot yet filtered but freshly distilled$BLike unseeded land waiting there tilled.$BNext I will fashion our pile of charcoal$BDeliver a sycamore branch, that is your next goal.',12340),
	 (50,94,94,'An encore for you? Well sure friend!$B$BI''ll mix and mix till we have a mash$BFor this will be our own private stash$BA still must be fashioned of metal strong$BBring me some Truesilver so I can finish this song.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (49,94,94,'Encore? Well, sure!$B$BAmber is the hue of my life''s longest love$BLike the last embers of dusk in the sky above$BRetrieve for me so that my love shall be born$BOne sack of each: barley, rye and corn.',12340),
	 (48,94,94,'Hiccup! Ho ho! You want an encore?$B$BIn the land to the south where vines twist and creep$BLies a hidden well where the water runs deep$BPure as the Light''s sacred Daughter$BBring to me now some Holy Spring Water.',12340),
	 (47,0,0,'Psst! You have that Gold Dust for me...for me?',12340),
	 (46,0,0,'How goes the hunting, $N?',12340),
	 (45,1,0,NULL,12340),
	 (39,1,0,NULL,12340),
	 (40,1,0,NULL,12340),
	 (38,1,1,'Come back with the following ingredients: $b $b 3 Stringy Vulture Meat $b 3 Goretusk Snouts $b 3 Murloc Eyes $b 3 Okra',12340),
	 (37,1,0,NULL,12340),
	 (36,6,6,'I''m going to miss that Verna Furlbrow so much. I don''t suppose you happened to see her on your way here?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (35,1,0,NULL,12340),
	 (34,6,6,'Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?',12340),
	 (33,6,6,'Hey $N. How goes the hunt for diseased young wolves?',12340),
	 (32,6,0,'I''m sorry. I don''t know you... but from the look of things you have at least heard something of me. Now, what can I help you with? Do you have something for me?',12340),
	 (31,1,0,'Your return to Thunder Bluff is not without heralding, though I will need proof of your lessons learned in Moonglade before I will teach you your aquatic form.$B$BDo you have the Pendant of the Sea Lion?',12340),
	 (30,1,0,'Have you formed your pendant for me to inspect, $N? If you need help in locating the parts, try asking the local populace for information. Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.',12340),
	 (27,1,0,'',12340),
	 (26,1,0,'',12340),
	 (25,1,0,'You back already? What''s the situation out there - all cleared up now, thanks to you?',12340),
	 (24,6,0,'Greetings once again, $N! Have you come to show me proof of your hunt?',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (23,6,0,'Ah - $N - I was just thinking about you! How goes your hunting?',12340),
	 (22,5,4,'All I need for my famous meat pie are 8 Goretusk Livers!',12340),
	 (21,1,1,'I know it''s bloody work, $N, but it''s vital to the safety of Northshire. Are you ready to report?',12340),
	 (20,0,0,'Have you been slaying orcs, $N? If so, then show me...',12340),
	 (19,0,0,'Orc pressure from Blackrock is still tense. But have you at least rid us of Tharil''zun?',12340),
	 (15,1,6,'Have you been to the mines? Are you ready to report?',12340),
	 (16,0,0,'Farming is thirsty work, and I''m always looking for refreshing spring water.$B$BIf you have any, then I''m willing to make a trade.',12340),
	 (17,6,6,'Have you obtained the magenta fungus caps I need for my alchemical work? No caps - no reward!',12340),
	 (18,6,6,'Have you gathered those bandanas for me yet?',12340),
	 (14,1,1,'$N, now is no time for idle chatter. If you still wish to prove yourself to The People''s Militia you need to slay the Defias I notified you about earlier. Return to me when you have completed your duty.',12340);
INSERT INTO quest_request_items (ID,EmoteOnComplete,EmoteOnIncomplete,CompletionText,VerifiedBuild) VALUES
	 (13,1,1,'We have not time to talk, $N. The Defias Pillagers are denying the people of Westfall the peace and prosperity they deserve. Make sure at least 15 Defias Pillagers and 15 Defias Looters have been killed. That will send a clear message that corruption is not welcome here.',12340),
	 (12,1,1,'Perhaps I did not make myself clear, pledge. In order to prove your worth as a servant to The People''s Militia and to the Light you need to slay 15 Defias Trappers and 15 Defias Smugglers then return to me when the deed is done.',12340),
	 (11,0,0,'Hail, $N. Have you been killing Gnolls...?',12340),
	 (10,6,6,'Well, what news do you have?  You look like you''ve been in quite the fight... is Scrimshank alive?',12340),
	 (9,1,6,'Ah, I see you''re back! I hope you''ve been hard at work clearing those fields of those Harvest Watchers. Have you killed twenty yet?',12340),
	 (8,6,0,'Yes? Yes? What is it?$B$BThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name''s Renee if you need anything at all.',12340),
	 (7,1,6,'How goes the hunting, $N? Have you found and defeated those vermin?',12340),
	 (6,6,6,'Did you find Garrick''s shack? Are we finally free of that villain?',12340),
	 (5,1,0,'Oh, a shipment from my brother? Splendid! Fortune truly shines on me today!',12340),
	 (2,1,0,'Yes, mighty $C, I sensed your arrival. I trust you have more news to report to me about your hunt?',12340);
